L["/dui import - add a shared DaylightUI profile"] = "/dui import - 공유된 DaylightUI 프로필 추가"
L["/dui install - the setup guide: set this character up, or take the tour again"] = "/dui install - 설정 가이드: 이 캐릭터를 설정하거나 둘러보기를 다시 진행"
L["/dui leader - open or close the leader tools; /dui leader test (or test party) tries them with sample members"] = "/dui leader - 파티장 도구 열기/닫기; /dui leader test (또는 test party)로 샘플 구성원과 함께 시험"
L["/dui levelup - preview the level-up animation"] = "/dui levelup - 레벨 업 애니메이션 미리 보기"
L["/dui lock - finish moving"] = "/dui lock - 이동 마치기"
L["/dui loot - preview the loot feed"] = "/dui loot - 전리품 알림 미리 보기"
L["/dui notes - what's new"] = "/dui notes - 새로운 소식"
L["/dui npc - try the NPC window with a sample talk"] = "/dui npc - 샘플 대화로 NPC 창 체험"
L["/dui opens the settings."] = "/dui로 설정을 엽니다."
L["/dui platedebug - your target's nameplate's click area"] = "/dui platedebug - 대상 이름표의 클릭 영역"
L["/dui platefps - hide or show our nameplates and print addon time (testing)"] = "/dui platefps - DaylightUI 이름표를 숨기거나 표시하고 애드온 시간 출력 (테스트용)"
L["/dui reset - put every frame back"] = "/dui reset - 모든 창을 원래 위치로"
L["/dui sweep party, or /dui sweep raid"] = "/dui sweep party 또는 /dui sweep raid"
L["/dui sweep party|raid - step through sample looks for the party or raid frames, to check them"] = "/dui sweep party|raid - 파티 또는 공격대 개체창의 샘플 모양을 차례로 넘겨 확인"
L["/dui taint - the game's values DaylightUI has marked (for tracking down blocked actions)"] = "/dui taint - DaylightUI가 표시한 게임 값 (차단된 동작 추적용)"
L["/dui test - preview every frame with sample units (/dui test raid: with a raid of forty)"] = "/dui test - 샘플 유닛으로 모든 창 미리 보기 (/dui test raid: 40인 공격대로)"
L["/dui unlock - move frames"] = "/dui unlock - 창 이동"
L["/dui unlock lets you move frames; right-click a handle to put one back."] = "/dui unlock으로 창을 옮길 수 있습니다. 핸들을 오른쪽 클릭하면 원래 위치로 돌아갑니다."
L["/dui zone - preview the zone title"] = "/dui zone - 지역 제목 미리 보기"
L["0 leaves just the bars, with no outline round them."] = "0이면 테두리 없이 막대만 남습니다."
L["1 day"] = "1일"
L["1 item"] = "아이템 1개"
L["1 item is missing"] = "아이템 1개 없음"
L["1 new talent point"] = "새 특성 포인트 1"
L["1 setting matches."] = "설정 1개 일치."
L["1 slot left"] = "1칸 남음"
L["1 unrecognized buff on the group:"] = "파티에 인식되지 않은 강화 효과 1개:"
L["24-hour clock"] = "24시간제 시계"
L["2D portrait"] = "2D 초상화"
L["30 days"] = "30일"
L["3D portrait"] = "3D 초상화"
L["62% rather than 62, when the health text shows a percent."] = "생명력 텍스트가 백분율일 때 62 대신 62% 형식으로 표시합니다."
L["7 days"] = "7일"
L[">> You <<"] = ">> 당신 <<"
L["A bar ( | )"] = "막대 ( | )"
L["A big number in the middle of your screen counts down any pull your group starts, in place of the game's bar. Move it in unlock mode. In a dungeon or raid the game may keep its own bar for a countdown someone else starts."] = "파티가 시작한 전투 카운트다운을 게임의 막대 대신 화면 가운데 큰 숫자로 표시합니다. 잠금 해제 모드에서 옮길 수 있습니다. 던전이나 공격대에서는 다른 사람이 시작한 카운트다운에 게임이 자체 막대를 유지할 수 있습니다."
L["A bird on the world map at each flight master you can use: blue for Alliance, red for Horde, gold for both."] = "이용할 수 있는 비행 조련사마다 세계 지도에 새 아이콘을 표시합니다: 얼라이언스는 파란색, 호드는 빨간색, 양쪽 모두는 금색."
L["A border and shadow around each line."] = "각 줄 둘레의 외곽선과 그림자."
L["A border and shadow around the background."] = "배경 둘레의 외곽선과 그림자."
L["A border and shadow around the boxes."] = "상자 둘레의 외곽선과 그림자."
L["A border and shadow around the meter's own window."] = "측정기 창 둘레의 외곽선과 그림자."
L["A border and shadow around the panel behind the bar. When off, the panel is a plain fill."] = "막대 뒤 패널 둘레의 외곽선과 그림자. 끄면 패널이 단색으로 채워집니다."
L["A border and shadow around the second meter's window."] = "두 번째 측정기 창 둘레의 외곽선과 그림자."
L["A bright line along the cooldown shade's moving edge."] = "재사용 대기시간 음영의 움직이는 가장자리를 따라 밝은 선."
L["A buff's exact name"] = "강화 효과의 정확한 이름"
L["A buff's time turns orange and gently pulses in its last 5 seconds."] = "강화 효과의 남은 시간이 마지막 5초 동안 주황색으로 바뀌고 부드럽게 깜박입니다."
L["A button on the game's class trainer window that learns every spell you can afford in one click. The DaylightUI style NPC window's trainer page has its own, so this is for the game's window (NPC window > Trainer window off)."] = "게임의 직업 상급자 창에 살 수 있는 모든 주문을 한 번의 클릭으로 배우는 버튼을 추가합니다. DaylightUI 스타일 NPC 창의 상급자 페이지에는 자체 버튼이 있으므로, 이것은 게임 창용입니다 (NPC 창 > 상급자 창 끄기)."
L["A clean chat panel with class colors, timestamps and copyable links."] = "직업 색상, 시간 표시, 복사 가능한 링크가 있는 깔끔한 대화 패널."
L["A color over the icon while the mouse is over it."] = "마우스를 올렸을 때 아이콘 위에 덮는 색상."
L["A color over the icon while you press it."] = "누르고 있을 때 아이콘 위에 덮는 색상."
L["A copy of the one in use, layout and all."] = "사용 중인 프로필의 사본 (배치 포함)."
L["A countdown icon for each totem you have down."] = "설치한 토템마다 카운트다운 아이콘."
L["A crown on top of the portrait ring (or over the name tab) for the party or raid leader."] = "파티장 또는 공격대장에게 초상화 고리 위 (또는 이름 탭 위)에 왕관을 표시합니다."
L["A dark edge around the letters on DaylightUI's frames, so text stays readable over a busy world."] = "DaylightUI 창의 글자 둘레에 어두운 테두리를 넣어, 복잡한 배경에서도 텍스트가 잘 읽히게 합니다."
L["A dash ( - )"] = "대시 ( - )"
L["A debuff you can remove, as tiles show it."] = "타일에 표시되는 것처럼 해제할 수 있는 약화 효과."
L["A done objective stays, dimmed with a tick. When off, it disappears once it's done."] = "완료한 목표는 체크 표시와 함께 흐리게 남습니다. 끄면 완료 즉시 사라집니다."
L["A dot ( · )"] = "점 ( · )"
L["A dragon wrapped around the end of an elite's or boss's bar, in gold, or silver for a rare."] = "정예나 우두머리의 막대 끝을 감싼 용 장식: 금색, 희귀는 은색."
L["A frame dropped in unlock mode, a spell placed in the Cooldown Manager editor, a click-cast bound. The game has no sound of its own for these."] = "잠금 해제 모드에서 창을 내려놓을 때, 재사용 대기시간 관리자 편집기에 주문을 배치할 때, 클릭 시전을 지정할 때. 게임에는 이런 소리가 없습니다."
L["A framed panel behind the bar."] = "막대 뒤의 테두리 패널."
L["A friendly player's <guild> under their name, smaller."] = "우호적인 플레이어의 이름 아래 <길드>를 작게 표시합니다."
L["A gradient per point (Gradients page)"] = "포인트마다 그라데이션 (그라데이션 페이지)"
L["A green sliver on the health bar for heals on their way, as the unit frames show them."] = "들어오는 치유를 생명력 막대에 초록색 조각으로 표시합니다 (개체창과 같은 방식)."
L["A kill or item for a quest shows for a moment at the top of the screen, small, with a progress bar. Turn it off to see the game's yellow line instead. Move it in unlock mode."] = "퀘스트용 처치나 아이템을 화면 위쪽에 진행 막대와 함께 작게 잠시 표시합니다. 끄면 게임의 노란 문구가 대신 나옵니다. 잠금 해제 모드에서 옮길 수 있습니다."
L["A line on enemy health bars where your finishing moves start to work. The bar's end up to it lights up in your accent color once the enemy is that low. Your class: warriors (Execute) and paladins (Hammer of Wrath)."] = "적 생명력 막대에 마무리 기술이 통하기 시작하는 지점을 선으로 표시합니다. 적의 생명력이 그만큼 낮아지면 막대 끝에서 선까지가 강조 색상으로 빛납니다. 해당 직업: 전사(마무리 일격), 성기사(천벌의 망치)."
L["A mana, rage or energy bar under the health. When off, the frame is all health."] = "생명력 아래 마나, 분노 또는 기력 막대. 끄면 창 전체가 생명력이 됩니다."
L["A mark just left of the bar of anything your quests still need. Not inside instances."] = "퀘스트에 아직 필요한 대상은 막대 바로 왼쪽에 표시합니다. 인스턴스 안에서는 표시되지 않습니다."
L["A member's border turns red while something is attacking them."] = "무언가에게 공격받는 동안 구성원의 테두리가 빨갛게 변합니다."
L["A member's ring (or name tab without a portrait) turns red while something is attacking them."] = "무언가에게 공격받는 동안 구성원의 고리 (초상화가 없으면 이름 탭)가 빨갛게 변합니다."
L["A name for the new group:"] = "새 그룹 이름:"
L["A name for the new profile (a copy of %s):"] = "새 프로필 이름 (%s의 사본):"
L["A new profession"] = "새 전문 기술"
L["A new profile, made from %s with your picks."] = "%s에서 선택한 대로 만든 새 프로필."
L["A new zone's name rises in at the top of the screen with a thin line under it, then the subzone and PvP status; a subzone shows just its name, small. It replaces the game's zone text. Follows Motion effects (General > Appearance)."] = "새 지역에 들어서면 화면 위쪽에 지역 이름이 얇은 밑줄과 함께 떠오르고, 이어서 하위 지역과 PvP 상태가 나옵니다. 하위 지역은 이름만 작게 표시됩니다. 게임의 지역 문구를 대신합니다. 모션 효과(일반 > 모양)를 따릅니다."
L["A note for %s:"] = "%s에 대한 쪽지:"
L["A pale sliver on the health bar for an absorb shield, as the unit frames show them."] = "흡수 보호막을 생명력 막대에 옅은 조각으로 표시합니다 (개체창과 같은 방식)."
L["A panel behind the whole bar, so its buttons sit on one strip."] = "막대 전체 뒤에 패널을 깔아 버튼이 한 줄에 놓이게 합니다."
L["A panel behind the whole bar."] = "막대 전체 뒤의 패널."
L["A player's <guild> under their name, smaller."] = "플레이어 이름 아래 <길드>를 작게 표시합니다."
L["A player's casts in their class color, or their class's gradient with a two-color fill. Creatures' casts keep the fill style. Not with the Daylight gradient."] = "플레이어의 시전은 직업 색상, 또는 2색 채우기일 때 직업 그라데이션으로 표시합니다. 생물의 시전은 채우기 스타일을 따릅니다. Daylight 그라데이션과는 함께 쓸 수 없습니다."
L["A player's name in their class color; other units in their reaction's color."] = "플레이어 이름은 직업 색상, 다른 유닛은 관계 색상으로 표시합니다."
L["A pressed button's icon sinks in a little and springs back as you let go."] = "누른 버튼의 아이콘이 살짝 들어갔다가 손을 떼면 튀어나옵니다."
L["A pulsing border while the spell's proc alert is up."] = "주문의 발동 알림이 떠 있는 동안 깜박이는 테두리."
L["A quest ready to hand in shows its title alone. A timed quest never folds."] = "완료 보고할 준비가 된 퀘스트는 제목만 표시합니다. 시간제한 퀘스트는 접히지 않습니다."
L["A quest you've failed, like a timed one that ran out."] = "시간이 다 된 시간제한 퀘스트처럼 실패한 퀘스트."
L["A ring over the outer end. Class icons show for players; NPCs show their face. Needs a frame at least 20 tall."] = "바깥쪽 끝에 고리를 표시합니다. 플레이어는 직업 아이콘, NPC는 얼굴이 나옵니다. 창 높이가 20 이상이어야 합니다."
L["A round badge with their portrait, or a slim bar with the portrait beside it and the name above."] = "초상화가 있는 둥근 배지, 또는 옆에 초상화와 위에 이름이 있는 얇은 막대."
L["A second damage meter in its own window, for two lists at once: healing beside damage, say. Hover it for the same buttons."] = "별도 창의 두 번째 피해량 측정기로 목록 두 개를 동시에 봅니다: 피해 옆에 치유량 같은 식으로. 마우스를 올리면 같은 버튼이 나옵니다."
L["A set already has that name."] = "이미 같은 이름의 세트가 있습니다."
L["A shield: the bar empties as it soaks damage, with the amount left on it. Or by its time, like any buff."] = "보호막: 피해를 흡수할수록 막대가 줄어들고 남은 양이 표시됩니다. 또는 다른 강화 효과처럼 시간으로."
L["A skill going up shows its new rank, out of its cap: Tailoring 152 / 225. More skill-ups move the same line on."] = "기술이 오르면 새 숙련도를 최대치와 함께 표시합니다: 재봉술 152 / 225. 더 오르면 같은 줄이 갱신됩니다."
L["A slash ( / )"] = "빗금 ( / )"
L["A slim bar under the tooltip of a player or creature."] = "플레이어나 생물 툴팁 아래 얇은 막대."
L["A slot at or under this much durability gets an amber dot and says Repair soon."] = "내구도가 이 값 이하인 칸에는 주황색 점이 붙고 '곧 수리 필요'라고 표시됩니다."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner of bank items, until the item is bound to you."] = "은행 아이템의 왼쪽 위 모서리에 작게 BoE(착용 시 귀속) 또는 BoU(사용 시 귀속)를 표시합니다. 아이템이 귀속되면 사라집니다."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound to you."] = "왼쪽 위 모서리에 작게 BoE(착용 시 귀속) 또는 BoU(사용 시 귀속)를 표시합니다. 아이템이 귀속되면 사라집니다."
L["A small BoE (binds when equipped) or BoU (binds when used) in the top left corner, until the item is bound."] = "왼쪽 위 모서리에 작게 BoE(착용 시 귀속) 또는 BoU(사용 시 귀속)를 표시합니다. 아이템이 귀속되면 사라집니다."
L["A small Copy button at the top-right of the chat. It opens the tab's text so you can select it and press Ctrl+C. /dui copy does the same."] = "대화창 오른쪽 위의 작은 복사 버튼입니다. 탭의 텍스트를 열어 선택하고 Ctrl+C를 누를 수 있습니다. /dui copy도 같습니다."
L["A small badge at the foot of the portrait (or the frame's corner without one), colored by how hard the unit is for you."] = "초상화 아래 (초상화가 없으면 창 모서리)에 유닛의 난이도에 따라 색이 바뀌는 작은 배지."
L["A small badge at the foot of the portrait, colored by how hard the unit is for you. Needs the portrait or the name tab."] = "초상화 아래에 유닛의 난이도에 따라 색이 바뀌는 작은 배지. 초상화나 이름 탭이 필요합니다."
L["A small bar beside each party member who has a pet out. Your own pet keeps its own frame."] = "소환수를 꺼낸 파티원 옆에 작은 막대. 당신의 소환수는 자체 창을 유지합니다."
L["A small crown on the raid leader's tile."] = "공격대장 타일에 작은 왕관."
L["A small crown tab beside your party or raid frames while you lead the group or assist in a raid. It opens ready check, role check, a pull timer, target and world markers, and Everyone is assist. When off, these are only in the game's slash commands."] = "파티장이거나 공격대에서 승급자일 때 파티 또는 공격대 창 옆에 작은 왕관 탭이 나옵니다. 전투 준비, 역할 확인, 전투 카운트다운, 대상 및 위치 표시기, 모두 승급을 엽니다. 끄면 게임의 슬래시 명령어로만 쓸 수 있습니다."
L["A small dot in the top right corner on bank items that are part of one of your equipment sets."] = "장비 구성에 포함된 은행 아이템의 오른쪽 위 모서리에 작은 점."
L["A small dot in the top right corner on items that are part of one of your equipment sets."] = "장비 구성에 포함된 아이템의 오른쪽 위 모서리에 작은 점."
L["A small gray line at the bottom of spell and item tooltips with its ID: handy for macros, other addons and bug reports. Buff and debuff icons use the game's own tooltip, which can't show it."] = "주문과 아이템 툴팁 아래에 ID를 작은 회색 줄로 표시합니다: 매크로, 다른 애드온, 버그 신고에 유용합니다. 강화 및 약화 효과 아이콘은 게임 자체 툴팁을 써서 표시할 수 없습니다."
L["A small icon in a corner for a debuff you can remove, edged in its type's color."] = "해제할 수 있는 약화 효과를 모서리에 작은 아이콘으로, 종류별 색상 테두리와 함께 표시합니다."
L["A small mana, rage or energy number on the power bar."] = "상태 막대에 작은 마나, 분노 또는 기력 숫자."
L["A small pet bar beside each party member whose pet is out."] = "소환수를 꺼낸 파티원 옆에 작은 소환수 막대."
L["A small skull on the portrait once your damage over time is enough to finish the target."] = "지속 피해로 대상을 마무리할 수 있을 때 초상화에 작은 해골을 표시합니다."
L["A small skull past the bar's end once your damage over time is enough to finish that enemy."] = "지속 피해로 그 적을 마무리할 수 있을 때 막대 끝 너머에 작은 해골을 표시합니다."
L["A small soft drop shadow under text."] = "텍스트 아래 작고 부드러운 그림자."
L["A small square left of the frame: red while your pet is unhappy, yellow while content, green while happy. Hover for its damage, loyalty and diet."] = "창 왼쪽의 작은 사각형: 소환수가 불만족이면 빨간색, 만족이면 노란색, 행복하면 초록색. 마우스를 올리면 피해, 충성도, 먹이를 보여 줍니다."
L["A small tag after an elite, dungeon, raid or PvP quest's title, here and in the quest log on the map."] = "정예, 던전, 공격대, PvP 퀘스트 제목 뒤에 작은 태그를 붙입니다. 여기와 지도의 퀘스트 목록 모두."
L["A small time at the bottom of the map. Hover it for both local and server time."] = "지도 아래에 작은 시간. 마우스를 올리면 지역 시간과 서버 시간을 모두 보여 줍니다."
L["A small zone name over each group of quests, the zone you're in first."] = "퀘스트 묶음마다 위에 작은 지역 이름, 현재 지역이 먼저."
L["A soft glow in the threat color around the health bar."] = "생명력 막대 둘레에 위협 색상의 은은한 빛."
L["A soft light behind the arrow, in its color."] = "화살표 뒤에 같은 색의 은은한 빛."
L["A soft light in the line's color runs across it as it comes in or adds up."] = "줄이 들어오거나 합산될 때 그 줄의 색으로 은은한 빛이 가로지릅니다."
L["A soft light round the frame in the debuff's type color."] = "창 둘레에 약화 효과 종류 색상의 은은한 빛."
L["A soft light round the tile in the debuff's type color."] = "타일 둘레에 약화 효과 종류 색상의 은은한 빛."
L["A soft shadow round each button."] = "각 버튼 둘레의 부드러운 그림자."
L["A soft, minimal interface."] = "부드럽고 미니멀한 인터페이스."
L["A soft, warm chime when a tracked quest is ready to hand in."] = "추적 중인 퀘스트를 완료 보고할 수 있을 때 부드럽고 따뜻한 알림음."
L["A space"] = "공백"
L["A spell that just lit up, like Overpower or Execute."] = "제압이나 마무리 일격처럼 방금 활성화된 주문."
L["A spell with charges: the bar is cut into one piece per charge."] = "충전 주문: 충전마다 한 칸씩 막대가 나뉩니다."
L["A spell's icon pops and lights up once when it comes off a real cooldown (never for the global cooldown). Needs Motion effects (General > Appearance)."] = "실제 재사용 대기시간이 끝나면 주문 아이콘이 한 번 튀어오르며 빛납니다 (전역 재사용 대기시간은 제외). 모션 효과(일반 > 모양)가 필요합니다."
L["A spell's icon turns gray while it's on cooldown. The global cooldown doesn't count."] = "재사용 대기 중인 주문 아이콘을 회색으로 표시합니다. 전역 재사용 대기시간은 제외합니다."
L["A square minimap in the panel. Scroll to zoom."] = "패널 안의 사각형 미니맵. 스크롤로 확대 및 축소합니다."
L["A stun, fear, polymorph and the like, as a bigger icon beside the bar's end."] = "기절, 공포, 변이 등을 막대 끝 옆에 큰 아이콘으로."
L["A symbol on the world map at each boat dock and zeppelin tower. Hover it to see where it goes."] = "세계 지도의 배 선착장과 비행선 탑마다 기호를 표시합니다. 마우스를 올리면 행선지가 나옵니다."
L["A symbol on the world map at each dungeon and raid entrance. Hover it for the name."] = "세계 지도의 던전과 공격대 입구마다 기호를 표시합니다. 마우스를 올리면 이름이 나옵니다."
L["A thin bar under the name."] = "이름 아래 얇은 막대."
L["A thin line across the bars where your threat would pull it: 110% of the tank's in melee, 130% at range. Not shown on a boss, whose numbers the game keeps hidden."] = "위협이 몹을 끌어올 지점에 얇은 선을 긋습니다: 근접에서는 방어 전담의 110% 수준, 원거리에서는 130% 수준. 게임이 수치를 숨기는 우두머리에게는 표시되지 않습니다."
L["A thin mana strip along the bottom of the power bar while a form hides your mana."] = "변신으로 마나가 가려진 동안 상태 막대 아래쪽에 얇은 마나 띠."
L["A thin mana, rage or energy bar at the foot of each tile."] = "각 타일 아래쪽에 얇은 마나, 분노 또는 기력 막대."
L["A thin outline on chat text."] = "대화 텍스트에 얇은 외곽선."
L["A thin power bar under each pet's health."] = "각 소환수의 생명력 아래 얇은 상태 막대."
L["A thin strip under the minimap: gold, gear, bag space, friends online. Hover one for details, click it to open its window."] = "미니맵 아래 얇은 띠: 골드, 장비, 가방 공간, 접속 중인 친구. 마우스를 올리면 자세히, 클릭하면 해당 창이 열립니다."
L["A thinner outline leaves more of each pip for the color. Set to 0 for none."] = "외곽선이 얇을수록 각 칸에 색이 더 많이 남습니다. 0이면 없음."
L["A tooltip for something in the world (a creature, a player, a mailbox) fades away slowly after the mouse leaves it, as the game does. When off, it's gone at once."] = "월드의 무언가(생물, 플레이어, 우체통)에 대한 툴팁이 마우스가 떠난 뒤 게임처럼 천천히 사라집니다. 끄면 바로 사라집니다."
L["A trail of small diamonds from your feet to the marker, drifting toward it. Like the marker, it fades away once you're in the quest's area on the map."] = "발밑에서 표시기까지 작은 다이아몬드가 줄지어 그쪽으로 흘러갑니다. 표시기처럼 지도상 퀘스트 지역 안에 들어서면 사라집니다."
L["A two-minute tour of everything DaylightUI does, picking as you go. Nothing is saved until you finish."] = "DaylightUI가 하는 모든 것을 2분 만에 둘러보며 하나씩 고릅니다. 마칠 때까지는 아무것도 저장되지 않습니다."
L["A warm line of light spreads across the top of the screen, your new level rolls in and what you gained fades in under it, in place of the game's banner. Follows Motion effects (General > Appearance)."] = "화면 위쪽에 따뜻한 빛줄기가 퍼지고, 새 레벨이 굴러 들어오며 얻은 것이 그 아래 서서히 나타납니다. 게임의 배너를 대신합니다. 모션 효과(일반 > 모양)를 따릅니다."
L["A warning when your health or mana drops low."] = "생명력이나 마나가 낮아지면 경고."
L["A word when a fight starts and ends."] = "전투가 시작되고 끝날 때 한마디."
L["AFK"] = "자리 비움"
L["AVOIDABLE"] = "회피 가능"
L["AWAY"] = "자리 비움"
L["Abandon"] = "포기"
L["Abandon \"%s\"?"] = "\"%s\" 퀘스트를 포기할까요?"
L["Abandon?"] = "포기할까요?"
L["About 1 in %d of your attacks hits for double damage."] = "공격 %d번 중 약 1번은 두 배의 피해를 줍니다."
L["About 1 in %d of your shots hits for double damage."] = "사격 %d번 중 약 1번은 두 배의 피해를 줍니다."
L["About 1 in %d of your spells lands a critical hit for half again as much."] = "주문 %d번 중 약 1번은 극대화로 1.5배의 효과를 냅니다."
L["Above"] = "위"
L["Above or below the frame, the bar is as wide as the frame. Off: the Width below."] = "창 위나 아래에 있을 때 막대 너비가 창과 같습니다. 끄면 아래 너비를 씁니다."
L["Above or below the frame: moves the bar sideways from the middle."] = "창 위나 아래에 있을 때: 막대를 가운데에서 좌우로 옮깁니다."
L["Above or below the frame: moves the bar up or down."] = "창 위나 아래에 있을 때: 막대를 위아래로 옮깁니다."
L["Above the frame"] = "창 위"
L["Above the health bar"] = "생명력 막대 위"
L["Above the name tab by default, running inward. Yours come first."] = "기본은 이름 탭 위, 안쪽으로 이어집니다. 당신의 것이 먼저 나옵니다."
L["Above your debuffs, from the right."] = "약화 효과 위, 오른쪽부터."
L["Absorb shields"] = "흡수 보호막"
L["Absorbs"] = "흡수"
L["Accent"] = "강조"
L["Accent color"] = "강조 색상"
L["Accent follows Appearance, including the Daylight gradient."] = "강조 색상은 Daylight 그라데이션을 포함해 모양 설정을 따릅니다."
L["Accent follows the accent you picked on the General page, gradient and all."] = "강조 색상은 일반 페이지에서 고른 강조 색상을 그라데이션까지 그대로 따릅니다."
L["Accent follows your accent color (General > Appearance), or pick your own."] = "강조 색상은 당신의 강조 색상(일반 > 모양)을 따르거나, 직접 고를 수 있습니다."
L["Accept"] = "수락"
L["Accept key"] = "수락 키"
L["Accept quests automatically"] = "퀘스트 자동 수락"
L["Account"] = "계정"
L["Achievement announcements."] = "업적 알림."
L["Achievement color"] = "업적 색상"
L["Achievements"] = "업적"
L["Across"] = "가로"
L["Across the bar"] = "막대 가로질러"
L["Across the bar keeps it inside. Any other spot puts it there, on or round the frame, so a long name has room. You can also drag it in Design mode."] = "막대 가로질러는 막대 안에 둡니다. 다른 위치는 창 위나 둘레의 그 자리에 두어 긴 이름도 들어갑니다. 디자인 모드에서 끌어 옮길 수도 있습니다."
L["Across the bar keeps the alignment below. Beside the tile needs space between tiles."] = "막대 가로질러는 아래 정렬을 따릅니다. 타일 옆은 타일 사이에 공간이 필요합니다."
L["Across, you shown, by role, icons in corners"] = "가로, 나 표시, 역할별, 모서리 아이콘"
L["Action Bar 1"] = "행동 단축바 1"
L["Action Bar 2"] = "행동 단축바 2"
L["Action Bar 3"] = "행동 단축바 3"
L["Action Bar 4"] = "행동 단축바 4"
L["Action Bar 5"] = "행동 단축바 5"
L["Action Bar 6"] = "행동 단축바 6"
L["Action Bar 7"] = "행동 단축바 7"
L["Action Bar 8"] = "행동 단축바 8"
L["Action Bars"] = "행동 단축바"
L["Action bars"] = "행동 단축바"
L["Activate"] = "활성화"
L["Activate this set first."] = "먼저 이 세트를 활성화하세요."
L["Active spell"] = "활성 주문"
L["Active spell color"] = "활성 주문 색상"
L["Active spell opacity"] = "활성 주문 투명도"
L["Add"] = "추가"
L["Add a friend: a BattleTag (Name#1234) or a character's name."] = "친구 추가: BattleTag(Name#1234) 또는 캐릭터 이름."
L["Add a group"] = "그룹 추가"
L["Add friend"] = "친구 추가"
L["Add to favorites"] = "친한 친구에 추가"
L["AddOns"] = "애드온"
L["Added with Add piece in Design mode. Drag it on the preview to move it. Up to three parts in one line, each in its own color."] = "디자인 모드에서 요소 추가로 넣었습니다. 미리 보기에서 끌어 옮기세요. 한 줄에 최대 세 부분, 각각 다른 색으로."
L["Added with Add piece in Design mode: one more row of auras, with its own filter."] = "디자인 모드에서 요소 추가로 넣었습니다: 자체 필터를 가진 오라 한 줄 더."
L["Addon button drawer"] = "애드온 버튼 서랍"
L["Addon options (Ace3)"] = "애드온 설정 (Ace3)"
L["Addons' minimap buttons and the game's addon menu are gathered into one drawer. The button in the map's bottom-right corner opens it."] = "애드온의 미니맵 버튼과 게임의 애드온 메뉴를 한 서랍에 모읍니다. 지도 오른쪽 아래 버튼으로 엽니다."
L["Adds a warm band inside the black outline, lit along the top. When off, the border is a plain dark line."] = "검은 외곽선 안에 위쪽이 밝은 따뜻한 띠를 더합니다. 끄면 테두리가 단순한 어두운 선입니다."
L["Adds about %.0f damage per second to your melee attacks."] = "근접 공격에 초당 약 %.0f의 피해를 더합니다."
L["Adds about %.0f damage per second to your shots."] = "사격에 초당 약 %.0f의 피해를 더합니다."
L["Adds up to %.0f to your heals."] = "치유량을 최대 %.0f 늘립니다."
L["Adds up to %.0f to your spells' damage."] = "주문 피해를 최대 %.0f 늘립니다."
L["Adventure"] = "모험"
L["Affliction"] = "고통"
L["After /reload, the last messages in each chat tab come back, above a gray line."] = "/reload 후 각 대화 탭의 마지막 메시지가 회색 선 위로 다시 나타납니다."
L["After a login or /reload the UI starts invisible and glides in. Anything set to fade ends faded."] = "로그인이나 /reload 후 UI가 보이지 않는 상태에서 서서히 나타납니다. 흐려지도록 설정된 것은 흐려진 채로 끝납니다."
L["After a player's guild name."] = "플레이어의 길드 이름 뒤."
L["After combat"] = "전투 후"
L["After the fight"] = "전투가 끝난 뒤"
L["Aggro"] = "위협"
L["Aggro color"] = "위협 색상"
L["Aggro colors"] = "위협 색상"
L["Agility"] = "민첩성"
L["Ah, a fresh face. Goldshire isn't what it was, with kobolds in every mine. Still, a man has to keep his shop."] = "아, 새 얼굴이군. 광산마다 코볼트가 들끓으니 황금골도 예전 같지 않아. 그래도 가게는 지켜야지."
L["Alfa Slab One"] = "Alfa Slab One"
L["Alignment"] = "정렬"
L["All"] = "전체"
L["All %d spells snapped together"] = "주문 %d개 모두 붙였습니다"
L["All activities"] = "모든 활동"
L["Show all"] = "모두 보기"
L["%d activities"] = "활동 %d개"
L["All addons: %.3f ms"] = "모든 애드온: %.3f ms"
L["All bars"] = "모든 막대"
L["All characters"] = "모든 캐릭터"
L["All debuffs"] = "모든 약화 효과"
L["All donators"] = "모든 후원자"
L["All four extra aura groups are in use: remove one first."] = "추가 오라 그룹 네 개를 모두 쓰고 있습니다: 먼저 하나를 지우세요."
L["All four extra texts are in use: remove one first."] = "추가 텍스트 네 개를 모두 쓰고 있습니다: 먼저 하나를 지우세요."
L["All frames are back in their default places."] = "모든 창이 기본 위치로 돌아갔습니다."
L["All points"] = "모든 포인트"
L["All quests"] = "모든 퀘스트"
L["All set"] = "준비 완료"
L["All slots"] = "모든 칸"
L["All time"] = "전체 기간"
L["All tracked quests"] = "추적 중인 모든 퀘스트"
L["All your bags in one window, profession bag and keyring included. It opens the same way the game's bags do."] = "전문 기술 가방과 열쇠고리를 포함한 모든 가방을 한 창에. 게임 가방과 같은 방법으로 열립니다."
L["Almost ready at"] = "거의 준비됨 기준"
L["Almost ready color"] = "거의 준비됨 색상"
L["Almost there"] = "거의 다 왔어요"
L["Also destroys %s."] = "%s도 파괴됩니다."
L["Alt"] = "ALT"
L["Alt-click on a quest"] = "퀘스트를 Alt-클릭"
L["Alt-click: %s"] = "Alt-클릭: %s"
L["Always"] = "항상"
L["Always (floating)"] = "항상 (떠 있음)"
L["Always a skill point"] = "항상 기술 포인트 하나"
L["Ammo"] = "탄환 및 화살"
L["An Item Level line on weapon and armor tooltips, in soft gold."] = "무기와 방어구 툴팁에 부드러운 금색의 아이템 레벨 줄."
L["An arrow on your screen that points to the nearest mob or object you still need for the quest you picked, then to the quest giver once it's ready, with the yards under it. Nothing goes on the map. Needs the QuestieDB addon."] = "선택한 퀘스트에 아직 필요한 가장 가까운 몹이나 물체를, 준비되면 퀘스트 제공자를 가리키는 화살표를 화면에 표시하고 아래에 거리를 보여 줍니다. 지도에는 아무것도 표시하지 않습니다. QuestieDB 애드온이 필요합니다."
L["An item's green Equip lines in a few words (\"Improves your chance to hit by 1%\" reads \"+1% Hit\"), and every stat in a color of its own: each school, hit, crit, spell power, healing, the base stats. Procs and use effects stay as they are."] = "아이템의 초록색 착용 효과 문구를 몇 단어로 줄이고(\"적중률이 1% 증가합니다\"는 \"+1% 적중\"), 모든 능력치를 각자의 색으로 표시합니다: 각 계열, 적중, 치명타, 주문력, 치유량, 기본 능력치. 발동 효과와 사용 효과는 그대로 둡니다."
L["An objective you've finished."] = "완료한 목표."
L["An outline around its bar, a soft glow around it, or nothing."] = "막대 둘레의 외곽선, 은은한 빛, 또는 없음."
