L["Class and profession trainers open in the NPC window too, with what you can learn now and what's coming up. Pick a spell, then press Train or Train all: a click or a key alone never spends gold. Turn it off to use the game's trainer window."] = "직업 및 전문 기술 상급자도 NPC 창에서 열리며, 지금 배울 수 있는 것과 곧 배울 것을 보여 줍니다. 주문을 고른 뒤 배우기나 모두 배우기를 누르세요: 클릭이나 키 하나만으로는 골드를 쓰지 않습니다. 끄면 게임의 상급자 창을 씁니다."
