L["Class and reaction: players by class color, others by friendly, neutral or hostile. Dark: a near-black bar with the missing health in the class or reaction color."] = "직업 및 관계: 플레이어는 직업 색상, 그 외는 우호, 중립, 적대로. 어두움: 거의 검은 막대에 잃은 생명력을 직업 또는 관계 색상으로."
