L["Class gradient: the unit's class colors (an NPC's are by how friendly it is), and the red aggro ring is shaded to match. Accent color: your accent on every frame. Daylight gradient: the logo's colors on every frame. Light: a gray ring. Dark: the same dark border as the frame."] = "직업 그라데이션: 유닛의 직업 색상(NPC는 우호도에 따라)이며, 빨간 위협 고리도 맞춰 음영이 들어갑니다. 강조 색상: 모든 창에 강조 색상을 씁니다. Daylight 그라데이션: 모든 창에 로고 색상을 씁니다. 밝음: 회색 고리. 어두움: 창과 같은 어두운 테두리."
