L["Cuts both ends of each line at an angle. When off, the ends are straight."] = "각 줄의 양 끝을 비스듬히 자릅니다. 끄면 끝이 반듯합니다."
L["Cuts each tile's right end at an angle, like your own frame; the bars follow it."] = "내 창처럼 각 타일의 오른쪽 끝을 비스듬히 자릅니다. 막대도 따라갑니다."
L["Cuts one end of each pet bar at an angle. When off, the ends are straight."] = "각 소환수 막대의 한쪽 끝을 비스듬히 자릅니다. 끄면 끝이 반듯합니다."
L["Cuts the end of the bar at an angle. When off, the end is straight."] = "막대 끝을 비스듬히 자릅니다. 끄면 끝이 반듯합니다."
L["Cuts the end of your focus's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "주시 대상 시전바의 끝을 비스듬히 자릅니다. 끄면 끝이 반듯합니다. 창 안에 있을 때는 적용되지 않습니다."
L["Cuts the end of your target's cast bar at an angle. When off, its end is straight. Not while it sits inside the frame."] = "대상 시전바의 끝을 비스듬히 자릅니다. 끄면 끝이 반듯합니다. 창 안에 있을 때는 적용되지 않습니다."
L["Cuts the frame's inner end at an angle; the bars follow it."] = "창의 안쪽 끝을 비스듬히 자릅니다. 막대도 따라갑니다."
L["Cuts the left end at an angle; the bars follow it."] = "왼쪽 끝을 비스듬히 자릅니다. 막대도 따라갑니다."
L["Cuts the right end of each bar at an angle. When off, the ends are square."] = "각 막대의 오른쪽 끝을 비스듬히 자릅니다. 끄면 끝이 반듯합니다."
L["Cuts the right end at an angle; the bars and an attached cast bar follow it."] = "오른쪽 끝을 비스듬히 자릅니다. 막대와 붙은 시전바도 따라갑니다."
L["Cuts the right end at an angle; the bars follow it."] = "오른쪽 끝을 비스듬히 자릅니다. 막대도 따라갑니다."
L["Cutscenes and intro movies end at once. Hold Shift as one starts to watch it."] = "동영상과 시작 영상을 바로 끝냅니다. 시작할 때 Shift를 누르고 있으면 볼 수 있습니다."
L["DAMAGE"] = "피해"
L["DEAD"] = "죽음"
L["DEATHS"] = "죽은 수"
L["DISPELS"] = "무효화"
L["DND"] = "다른 용무 중"
L["DPS / Tank"] = "DPS / 방어 전담"
L["DPS / Tank (as it comes)"] = "DPS / 방어 전담 (기본 그대로)"
L["DPS/Tank made calm for questing: your action bars and your own frame fade a while after a fight (back under the mouse, in a fight or when you're hurt), the damage meter starts folded (one click on the panel's tab brings it out), the minimap is a little smaller and the XP bar shows its percent. Nothing fades in dungeons, raids, battlegrounds or arenas (General > Appearance, Fade only in the open world). Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "퀘스트에 맞게 차분해진 DPS/방어 전담: 전투 후 잠시 뒤 행동 단축바와 내 창이 흐려지고(마우스를 올리거나, 전투 중이거나, 다쳤을 때 다시 나타남), 피해량 측정기는 접힌 채 시작하며(패널 탭을 한 번 클릭하면 펼쳐짐), 미니맵은 조금 작아지고 경험치 막대에 백분율이 표시됩니다. 던전, 공격대, 전장, 투기장에서는 아무것도 흐려지지 않습니다(일반 > 모양, 야외에서만 흐려짐). 사용하려면 위에서 고르세요. 지금 프로필에서 행동 단축바를 옮겼다면 함께 가져올지 묻습니다."
L["DPS/Tank with your party and raid as square tiles under you (you included, missing health on them, dispels easy to see), and your frame and your target's raised a little. Everything it sets is on the Party and Raid pages; move any of them in unlock mode. Choose it above to use it. If the profile you're on has moved action bars, offers to bring them along."] = "파티와 공격대를 내 아래에 사각형 타일로(나 포함, 잃은 생명력 표시, 해제할 효과가 잘 보임) 표시하고, 내 창과 대상 창을 조금 올린 DPS/방어 전담. 설정하는 모든 것은 파티와 공격대 페이지에 있고, 잠금 해제 모드에서 무엇이든 옮길 수 있습니다. 사용하려면 위에서 고르세요. 지금 프로필에서 행동 단축바를 옮겼다면 함께 가져올지 묻습니다."
L["Damage"] = "피해"
