L["Daylight"] = "Daylight"
L["Daylight UI couldn't skin %s %s: it's left as it is."] = "Daylight UI가 %s %s에 스킨을 적용하지 못했습니다: 그대로 둡니다."
L["Daylight gradient"] = "Daylight 그라데이션"
L["Daylight is the warm band inside a dark outline, Flat a plain outline. With None the icon fills the whole button."] = "Daylight는 어두운 외곽선 안의 따뜻한 띠, 단순은 단순한 외곽선입니다. 없음이면 아이콘이 버튼 전체를 채웁니다."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Default uses the style set for every frame (Extras > Frame style). Each style keeps its own heights."] = "Daylight: 이름 탭이 위에 있고 자원 막대가 안에 있는 창. 리본: 이름과 생명력이 위에 떠 있고 자원이 아래 얇은 선인 얇은 막대. 기본은 모든 창에 설정한 스타일을 씁니다(추가 > 창 스타일). 스타일마다 높이를 따로 저장합니다."
L["Daylight: the frame with its name in a tab above it and the power bar inside. Ribbon: a slim bar with the name and health floating above it and the power as a thin line under it. Each frame can pick its own on its page."] = "Daylight: 이름 탭이 위에 있고 자원 막대가 안에 있는 창. 리본: 이름과 생명력이 위에 떠 있고 자원이 아래 얇은 선인 얇은 막대. 각 창은 자기 페이지에서 따로 고를 수 있습니다."
L["DaylightUI"] = "DaylightUI"
L["DaylightUI (General)"] = "DaylightUI (일반)"
L["DaylightUI Discord"] = "DaylightUI Discord"
L["DaylightUI has a new setup guide. Take the tour to see everything it can do, or keep your setup as it is."] = "DaylightUI에 새 설정 가이드가 생겼습니다. 둘러보기로 할 수 있는 모든 것을 보거나, 지금 설정을 그대로 두세요."
L["DaylightUI is set up on this character. Reload to put it in place?"] = "이 캐릭터에 DaylightUI 설정이 끝났습니다. 리로드해서 적용할까요?"
L["DaylightUI look for speech bubbles (say, yell, party). Instances keep the game's bubbles, since addons can't change them there."] = "말풍선(일반 대화, 외치기, 파티)에 DaylightUI 모양을 입힙니다. 인스턴스에서는 애드온이 바꿀 수 없어 게임의 말풍선을 유지합니다."
L["DaylightUI moved the quest tracker to fit the panel. Reload to put it in place?"] = "DaylightUI가 패널에 맞춰 퀘스트 추적기를 옮겼습니다. 리로드해서 적용할까요?"
L["DaylightUI put this profile's Edit Mode layout in place. Reload to use it?"] = "DaylightUI가 이 프로필의 편집 모드 배치를 적용했습니다. 리로드해서 사용할까요?"
L["DaylightUI replaces your frames, bars, bags, chat and more with a soft, minimal look. Let's set this character up."] = "DaylightUI는 창, 막대, 가방, 대화 등을 부드럽고 미니멀한 모양으로 바꿉니다. 이 캐릭터를 설정해 봅시다."
L["DaylightUI saved the loot window's position. Reload to put it in place?"] = "DaylightUI가 전리품 창 위치를 저장했습니다. 리로드해서 적용할까요?"
L["DaylightUI saved the quest tracker's position. Reload to put it in place?"] = "DaylightUI가 퀘스트 추적기 위치를 저장했습니다. 리로드해서 적용할까요?"
L["DaylightUI style Legacy window"] = "DaylightUI 스타일 유산 창"
L["DaylightUI style NPC window"] = "DaylightUI 스타일 NPC 창"
L["DaylightUI style character window"] = "DaylightUI 스타일 캐릭터 창"
