L["DaylightUI style inspect window"] = "DaylightUI 스타일 살펴보기 창"
L["DaylightUI style layout and look for the game's Cooldown Manager. When off, it's left exactly as the game draws it and /cdm opens the game's own settings."] = "게임의 재사용 대기시간 관리자에 DaylightUI 스타일 배치와 모양을 입힙니다. 끄면 게임이 그리는 그대로 두고 /cdm은 게임 자체 설정을 엽니다."
L["DaylightUI style mailbox"] = "DaylightUI 스타일 우체통"
L["DaylightUI style profession window"] = "DaylightUI 스타일 전문 기술 창"
