L["Down: newest on top"] = "아래로: 최신이 위"
L["Drag a piece to move it. Click it for its settings; the arrow keys then nudge it."] = "조각을 끌어 옮기세요. 클릭하면 설정이 열리고, 방향키로 미세 조정할 수 있습니다."
L["Drag it to an action bar."] = "행동 단축바로 끌어다 놓으세요."
L["Drag the pieces of the preview to move them: each stays where you let go, or catches on a dot right beside it. Click one, and the arrow keys nudge it (Shift for bigger steps). Every move changes the same settings as the cards below."] = "미리 보기의 조각을 끌어 옮기세요. 놓은 자리에 그대로 머물거나, 바로 옆의 점에 살짝 붙습니다. 조각을 클릭하면 방향키로 미세 조정할 수 있습니다(Shift로 더 크게). 옮길 때마다 아래 카드와 같은 설정이 바뀝니다."
L["Drag to move it, or click for its settings."] = "끌어서 옮기거나, 클릭하여 설정을 엽니다."
L["Drag to move. Drop it beside another piece to hook it on, drag it away to free it. Delete removes it."] = "끌어서 옮깁니다. 다른 조각 옆에 놓으면 연결되고, 떨어뜨려 끌면 풀립니다. 삭제하면 제거됩니다."
L["Dragon around the portrait"] = "초상화 주위의 용"
L["Dragon color"] = "용 색상"
L["Drop an item here"] = "여기에 아이템을 놓으세요"
L["Druid"] = "드루이드"
L["Druid mana in forms"] = "변신 중 드루이드 마나"
L["Dungeon"] = "던전"
L["Dungeon Journal"] = "던전 도감"
L["Dungeon and raid entrances"] = "던전 및 공격대 입구"
L["Dungeon tag color"] = "던전 태그 색상"
L["Dungeons, raids and battlegrounds"] = "던전, 공격대, 전장"
L["Durability"] = "내구도"
L["Durability %s"] = "내구도 %s"
L["During a ready check, a tick, a cross or a question mark on each member: ready, not ready, or no answer yet. They stay a few seconds after the check ends."] = "전투 준비 중 각 구성원에게 체크, 엑스 또는 물음표가 표시됩니다: 준비됨, 준비 안 됨, 아직 응답 없음. 확인이 끝난 뒤에도 몇 초간 남습니다."
L["ENEMY TAKEN"] = "적 받은 피해"
L["Each bar in its player's class color, or all in one color."] = "막대마다 해당 플레이어의 직업 색상, 또는 모두 한 가지 색상입니다."
L["Each bar's hand (or the queued attack) and the time to the next swing, written on the bar."] = "각 막대의 손 (또는 대기 중인 공격)과 다음 공격까지 남은 시간을 막대 위에 표시합니다."
L["Each bar's shape and when it shows. Changes apply at once. Move bars in unlock mode."] = "각 막대의 모양과 표시 시점입니다. 바로 적용됩니다. 막대는 잠금 해제 모드에서 옮기세요."
L["Each bar's size, shape and when it shows. Pick the bar with Settings for."] = "각 막대의 크기, 모양, 표시 시점입니다. 설정할 막대를 고르세요."
L["Each character uses a profile (one per talent set, with dual spec). Everything on every page changes the profile in use."] = "캐릭터마다 프로필을 사용합니다 (이중 특성이면 특성마다 하나). 모든 페이지의 설정은 사용 중인 프로필을 바꿉니다."
L["Each character's bags are saved when you log out, and its bank each time you visit a banker. See them anywhere with the chest button in your bags, or /dui bank. When off, the button goes away and nothing new is saved."] = "캐릭터마다 로그아웃할 때 가방이, 은행원을 찾을 때마다 은행이 저장됩니다. 가방의 상자 버튼이나 /dui bank로 어디서든 볼 수 있습니다. 끄면 버튼이 사라지고 새로 저장되지 않습니다."
L["Each combo point you build on your target."] = "대상에게 쌓은 연계 점수 하나하나입니다."
L["Each icon darkens like a clock as its time runs out."] = "시간이 다 되어 갈수록 아이콘이 시계처럼 어두워집니다."
L["Each icon's width and height."] = "각 아이콘의 너비와 높이입니다."
L["Each item's name and item level next to its icon. When off, only the icons show, with the item level in each corner and more room for the model."] = "아이콘 옆에 각 아이템의 이름과 아이템 레벨을 표시합니다. 끄면 아이콘만 표시되며, 아이템 레벨은 모서리에 표시되고 모델 공간이 넓어집니다."
L["Each its own"] = "각자 따로"
L["Each main-hand swing hits for %.0f to %.0f before armor."] = "주장비 공격 한 번에 방어도 적용 전 %.0f~%.0f의 피해를 줍니다."
L["Each member's health written on their tile."] = "각 구성원의 생명력을 칸에 표시합니다."
L["Each member's name on their tile."] = "각 구성원의 이름을 칸에 표시합니다."
L["Each objective line under a quest."] = "퀘스트 아래 각 목표 줄입니다."
L["Each person who whispers you gets a tab next to the others, and the whisper shows in your main tab as well. When off, whispers only show in the main tab."] = "귓속말을 보낸 사람마다 탭이 생기고, 귓속말은 기본 탭에도 표시됩니다. 끄면 귓속말은 기본 탭에만 표시됩니다."
L["Each pip leans like the frames' angled ends. When off, their ends are straight."] = "각 칸이 개체창의 비스듬한 끝처럼 기울어집니다. 끄면 끝이 곧게 됩니다."
L["Each pip's end cut at an angle, like the health bar's."] = "각 칸의 끝을 생명력 막대처럼 비스듬히 자릅니다."
L["Each quest's level in front of its title, like [15]."] = "각 퀘스트 제목 앞에 레벨을 [15]처럼 표시합니다."
L["Each quest's title in the tracker."] = "추적기에 표시되는 각 퀘스트 제목입니다."
L["Each shot hits for %.0f to %.0f before armor."] = "사격 한 번에 방어도 적용 전 %.0f~%.0f의 피해를 줍니다."
L["Each square darkens like a clock as your spell runs out."] = "주문이 끝나 갈수록 각 네모가 시계처럼 어두워집니다."
L["Each talent set has its own layout. Edit layout and Copy from work on this one."] = "특성 구성마다 배치가 따로 있습니다. 배치 편집과 복사해 오기는 이 배치에 적용됩니다."
L["Each text updates as it changes. Hover for details: gold on every character, each piece of gear, each bag, who's online."] = "각 텍스트는 바뀔 때마다 갱신됩니다. 마우스를 올리면 자세히 보여 줍니다: 모든 캐릭터의 골드, 장비 하나하나, 가방 하나하나, 접속 중인 사람."
L["Each threat bar in its player's class color, or all in one color."] = "위협 막대마다 해당 플레이어의 직업 색상, 또는 모두 한 가지 색상입니다."
L["Early start"] = "미리 시작"
L["Earned"] = "획득"
L["Earned this session"] = "이번 접속에서 획득"
L["Eases class, reaction and power colors toward gray for a gentler look."] = "직업, 관계, 자원 색상을 회색 쪽으로 누그러뜨려 더 부드럽게 보이게 합니다."
L["Edit"] = "편집"
L["Edit Mode hasn't loaded its layouts yet; try again in a moment"] = "편집 모드가 아직 배치를 불러오지 않았습니다. 잠시 후 다시 시도하세요"
L["Edit Mode is open; close it first"] = "편집 모드가 열려 있습니다. 먼저 닫으세요"
