L["Enemy pets and totems get a look of their own, totems in their element's color. In battlegrounds they're all red: the game hides which totem it is. When off, the game's setting for their plates is turned off too."] = "적 소환수와 토템이 따로 표시되며, 토템은 원소 색상으로 나타납니다. 전장에서는 게임이 어떤 토템인지 숨기므로 모두 빨간색입니다. 끄면 이들의 이름표에 대한 게임 설정도 꺼집니다."
L["Enemy plates: the health bar, the name under it, casts, your debuffs and crowd control. Friendly plates are simpler."] = "적 이름표: 생명력 막대, 그 아래 이름, 시전, 내 약화 효과와 군중 제어. 아군 이름표는 더 간단합니다."
L["Energy"] = "기력"
L["Enhancement"] = "고양"
L["Enter"] = "Enter"
L["Enter or Space"] = "Enter 또는 Space"
L["Enter says yes when someone asks you something: a group invite, a shared quest, a summon, a resurrect. Never on anything that binds, rolls or costs, and never in combat. Making an inn your home takes your Accept key too."] = "누군가 무언가를 물을 때 Enter로 수락합니다: 파티 초대, 공유된 퀘스트, 소환, 부활. 귀속, 주사위, 비용이 드는 것에는 절대 쓰이지 않으며, 전투 중에도 쓰이지 않습니다. 여관을 귀환 장소로 정할 때는 수락 키도 쓰입니다."
L["Entering and leaving combat"] = "전투 시작과 종료"
L["Epic (purple) and up"] = "영웅 (보라색) 이상"
L["Epic mount fund: %d%%. Keep saving!"] = "전문가 탈것 자금: %d%%. 계속 모으세요!"
L["Equipment sets"] = "장비 구성"
