L["Every bag in one window, with search, sorting and categories."] = "모든 가방을 한 창에, 검색, 정렬, 범주와 함께."
L["Every color in the quest tracker."] = "퀘스트 추적기의 모든 색상입니다."
L["Every debuff on you, over your frame. Off by default: your buff bars show them too."] = "내게 걸린 모든 약화 효과를 개체창 위에 표시합니다. 강화 효과 막대에도 표시되므로 기본값은 꺼짐입니다."
L["Every empty slot"] = "모든 빈 칸"
L["Every font"] = "모든 글꼴"
L["Every hand's bar in your class color, or your class's gradient with a two-color fill. A queued attack keeps its own color. Not with the Daylight gradient."] = "모든 손의 막대를 직업 색상으로, 또는 두 색상 채우기의 직업 그라데이션으로 표시합니다. 대기 중인 공격은 자기 색상을 유지합니다. Daylight 그라데이션과는 함께 쓸 수 없습니다."
L["Every header in this one color."] = "모든 머리글을 이 한 가지 색상으로."
L["Every health bar's color when Health bar color is One color."] = "생명력 막대 색상이 한 가지 색상일 때 모든 생명력 막대의 색상입니다."
L["Every item you dragged onto a group, or moved with Alt-right-click, goes back to its own group."] = "그룹으로 끌어다 놓거나 Alt-오른쪽 클릭으로 옮긴 모든 아이템이 원래 그룹으로 돌아갑니다."
L["Every line in the tooltips. General uses the font on General > Appearance."] = "툴팁의 모든 줄입니다. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["Every line stays until the newest one's time is up, then they all go. When off, each line leaves on its own."] = "가장 최근 줄의 시간이 다 될 때까지 모든 줄이 남았다가 함께 사라집니다. 끄면 줄마다 따로 사라집니다."
L["Every other row on a faint stripe, in the stats and the long lists, so lines are easier to follow."] = "능력치와 긴 목록에서 한 줄 걸러 옅은 줄무늬를 깔아 줄을 따라 읽기 쉽게 합니다."
L["Every part of DaylightUI and what it does. Switch off any you don't want; that applies when you reload."] = "Daylight UI의 모든 부분과 그 역할입니다. 원하지 않는 부분은 끄세요. 다시 불러오면 적용됩니다."
L["Every part's fade in one place. Each is the same setting as on that part's own page."] = "모든 부분의 사라짐 설정을 한곳에 모았습니다. 각 부분의 페이지에 있는 설정과 같은 것입니다."
L["Every power bar's color when Power bar color is One color."] = "자원 막대 색상이 한 가지 색상일 때 모든 자원 막대의 색상입니다."
L["Every quest in your log"] = "퀘스트 목록의 모든 퀘스트"
L["Every quest title's color while Quest title color is set to One color."] = "퀘스트 제목 색상이 한 가지 색상일 때 모든 퀘스트 제목의 색상입니다."
L["Every reward earned."] = "획득한 모든 보상입니다."
L["Every setting for this piece"] = "이 조각의 모든 설정"
L["Every text in the loot feed. General uses the font on General > Appearance."] = "전리품 알림의 모든 텍스트입니다. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["Every text in the quest tracker. General uses the font on General > Appearance."] = "퀘스트 추적기의 모든 텍스트입니다. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["Every texture"] = "모든 텍스처"
L["Every tracked quest, only the zone you're in, or every quest in your log without tracking them. The controls over the list switch the first two."] = "추적 중인 모든 퀘스트, 현재 지역만, 또는 추적하지 않고 퀘스트 목록의 모든 퀘스트입니다. 목록 위의 버튼으로 앞의 두 가지를 전환합니다."
