L["Fade everything at the campfire"] = "모닥불에서 모두 흐리게"
L["Fade in"] = "나타나기"
L["Fade in combat"] = "전투 중 사라짐"
L["Fade in on login"] = "접속 시 나타나기"
L["Fade only in the open world"] = "야외에서만 사라짐"
L["Fade other plates"] = "다른 이름표 흐리게"
L["Fade out"] = "사라지기"
L["Fade out of combat"] = "비전투 시 사라짐"
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP)."] = "비전투 시 사라짐: 전투가 끝나고 잠시 뒤 사라졌다가 전투가 시작되면 돌아옵니다. 전투 중 사라짐: 전투가 시작되고 잠시 뒤 사라졌다가 전투가 끝나면 돌아옵니다. 마우스를 올릴 때까지 사라짐: 마우스를 올릴 때까지 흐린 상태로 있습니다. 변화가 있을 때만: 전투가 아닐 때는 사라지고, 전투 중에는 돌아오며, 변화가 있을 때 잠깐 돌아옵니다 (강화 효과를 얻거나 잃을 때, 생명력, 퀘스트 진행, 경험치)."
L["Fade out of combat: fades a while after a fight and comes back in one. Fade in combat: fades a while into a fight and comes back after. Fade until mouseover: stays faded until your mouse is over it. Only when something changes: gone out of a fight, back in one, and back for a moment when it changes (a buff gained or lost, your health, quest progress, XP). Hidden (in combat, out of combat or always): gone, and its buttons can't be clicked."] = "비전투 시 사라짐: 전투가 끝나고 잠시 뒤 사라졌다가 전투가 시작되면 돌아옵니다. 전투 중 사라짐: 전투가 시작되고 잠시 뒤 사라졌다가 전투가 끝나면 돌아옵니다. 마우스를 올릴 때까지 사라짐: 마우스를 올릴 때까지 흐린 상태로 있습니다. 변화가 있을 때만: 전투가 아닐 때는 사라지고, 전투 중에는 돌아오며, 변화가 있을 때 잠깐 돌아옵니다 (강화 효과를 얻거나 잃을 때, 생명력, 퀘스트 진행, 경험치). 숨김 (전투 중, 비전투 시 또는 항상): 사라지며 버튼을 클릭할 수 없습니다."
L["Fade the icon"] = "아이콘 흐리게"
