L["Fade until mouseover"] = "마우스를 올릴 때까지 사라짐"
L["Fade when out of range"] = "사거리 밖이면 흐리게"
L["Faded opacity"] = "흐려진 투명도"
L["Fades only while your health is full; comes back as soon as it drops. Show on mouseover still works."] = "생명력이 가득 찼을 때만 사라지고, 줄어들면 바로 돌아옵니다. 마우스를 올리면 표시는 계속 작동합니다."
L["Fades only while your pet's health is full; comes back as soon as it drops. Show on mouseover still works."] = "소환수의 생명력이 가득 찼을 때만 사라지고, 줄어들면 바로 돌아옵니다. 마우스를 올리면 표시는 계속 작동합니다."
L["Failed"] = "실패"
