L["Health and power"] = "생명력과 자원"
L["Health and power bars fill from the opposite side."] = "생명력과 자원 막대를 반대쪽에서 채웁니다."
L["Health and power numbers"] = "생명력과 자원 수치"
L["Health bar"] = "생명력 막대"
