L["Health bar texture"] = "생명력 막대 텍스처"
L["Health text"] = "생명력 텍스트"
L["Health text color"] = "생명력 텍스트 색상"
L["Health text font"] = "생명력 텍스트 글꼴"
L["Health text format"] = "생명력 텍스트 형식"
L["Health text left / right"] = "생명력 텍스트 좌 / 우"
L["Health text size"] = "생명력 텍스트 크기"
L["Health text up / down"] = "생명력 텍스트 위 / 아래"
L["Healthstone"] = "생명석"
L["Hearthstone"] = "귀환석"
