L["Height"] = "높이"
L["Height limit"] = "높이 제한"
L["Hello"] = "안녕"
L["Herbalist's Band"] = "약초채집가의 반지"
L["Here's what Finish will do. Nothing has been saved yet."] = "완료를 누르면 이렇게 됩니다. 아직 아무것도 저장되지 않았습니다."
L["Hexagon"] = "육각형"
L["Hidden"] = "숨겨짐"
L["Hidden in combat"] = "전투 중 숨김"
L["Hidden out of combat"] = "비전투 시 숨김"
L["Hide"] = "숨기기"
L["Hide cooldown swipe"] = "재사용 대기시간 쓸기 효과 숨기기"
L["Hide duration swipe"] = "지속시간 쓸기 효과 숨기기"
L["Hide global cooldown swipe"] = "전역 재사용 대기시간 쓸기 효과 숨기기"
L["Hide keeps its gap: the other spells don't move."] = "숨겨도 자리는 유지됩니다: 다른 주문은 움직이지 않습니다."
L["Hide lower ranks"] = "낮은 등급 숨기기"
L["Hide shows the spell only while it's on cooldown. Only when usable shows it once you can cast it: Riposte after a parry, Overpower after a dodge, Execute on a low target. Both keep the gap: the other spells don't move."] = "숨기기는 재사용 대기 중일 때만 주문을 표시합니다. 사용 가능할 때만은 시전할 수 있게 되면 표시합니다: 무기 막기 후 반격, 피함 후 제압, 생명력이 낮은 대상에게 마무리 일격. 둘 다 자리는 유지됩니다: 다른 주문은 움직이지 않습니다."
L["Hide while mounted"] = "탈것을 타면 숨기기"
L["Hides the higher raid groups, e.g. 4 for a 20-player raid."] = "높은 번호의 공격대 그룹을 숨깁니다. 예: 20인 공격대라면 4."
L["Hides the number while a minute or more is left, so long buffs stay quiet."] = "1분 이상 남았을 때는 숫자를 숨겨 오래 가는 강화 효과는 조용히 둡니다."
L["Hides the red text and voice line from pressing a button too soon: not enough rage, mana or energy, not ready yet, out of range, no target. The useful ones still show: bags full, interrupted, line of sight, quest messages."] = "버튼을 너무 일찍 눌렀을 때 나오는 빨간 글자와 음성을 숨깁니다: 분노, 마나, 기력 부족, 아직 준비 안 됨, 사거리 밖, 대상 없음. 쓸모 있는 것은 계속 표시됩니다: 가방 가득 참, 차단됨, 시야, 퀘스트 메시지."
L["Hiding"] = "숨기는 중"
L["Highlight"] = "강조"
L["Highlight color"] = "강조 색상"
L["Highlights a spell that is active (an aura, auto attack, a stance) or being cast."] = "활성화된 주문 (오라, 자동 공격, 태세)이나 시전 중인 주문을 강조합니다."
L["History"] = "기록"
L["Hold: move to another group"] = "누르고 있기: 다른 그룹으로 옮기기"
L["Holy"] = "신성"
L["Holy Light"] = "성스러운 빛"
L["Home"] = "처음으로"
L["Honor"] = "명예"
L["Honor gains"] = "명예 획득"
L["Honor you earn in PvP."] = "PvP에서 얻는 명예입니다."
L["Honored"] = "우호적"
L["Hooked above %s"] = "%s 위에 연결됨"
L["Hooked below %s"] = "%s 아래에 연결됨"
L["Hooked left of %s"] = "%s 왼쪽에 연결됨"
L["Hooked right of %s"] = "%s 오른쪽에 연결됨"
L["Horizontal (light at the full end)"] = "가로 (가득 찬 쪽이 밝음)"
L["Hostile"] = "적대적"
L["Hover a button and press a key to bind it, or Escape to clear it. Click Okay when you're done. Out of combat only."] = "버튼에 마우스를 올리고 키를 눌러 지정하거나, Esc로 지웁니다. 다 되면 확인을 누르세요. 비전투 시에만 가능합니다."
L["Hover it for buttons: the fight (overall, current, and earlier fights by name), the mode, and reset."] = "마우스를 올리면 버튼이 나옵니다: 전투 (종합, 현재, 이전 전투는 이름으로), 방식, 초기화."
L["Hovering a quest in the quest log shows its tooltip beside the log, as the game's own log does. Off shows it at the mouse."] = "퀘스트 목록에서 퀘스트에 마우스를 올리면 게임의 퀘스트 목록처럼 목록 옆에 툴팁이 표시됩니다. 끄면 마우스 위치에 표시됩니다."
L["Hovering an item, spell or quest link in chat shows its tooltip, just above the chat."] = "대화창의 아이템, 주문, 퀘스트 링크에 마우스를 올리면 대화창 바로 위에 툴팁이 표시됩니다."
L["How big a crit on you pops. It starts at half this and settles back. The game's own is 60."] = "내게 들어온 치명타가 얼마나 크게 튀어나오는지입니다. 이 값의 절반에서 시작해 다시 가라앉습니다. 게임 기본값은 60입니다."
L["How big each buff icon is."] = "각 강화 효과 아이콘의 크기입니다."
L["How big each debuff icon is."] = "각 약화 효과 아이콘의 크기입니다."
L["How big each icon is."] = "각 아이콘의 크기입니다."
L["How big each item slot is in the Bank and alts window."] = "은행과 다른 캐릭터 창의 아이템 칸 크기입니다."
L["How big each item slot is in the bag."] = "가방의 아이템 칸 크기입니다."
L["How big each item slot is in the bank."] = "은행의 아이템 칸 크기입니다."
L["How big every square is."] = "모든 네모의 크기입니다."
L["How big it is, as a percent of its normal size. This is Edit Mode's own size setting, kept in your Edit Mode layout."] = "보통 크기에 대한 백분율 크기입니다. 편집 모드의 크기 설정이며, 편집 모드 배치에 저장됩니다."
L["How big the PvP flag is."] = "PvP 깃발의 크기입니다."
L["How big the arrow is on your screen, yards text included."] = "화면에 표시되는 화살표의 크기입니다 (거리 텍스트 포함)."
L["How big the clock is."] = "시계의 크기입니다."
L["How big the corner crown is."] = "모서리 왕관의 크기입니다."
L["How big the crowd control icon is."] = "군중 제어 아이콘의 크기입니다."
L["How big the data texts are."] = "정보 텍스트의 크기입니다."
L["How big the dispellable debuff's icon is."] = "해제 가능한 약화 효과 아이콘의 크기입니다."
L["How big the framerate is."] = "프레임률의 크기입니다."
L["How big the health text is on this frame."] = "이 개체창의 생명력 텍스트 크기입니다."
L["How big the health text on the tiles is."] = "칸의 생명력 텍스트 크기입니다."
L["How big the icons of buffs you can purge or steal are."] = "훔치거나 정화할 수 있는 강화 효과 아이콘의 크기입니다."
L["How big the item names, counts and skill-up text are in the loot feed."] = "전리품 알림의 아이템 이름, 개수, 기술 향상 텍스트 크기입니다."
L["How big the large health number is."] = "큰 생명력 숫자의 크기입니다."
L["How big the leader crown is."] = "파티장 왕관의 크기입니다."
L["How big the leader's crown is."] = "파티장 왕관의 크기입니다."
L["How big the name is on this frame."] = "이 개체창의 이름 크기입니다."
L["How big the names on the tiles are."] = "칸에 표시되는 이름의 크기입니다."
L["How big the pets' health text is."] = "소환수 생명력 텍스트의 크기입니다."
L["How big the pets' names are."] = "소환수 이름의 크기입니다."
L["How big the portrait ring is next to the frame's height."] = "개체창 높이에 대한 초상화 고리의 크기입니다."
L["How big the quest marker is in the world, distance text included."] = "월드에 표시되는 퀘스트 표시의 크기입니다 (거리 텍스트 포함)."
L["How big the raid marker is."] = "공격대 징표의 크기입니다."
L["How big the ready check answer is."] = "전투 준비 응답의 크기입니다."
L["How big the resting Zzz is."] = "휴식 중 Zzz의 크기입니다."
L["How big the role icon is."] = "역할 아이콘의 크기입니다."
L["How big the round badge of an enemy pet or totem is."] = "적 소환수나 토템의 둥근 배지 크기입니다."
L["How big the square minimap is."] = "네모 미니맵의 크기입니다."
L["How big the window is."] = "창의 크기입니다."
L["How big the window is. Other windows still open beside it when they fit."] = "창의 크기입니다. 공간이 맞으면 다른 창도 계속 옆에 열립니다."
L["How big this extra text is."] = "이 추가 텍스트의 크기입니다."
L["How big your buff icons on friendly plates are."] = "아군 이름표에 표시되는 내 강화 효과 아이콘의 크기입니다."
L["How big your debuff icons are."] = "내 약화 효과 아이콘의 크기입니다."
L["How bright the light behind the arrow is."] = "화살표 뒤 빛의 밝기입니다."
L["How bright the pips you haven't filled are, as a share of their color. Lower makes the filled ones stand out more."] = "채우지 않은 칸의 밝기입니다 (색상 대비 비율). 낮출수록 채운 칸이 더 돋보입니다."
L["How bright the unexplored areas are. At 100% they look like the parts you've explored."] = "탐험하지 않은 지역의 밝기입니다. 100%면 탐험한 곳과 같아 보입니다."
L["How dark the shade that sweeps over a button on cooldown is."] = "재사용 대기 중인 버튼 위를 쓸고 지나가는 그림자의 어둡기입니다."
L["How dark the shadow around DaylightUI's frames and windows is."] = "Daylight UI 개체창과 창 주위 그림자의 어둡기입니다."
L["How each hand's bar is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per hand, set right here. A queued attack always keeps its own color."] = "각 손의 막대를 채우는 방식: 각각 한 가지 색상, Daylight 그라데이션 (로고의 파랑에서 주황), 또는 여기서 정하는 손마다 두 색상 그라데이션. 대기 중인 공격은 항상 자기 색상을 유지합니다."
L["How every cast bar (yours, target's, focus's) is filled: one color each, the Daylight gradient (the logo's blue to orange), or a two-color gradient per kind of cast, set right here."] = "모든 시전바 (내, 대상, 주시 대상)를 채우는 방식: 각각 한 가지 색상, Daylight 그라데이션 (로고의 파랑에서 주황), 또는 여기서 정하는 시전 종류마다 두 색상 그라데이션."
L["How far above the cursor the tooltip's corner sits (below zero: lower down)."] = "툴팁 모서리가 커서보다 얼마나 위에 있는지입니다 (0 미만: 더 아래)."
L["How far along that quest objective is (4/10, or 45%), small, beside the !."] = "그 퀘스트 목표의 진행도 (4/10 또는 45%)를 ! 옆에 작게 표시합니다."
L["How far away plates show, in yards. 60 is the most the game allows."] = "이름표가 표시되는 거리 (미터)입니다. 게임이 허용하는 최대는 60입니다."
L["How far away the spot is."] = "그 지점까지의 거리입니다."
L["How far from the target the numbers start."] = "숫자가 대상에서 얼마나 떨어져 시작하는지입니다."
L["How far it fades. At 0 it disappears fully. Never more than Opacity."] = "얼마나 흐려지는지입니다. 0이면 완전히 사라집니다. 투명도보다 높아지지 않습니다."
L["How far past the name and bar a click still selects the unit."] = "이름과 막대 바깥으로 얼마나 떨어진 곳까지 클릭해도 대상이 선택되는지입니다."
L["How far right of the cursor the tooltip's corner sits (below zero: to the left)."] = "툴팁 모서리가 커서보다 얼마나 오른쪽에 있는지입니다 (0 미만: 왼쪽)."
L["How far the camera can zoom out. 100% is the game's normal limit; the far right end is as far as this client allows. At 100% the game's own setting is left alone."] = "카메라를 얼마나 멀리 뺄 수 있는지입니다. 100%는 게임의 일반 한도이고, 맨 오른쪽 끝은 이 클라이언트가 허용하는 최대입니다. 100%면 게임 설정을 건드리지 않습니다."
L["How far the frames' angled ends lean, on every unit frame and cast bar. 21% is the usual look."] = "모든 개체창과 시전바의 비스듬한 끝이 기울어지는 정도입니다. 21%가 보통 모양입니다."
L["How far the name tab's shadow spreads. 0 leaves no shadow."] = "이름 탭 그림자가 퍼지는 정도입니다. 0이면 그림자가 없습니다."
L["How far the numbers fly out to the sides. At 0 they go straight up, the game's own way."] = "숫자가 옆으로 날아가는 정도입니다. 0이면 게임 방식대로 곧장 위로 올라갑니다."
L["How far the panel reaches past the buttons on every side."] = "패널이 버튼 바깥으로 각 방향에 얼마나 넓게 나오는지입니다."
L["How far the soft shadow around DaylightUI's frames and windows reaches."] = "Daylight UI 개체창과 창 주위 부드러운 그림자가 퍼지는 정도입니다."
L["How far this frame's shadow spreads. 0 leaves no shadow."] = "이 개체창의 그림자가 퍼지는 정도입니다. 0이면 그림자가 없습니다."
L["How far through the level you are, e.g. 24%. With the numbers on too, it sits between them and the rested XP."] = "현재 레벨의 진행도입니다. 예: 24%. 숫자도 켜면 숫자와 휴식 경험치 사이에 표시됩니다."
L["How health and power numbers are written on unit frames, extra texts and nameplates. Percents stay as they are."] = "개체창, 추가 텍스트, 이름표에서 생명력과 자원 수치를 표시하는 방식입니다. 백분율은 그대로입니다."
L["How long a line stays on screen before it fades away."] = "한 줄이 사라지기 전 화면에 머무는 시간입니다."
L["How long a new item stays in Recent before it goes to its own group."] = "새 아이템이 원래 그룹으로 가기 전 최근 항목에 머무는 시간입니다."
L["How long each buff and debuff has left, on the top edge of its icon."] = "각 강화 및 약화 효과의 남은 시간을 아이콘 위쪽 가장자리에 표시합니다."
L["How long each line stays after your last loot of it."] = "마지막으로 획득한 뒤 각 줄이 머무는 시간입니다."
L["How long it stays before fading, unless the buffs land first."] = "강화 효과가 먼저 걸리지 않으면 사라지기 전까지 머무는 시간입니다."
L["How low the enemy's health has to be."] = "적의 생명력이 얼마나 낮아야 하는지입니다."
L["How many bars sit on your screen. Each one can be changed on its own later."] = "화면에 둘 막대 수입니다. 나중에 막대마다 따로 바꿀 수 있습니다."
L["How many buttons this bar shows."] = "이 막대에 표시할 버튼 수입니다."
L["How many data texts share the strip. Pick what each shows under Slots."] = "띠에 함께 들어갈 정보 텍스트 수입니다. 각각 무엇을 표시할지는 칸에서 고르세요."
L["How many of the newest messages per chat tab come back after /reload."] = "/reload 후 대화 탭마다 돌아오는 최신 메시지 수입니다."
L["How many rows the buttons wrap into (columns when the bar is vertical)."] = "버튼이 줄바꿈되는 줄 수입니다 (세로 막대면 열 수)."
L["How many slots fit in each row of the bag. More columns make it wider and shorter."] = "가방 한 줄에 들어가는 칸 수입니다. 열이 많을수록 넓고 낮아집니다."
L["How many yards away it is."] = "몇 미터 떨어져 있는지입니다."
L["How much a block, absorb or resist saved you."] = "방패 막기, 흡수, 저항으로 막아 낸 양입니다."
L["How much color the empty part of a bar keeps."] = "막대의 빈 부분에 남는 색상의 양입니다."
L["How much of the health bar's width the row spans, centered."] = "생명력 막대 너비 중 줄이 차지하는 비율입니다 (가운데 정렬)."
L["How much the shield can still soak, at the bar's right end."] = "보호막이 아직 흡수할 수 있는 양을 막대 오른쪽 끝에 표시합니다."
L["How much the shield can still soak, on the icon in place of its time. Its size and color are the cooldown numbers'."] = "보호막이 아직 흡수할 수 있는 양을 아이콘의 시간 자리에 표시합니다. 크기와 색상은 재사용 대기시간 숫자와 같습니다."
L["How objective lines show their progress: in the colors below, green once done, or shading from red to green as the count fills."] = "목표 줄의 진행도 표시 방식: 아래 색상, 완료 시 초록색, 또는 개수가 찰수록 빨강에서 초록으로 변하는 색."
L["How round the name tab's corners are. 0 keeps them sharp."] = "이름 탭 모서리의 둥근 정도입니다. 0이면 각진 모서리입니다."
L["How round this frame's corners are. 0 keeps them sharp."] = "이 개체창 모서리의 둥근 정도입니다. 0이면 각진 모서리입니다."
L["How see-through a frame gets while its unit is out of range."] = "대상이 사거리 밖에 있을 때 개체창이 비치는 정도입니다."
L["How see-through a spell set to Fade gets, ready or on cooldown."] = "흐리게로 설정된 주문이 준비되었거나 재사용 대기 중일 때 비치는 정도입니다."
L["How see-through a spell's icon is while it's on cooldown. The global cooldown doesn't count."] = "재사용 대기 중인 주문 아이콘이 비치는 정도입니다. 전역 재사용 대기시간은 포함하지 않습니다."
L["How see-through every window and panel is: bags, character, spellbook, NPC, group finder, the game's windows we restyle, and chat, the info panel, the quest box and the buff bars unless they have a separate one on their pages."] = "모든 창과 패널이 비치는 정도입니다: 가방, 캐릭터, 마법책, NPC, 파티 찾기, Daylight UI가 꾸민 게임 창, 그리고 각자의 페이지에 따로 설정이 없다면 대화창, 정보 패널, 퀘스트 상자, 강화 효과 막대."
L["How see-through it is while shown, whatever the fade does."] = "표시 중일 때의 투명도입니다. 사라짐 설정과 관계없습니다."
L["How see-through it is, when it fades and how far. Unlocked, in test mode or with this page open, it shows at its opacity."] = "얼마나 비치는지, 언제 얼마나 사라지는지입니다. 잠금 해제, 테스트 모드, 또는 이 페이지가 열려 있으면 이 투명도로 표시됩니다."
L["How see-through party and raid frames get while a member is out of range."] = "구성원이 사거리 밖에 있을 때 파티 및 공격대 개체창이 비치는 정도입니다."
L["How see-through the borders around DaylightUI's frames and windows are."] = "Daylight UI 개체창과 창 주위 테두리가 비치는 정도입니다."
L["How see-through the info panel's boxes and the meters' own windows are."] = "정보 패널의 상자와 측정기 창이 비치는 정도입니다."
L["How see-through the other plates get while you have a target."] = "대상이 있을 때 다른 이름표가 비치는 정도입니다."
L["How see-through the world map's symbols are. Lower it to see more of the map under them."] = "세계 지도 기호가 비치는 정도입니다. 낮추면 기호 아래 지도가 더 잘 보입니다."
L["How should it look?"] = "어떤 모양으로 할까요?"
L["How solid its background is: 0 is fully see-through."] = "배경이 얼마나 짙은지입니다: 0이면 완전히 투명합니다."
L["How solid the ribbon behind each loot feed line is: 0 is fully see-through."] = "각 전리품 알림 줄 뒤 리본이 얼마나 짙은지입니다: 0이면 완전히 투명합니다."
L["How solid the dark background is."] = "어두운 배경이 얼마나 짙은지입니다."
L["How strong the highlight on an active spell is."] = "활성화된 주문 강조의 세기입니다."
L["How strong the mouseover color over the icon is."] = "아이콘 위 마우스오버 색상의 세기입니다."
L["How strong the pressed color over the icon is."] = "아이콘 위 누름 색상의 세기입니다."
L["How strongly it lights up once the enemy is in range."] = "적이 사거리에 들어왔을 때 밝아지는 세기입니다."
L["How strongly the debuff's color tints the health bar. Only for a Tint or Both highlight."] = "약화 효과 색상이 생명력 막대를 물들이는 세기입니다. 색조 또는 둘 다 강조일 때만 적용됩니다."
L["How strongly the spell cost shows on your power bar."] = "주문 비용이 자원 막대에 표시되는 세기입니다."
L["How tall a friendly plate's health bar is."] = "아군 이름표 생명력 막대의 높이입니다."
L["How tall each enemy plate's health bar is."] = "각 적 이름표 생명력 막대의 높이입니다."
L["How tall each line of text over you is. The game's own is 25."] = "내 위에 표시되는 텍스트 한 줄의 높이입니다. 게임 기본값은 25입니다."
L["How tall each of the threat meter's bars is."] = "위협 측정기 막대 하나의 높이입니다."
L["How tall each of this meter's bars is."] = "이 측정기 막대 하나의 높이입니다."
L["How tall each pet bar is."] = "소환수 막대 하나의 높이입니다."
L["How tall each raid tile is."] = "공격대 칸 하나의 높이입니다."
L["How tall each swing timer bar is."] = "자동 공격 타이머 막대 하나의 높이입니다."
L["How tall each tile's power bar is."] = "각 칸의 자원 막대 높이입니다."
L["How tall every other plate's health bar is while you have a target, as a share of Health bar height."] = "대상이 있을 때 다른 모든 이름표의 생명력 막대 높이입니다 (생명력 막대 높이 대비 비율)."
L["How tall the cast bar under an enemy plate is."] = "적 이름표 아래 시전바의 높이입니다."
L["How tall the experience bar is."] = "경험치 막대의 높이입니다."
L["How tall the health bar is."] = "생명력 막대의 높이입니다."
L["How tall the health bar under the tooltip is."] = "툴팁 아래 생명력 막대의 높이입니다."
L["How tall the meter's own window is."] = "측정기 창의 높이입니다."
L["How tall the pets' power bars are."] = "소환수 자원 막대의 높이입니다."
L["How tall the power bar is."] = "자원 막대의 높이입니다."
L["How tall the second meter's window is."] = "두 번째 측정기 창의 높이입니다."
L["How tall the tab holding the name above the frame is."] = "개체창 위 이름이 들어가는 탭의 높이입니다."
L["How tall this frame is."] = "이 개체창의 높이입니다."
L["How tall your cast bar is."] = "내 시전바의 높이입니다."
L["How tall your focus's cast bar is. Not inside the frame, where it takes the power bar's place."] = "주시 대상 시전바의 높이입니다. 개체창 안에 있을 때는 자원 막대 자리를 차지하므로 해당되지 않습니다."
L["How tall your target's cast bar is. Not inside the frame, where it takes the power bar's place."] = "대상 시전바의 높이입니다. 개체창 안에 있을 때는 자원 막대 자리를 차지하므로 해당되지 않습니다."
L["How tall your target's health bar is, as a share of Health bar height."] = "대상 생명력 막대의 높이입니다 (생명력 막대 높이 대비 비율)."
L["How the health text on friendly plates reads: a percent, the health itself, health out of max, both, or what's missing."] = "아군 이름표 생명력 텍스트의 표시 방식: 백분율, 생명력, 생명력 / 최대, 둘 다, 또는 손실량."
L["How the health text reads: a percent, the health itself, health out of max, both, or what's missing."] = "생명력 텍스트의 표시 방식: 백분율, 생명력, 생명력 / 최대, 둘 다, 또는 손실량."
L["How the pets' health text is written."] = "소환수 생명력 텍스트의 표시 방식입니다."
L["How the power text is written."] = "자원 텍스트의 표시 방식입니다."
L["How the tiles' health text is written. Missing health shows nothing while the member is at full."] = "칸 생명력 텍스트의 표시 방식입니다. 손실량은 구성원의 생명력이 가득하면 아무것도 표시하지 않습니다."
L["How thick the border around each button is."] = "각 버튼 주위 테두리의 두께입니다."
L["How thick the name tab's outline is. 0 leaves none."] = "이름 탭 외곽선의 두께입니다. 0이면 없습니다."
L["How this category's buffs are edged: one color or a gradient. Click to change."] = "이 범주 강화 효과의 테두리: 한 가지 색상 또는 그라데이션. 클릭하여 바꿉니다."
L["How this extra text writes the health."] = "이 추가 텍스트가 생명력을 표시하는 방식입니다."
L["How this extra text writes the power."] = "이 추가 텍스트가 자원을 표시하는 방식입니다."
L["How wide a friendly plate's health bar is."] = "아군 이름표 생명력 막대의 너비입니다."
L["How wide each combo point pip is. Not while the pips match the frame's width."] = "각 연계 점수 칸의 너비입니다. 칸이 개체창 너비에 맞춰져 있으면 해당되지 않습니다."
L["How wide each enemy plate's health bar is."] = "각 적 이름표 생명력 막대의 너비입니다."
L["How wide each pet bar is."] = "소환수 막대 하나의 너비입니다."
L["How wide each raid tile is."] = "공격대 칸 하나의 너비입니다."
L["How wide every other plate is while you have a target, as a share of Width."] = "대상이 있을 때 다른 모든 이름표의 너비입니다 (너비 대비 비율)."
L["How wide the bars are."] = "막대의 너비입니다."
L["How wide the damage meter is, in the panel or in its own window."] = "피해량 측정기의 너비입니다 (패널 안이나 별도 창)."
L["How wide the list is."] = "목록의 너비입니다."
L["How wide the name tab is when Name tab width is Fixed width."] = "이름 탭 너비가 고정 너비일 때 이름 탭의 너비입니다."
L["How wide the second meter's window is. Dragging its corner in unlock mode sets this too."] = "두 번째 측정기 창의 너비입니다. 잠금 해제 모드에서 모서리를 끌어도 설정됩니다."
L["How wide the separate experience bar is. Dragging its corner in unlock mode sets this too."] = "별도 경험치 막대의 너비입니다. 잠금 해제 모드에서 모서리를 끌어도 설정됩니다."
L["How wide the threat meter is."] = "위협 측정기의 너비입니다."
L["How wide this frame is."] = "이 개체창의 너비입니다."
L["How wide your focus's cast bar is. Not inside the frame, or while it matches the frame's width."] = "주시 대상 시전바의 너비입니다. 개체창 안에 있거나 개체창 너비에 맞출 때는 해당되지 않습니다."
L["How wide your target's cast bar is. Not inside the frame, or while it matches the frame's width."] = "대상 시전바의 너비입니다. 개체창 안에 있거나 개체창 너비에 맞출 때는 해당되지 않습니다."
L["How wide your target's plate is, as a share of Width."] = "대상 이름표의 너비입니다 (너비 대비 비율)."
L["How you find your way to quests, and how they show in the tracker."] = "퀘스트를 찾아가는 방법과 추적기에 퀘스트가 표시되는 방식입니다."
L["How your target's plate stands out from the rest."] = "대상 이름표가 다른 이름표와 구별되는 방식입니다."
L["Hunter"] = "사냥꾼"
L["Hunters: a line on the ranged bar where Auto Shot's wind-up starts, adjusted for haste and your ping. Moving past it holds the shot back, so the bar stays full and says Stop moving until you stand still."] = "사냥꾼: 원거리 막대에 자동 사격의 준비 동작이 시작되는 선을 표시합니다 (가속과 지연 시간 반영). 그 뒤로 움직이면 사격이 미뤄지므로, 막대가 가득 찬 채로 멈출 때까지 움직임 멈춤이라고 표시합니다."
L["I'd like to train."] = "수련을 하고 싶습니다."
L["INTERRUPTS"] = "차단"
L["Icon"] = "아이콘"
L["Icon (the game's)"] = "아이콘 (게임 기본)"
L["Icon look"] = "아이콘 모양"
L["Icon per class"] = "직업별 아이콘"
L["Icon positions and sizes"] = "아이콘 위치와 크기"
L["Icon size"] = "아이콘 크기"
L["Icon style"] = "아이콘 스타일"
L["Icon zoom"] = "아이콘 확대"
L["Icons fill from the bar's right edge leftward, toward the middle of the screen."] = "아이콘이 막대 오른쪽 끝에서 왼쪽으로, 화면 가운데 쪽으로 채워집니다."
L["Icons left / right"] = "아이콘 좌 / 우"
L["Icons on a row before it wraps to the next."] = "줄바꿈 전 한 줄의 아이콘 수입니다."
L["Icons on bars"] = "막대 위 아이콘"
L["Icons per row"] = "줄당 아이콘 수"
L["Icons up / down"] = "아이콘 위 / 아래"
L["Idle time (seconds)"] = "대기 시간 (초)"
L["Ignore"] = "차단"
L["Ignored"] = "차단됨"
L["Import"] = "가져오기"
L["Import profile"] = "프로필 가져오기"
L["Imported the profile %s."] = "%s 프로필을 가져왔습니다."
L["In a group or with a pet, a small tag on the frame's top inner corner: your threat on it, where 100% means it turns on you. Orange as you get close, red once it's on you."] = "파티 또는 소환수와 함께일 때 개체창 안쪽 위 모서리에 작은 태그로 내 위협 수준을 표시합니다. 100%가 되면 나를 공격합니다. 가까워지면 주황색, 나를 노리면 빨간색입니다."
L["In a group, colors a mob by who it's attacking; solo plates never change. As a tank: red when it's attacking someone else, orange when you're about to lose it, normal while you hold it. As damage or healer: orange when you're close to pulling it, red once it's attacking you."] = "파티에서 몹이 누구를 공격하는지에 따라 색을 입힙니다. 혼자일 때는 바뀌지 않습니다. 방어 전담일 때: 다른 사람을 공격하면 빨간색, 곧 놓칠 것 같으면 주황색, 붙잡고 있으면 보통 색입니다. 공격 전담이나 치유 전담일 때: 어그로를 끌 것 같으면 주황색, 나를 공격하면 빨간색입니다."
L["In a group or with a pet, the target's ring (and threat tag) turns this color as you get close to pulling it."] = "파티 또는 소환수와 함께일 때 어그로를 끌 것 같아지면 대상의 고리 (와 위협 태그)가 이 색으로 바뀝니다."
L["In a raid, only the leader and assists can use the leader tools."] = "공격대에서는 공격대장과 부공격대장만 공격대장 도구를 쓸 수 있습니다."
L["In a row above the bar."] = "막대 위 한 줄로."
L["In categories"] = "범주별"
L["In columns"] = "열로"
L["In combat"] = "전투 중"
L["In combat in a group or with a pet"] = "파티 또는 소환수와 전투 중"
L["In combat, when I'm the tank"] = "전투 중, 내가 방어 전담일 때"
L["In dungeons, raids, battlegrounds and arenas, everything set to fade stays shown, as if its fade were Never. It fades again once you're back outside."] = "던전, 공격대, 전장, 투기장에서는 사라짐이 설정된 모든 것이 사라짐 없음처럼 계속 표시됩니다. 바깥으로 나오면 다시 사라집니다."
L["In fights"] = "전투 중"
L["In fights and when idle"] = "전투 중과 대기 중"
L["In fights: the panel and tabs float away and the messages stay over the world. When idle: the whole chat also fades when nothing new has come in for a while. Always: no panel or tabs while you play, only messages. The mouse over the chat or pressing Enter brings it back."] = "전투 중: 패널과 탭이 사라지고 메시지는 월드 위에 남습니다. 대기 중: 한동안 새 메시지가 없으면 대화창 전체도 사라집니다. 항상: 플레이 중에는 패널과 탭 없이 메시지만 표시됩니다. 대화창에 마우스를 올리거나 Enter를 누르면 돌아옵니다."
L["In progress"] = "진행 중"
L["In rows"] = "행으로"
L["In screen pixels, so it stays sharp at any UI scale. Heavy border needs 3 or more."] = "화면 픽셀 단위라서 어떤 UI 크기에서도 선명합니다. 두꺼운 테두리는 3 이상이 필요합니다."
L["In the chat box, Up and Down step through what you sent. Alt+Up and Alt+Down still work as before. While the box is open, the arrow keys don't turn your character."] = "대화 입력창에서 위, 아래 키로 보낸 내용을 차례로 불러옵니다. Alt+위와 Alt+아래는 예전처럼 작동합니다. 입력창이 열려 있는 동안 화살표 키로 캐릭터가 돌지 않습니다."
L["In the group"] = "파티 안"
L["In the info panel"] = "정보 패널 안"
L["In use"] = "사용 중"
L["In use: %s"] = "사용 중: %s"
L["In your accent color (Appearance), following it when it changes. When off, uses the color below."] = "강조 색상 (모양)으로 표시하며, 강조 색상이 바뀌면 따라 바뀝니다. 끄면 아래 색상을 사용합니다."
L["In your layout: click to pick it."] = "배치에 있음: 클릭하여 고릅니다."
L["Inactive"] = "활동 중단"
L["Inbox"] = "받은 우편함"
L["Incoming heals"] = "들어오는 치유"
L["Info"] = "정보"
L["Info Panel"] = "정보 패널"
L["Info panel"] = "정보 패널"
L["Info panel background opacity"] = "정보 패널 배경 투명도"
L["Inner end"] = "안쪽 끝"
L["Inside the frame"] = "개체창 안"
L["Inside the frame it covers the power bar, as wide as it (in the Ribbon style it sits below the frame instead). Above, below or on its own it's a bar you size here; on its own you move it in unlock mode."] = "개체창 안에서는 자원 막대 위를 같은 너비로 덮습니다 (리본 스타일에서는 개체창 아래에 둡니다). 위, 아래, 또는 따로일 때는 여기서 크기를 정하는 막대가 되며, 따로일 때는 잠금 해제 모드에서 옮깁니다."
L["Inspect"] = "살펴보기"
L["Inspecting a player opens DaylightUI's window, with their gear and talents. Turn it off to use the game's window."] = "플레이어를 살펴보면 Daylight UI의 창이 열려 장비와 특성을 보여 줍니다. 끄면 게임의 창을 사용합니다."
L["Install the Jiberish Fabled Icons addon to unlock more class icon styles."] = "Jiberish Fabled Icons 애드온을 설치하면 더 많은 직업 아이콘 스타일을 쓸 수 있습니다."
L["Instance"] = "인스턴스"
L["Instance chat, used in battlegrounds and groups made by the group finder."] = "인스턴스 대화입니다. 전장과 파티 찾기로 만든 파티에서 쓰입니다."
L["Instance color"] = "인스턴스 색상"
L["Intellect"] = "지능"
L["Interrupt animation"] = "차단 애니메이션"
