L["It shows when the first meter would: the Damage meter page's \"Show only in a group\" and \"Show only in combat\" count for both. Reset clears the fights in both."] = "첫 번째 측정기가 표시될 때 함께 표시됩니다: 피해량 측정기 페이지의 \"파티에서만 표시\"와 \"전투 중에만 표시\"가 둘 다에 적용됩니다. 초기화하면 둘 다의 전투 기록이 지워집니다."
L["It slides back once the fight ends. A click on its tab overrides this until the next fight starts or ends."] = "전투가 끝나면 다시 미끄러져 돌아옵니다. 탭을 클릭하면 다음 전투가 시작되거나 끝날 때까지 이 설정을 무시합니다."
L["It takes a reload."] = "다시 불러와야 합니다."
L["It's %s. Just one more quest?"] = "%s입니다. 퀘스트 하나만 더?"
