L["Item level line"] = "아이템 레벨 줄"
L["Item names beside icons"] = "아이콘 옆 아이템 이름"
L["Item names in their quality color, or all white. The icon's edge keeps the quality color."] = "아이템 이름을 품질 색상으로, 또는 모두 흰색으로. 아이콘 테두리는 품질 색상을 유지합니다."
L["Item quality border"] = "아이템 품질 테두리"
L["Items"] = "아이템"
L["Items and loot"] = "아이템과 전리품"
L["Items below this quality don't show, like gray junk."] = "이 품질보다 낮은 아이템은 표시하지 않습니다 (회색 잡동사니 등)."
L["Items sorted into groups by type. To move an item to another group, drag it onto that group's heading or Alt-right-click it. Click a heading to collapse it. Alt-right-click also locks an item so it's never sold or disenchanted."] = "종류별로 그룹에 정리된 아이템입니다. 다른 그룹으로 옮기려면 그 그룹 머리글로 끌어다 놓거나 Alt-오른쪽 클릭하세요. 머리글을 클릭하면 접힙니다. Alt-오른쪽 클릭은 아이템을 잠가 판매되거나 마력 추출되지 않게도 합니다."
L["Items that are uncommon or better get a border in their quality color."] = "고급 이상 아이템에 품질 색상 테두리를 줍니다."
L["Items you loot, create, buy or get from a quest."] = "획득, 제작, 구매하거나 퀘스트에서 받은 아이템입니다."
L["Items your class, level or skills can't use yet, or that you already know, get a red icon, as at a vendor."] = "직업, 레벨, 기술로 아직 쓸 수 없거나 이미 아는 아이템은 상인에게서처럼 아이콘이 빨갛게 표시됩니다."
L["Itim"] = "Itim"
L["Its buff or debuff"] = "그 강화 또는 약화 효과"
L["Its cooldown"] = "그 재사용 대기시간"
L["Its options and My Journey windows, and its quest objective icons on the maps, each quest in its own color."] = "옵션과 My Journey 창, 그리고 지도의 퀘스트 목표 아이콘을 퀘스트마다 다른 색으로."
L["Its own fade, apart from the panel's. With this page open it shows a sample group."] = "패널과 별도로 사라집니다. 이 페이지가 열려 있으면 견본 파티를 보여 줍니다."
L["Its own window"] = "별도 창"
L["Its own window, in the bottom-right corner to start. Move it in unlock mode (/dui unlock) and drag its corner to size it."] = "별도 창입니다. 처음에는 오른쪽 아래 모서리에 있습니다. 잠금 해제 모드 (/dui unlock)에서 옮기고 모서리를 끌어 크기를 정하세요."
L["Its owner's class"] = "주인의 직업"
L["Its owner's class tells at a glance whose pet it is."] = "주인의 직업으로 누구의 소환수인지 한눈에 알 수 있습니다."
L["Its timer bars in your font, bar texture and border. Sizes, colors and spots stay DBM's."] = "타이머 막대에 내 글꼴, 막대 텍스처, 테두리를 씁니다. 크기, 색상, 위치는 DBM 그대로입니다."
L["BigWigs and LittleWigs"] = "BigWigs와 LittleWigs"
L["Their timer bars in your font, bar texture and border, on BigWigs' Default bar style. Sizes, colors and spots stay BigWigs'."] = "BigWigs의 Default 막대 스타일에서 타이머 막대에 내 글꼴, 막대 텍스처, 테두리를 씁니다. 크기, 색상, 위치는 BigWigs 설정을 따릅니다."
L["Its window, and each attunement chain drawn like the talent trees."] = "창과 함께, 각 조율 퀘스트 단계를 특성 계통도처럼 그립니다."
L["Jiberish Fabled Icons is installed. Pick an icon for each class below, any style or one of its specs. The first icon on each line follows the Icon style."] = "Jiberish Fabled Icons가 설치되어 있습니다. 아래에서 직업마다 아이콘을 고르세요. 어떤 스타일이든, 전문화 아이콘이든 됩니다. 각 줄의 첫 아이콘은 아이콘 스타일을 따릅니다."
L["Join a group to use the leader tools, or try them with /dui leader test."] = "파티에 들어가면 공격대장 도구를 쓸 수 있습니다. /dui leader test로 미리 써 볼 수도 있습니다."
L["Join the DaylightUI Discord: press Ctrl+C to copy the link, then paste it in your browser."] = "Daylight UI 디스코드에 참여하세요: Ctrl+C로 링크를 복사한 뒤 브라우저에 붙여 넣으세요."
L["Junk"] = "잡동사니"
L["Just left of the panel, level with its top, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "패널 바로 왼쪽, 위쪽에 맞춰 두며, 미니맵이나 피해량 측정기 크기가 바뀌면 따라갑니다. 끄면 잠금 해제 모드에서 직접 옮길 수 있습니다."
L["Just left of the panel, the first row resting on its bottom edge, following it as the minimap or damage meter changes size. Turn it off to move the bar yourself in unlock mode."] = "패널 바로 왼쪽, 첫 줄이 패널 아래쪽 가장자리에 걸치며, 미니맵이나 피해량 측정기 크기가 바뀌면 따라갑니다. 끄면 잠금 해제 모드에서 직접 옮길 수 있습니다."
L["Just this spell, for now"] = "일단 이 주문만"
