L["Keep these talents under a name and put them back later, or copy and paste a talent string."] = "이 특성을 이름으로 저장해 두었다가 나중에 되돌리거나, 특성 문자열을 복사해 붙여 넣으세요."
L["Keeps the separate bar the same width as your main action bar."] = "별도 막대를 주 행동 단축바와 같은 너비로 유지합니다."
L["Kept for every character on this account, each with its own Edit Mode layout."] = "이 계정의 모든 캐릭터에 저장되며, 캐릭터마다 편집 모드 배치가 따로 있습니다."
