L["Keybind size"] = "단축키 크기"
L["Keybinds"] = "단축키"
L["Keybinds, stack counts, macro names and cooldown numbers on every bar, the Cooldown Manager and totems. General uses the font on General > Appearance."] = "모든 막대, 재사용 대기시간 관리자, 토템의 단축키, 중첩 수, 매크로 이름, 재사용 대기시간 숫자입니다. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["Keys"] = "키"
L["Kicked by"] = "차단한 사람"
L["Kinds: gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\nBinding: boe, bou, soulbound. In an equipment set: set, or the set's name. Locked: locked\nQuality: poor, common, uncommon, rare, epic, legendary, or q>rare, q>=uncommon, q<epic\nItem level: ilvl>20, ilvl<=10, ilvl20-30\nJoin with & (all) or | (any), ! for not: boe & q>common, food | potion, gear & !set\nA word that isn't one of these finds names. Start with # for the keyword only."] = "종류: gear, weapon, armor, consumable, food, drink, potion, reagent, tradegoods, recipe, key, container, quest, junk\n귀속: boe, bou, soulbound. 장비 구성에 있음: set, 또는 구성 이름. 잠김: locked\n품질: poor, common, uncommon, rare, epic, legendary, 또는 q>rare, q>=uncommon, q<epic\n아이템 레벨: ilvl>20, ilvl<=10, ilvl20-30\n& (모두) 또는 | (하나라도)로 잇고, !는 아님: boe & q>common, food | potion, gear & !set\n이 중 어느 것도 아닌 단어는 이름을 찾습니다. 키워드만 찾으려면 #으로 시작하세요."
