L["Loot, money, XP, reputation and skill-ups don't bring the chat back, so it stays out of the way while you grind. Whispers, party, guild and other messages still do."] = "전리품, 돈, 경험치, 평판, 기술 향상으로는 대화창이 다시 나타나지 않아 사냥하는 동안 방해되지 않습니다. 귓속말, 파티, 길드 등 다른 메시지는 여전히 다시 나타나게 합니다."
L["Lootable quest objects sparkle, and so do quest givers (the game has no setting for one alone). The game only sparkles with its outline around what you point at off, so this keeps that outline off. Turning this off puts the outline back; the sparkle may stay until you restart the game."] = "획득할 수 있는 퀘스트 물체와 퀘스트를 주는 NPC가 반짝입니다 (게임에는 하나만 켜는 설정이 없습니다). 게임은 가리킨 대상의 외곽선이 꺼져 있을 때만 반짝임을 보여 주므로, 이 설정은 외곽선을 꺼 둡니다. 끄면 외곽선이 돌아오며, 반짝임은 게임을 재시작할 때까지 남을 수 있습니다."
L["Low health and mana warning"] = "생명력과 마나 부족 경고"
