L["On a flight path, a bar at the top of the screen shows where you're going and the time left. Each route's time is learned the first time you fly it, for all your characters. Move it with /dui unlock."] = "비행 경로를 이용하는 동안 화면 위쪽 바에 목적지와 남은 시간이 표시됩니다. 경로마다 처음 비행할 때 시간을 기록하며, 모든 캐릭터가 함께 씁니다. /dui unlock으로 옮기세요."
L["On a ready check, and when you enter a dungeon or raid in a group, a short line shows the group buffs you don't have yet: only ones someone in your group can give. It fades once they land. Move it in unlock mode."] = "전투 준비 때, 그리고 파티로 던전이나 공격대에 들어갈 때, 아직 받지 않은 파티 강화 효과가 짧은 한 줄로 표시됩니다: 파티원이 줄 수 있는 것만. 받으면 사라집니다. 잠금 해제 모드에서 옮기세요."
L["On cooldown"] = "재사용 대기 중"
L["On in the Healer setup. Each class has its own picks; change them below."] = "치유 전담 설정에서 켜집니다. 직업마다 따로 고른 것이 있으며, 아래에서 바꿀 수 있습니다."
L["On its own (unlock to move)"] = "따로 (잠금 해제로 이동)"
L["On its own, the power bar leaves the frame and you can move it anywhere in unlock mode, like the middle of the screen. The frame is then all health."] = "따로 두면 자원 바가 개체창에서 떨어져 나와, 잠금 해제 모드에서 화면 가운데 등 어디로든 옮길 수 있습니다. 그러면 개체창 전체가 생명력이 됩니다."
L["On the plate"] = "이름표 위"
L["On the portrait"] = "초상화 위"
L["On the portrait rings of the player, target and focus frames."] = "플레이어, 대상, 주시 대상 개체창의 초상화 고리 위."
L["One click sets where the auras and the name sit. Change anything after."] = "클릭 한 번으로 오라와 이름의 위치를 정합니다. 나중에 무엇이든 바꿀 수 있습니다."
L["One color"] = "단색"
L["One color on every pip; colors shading from Combo point color to Full color along the row; your class color; or two-color pairs from the Gradients page (Combo points), one for all pips or one each. Your nameplates' combo points use the same colors."] = "모든 점에 한 가지 색; 줄을 따라 연계 점수 색에서 가득 참 색으로 변하는 색; 직업 색상; 또는 그라데이션 페이지의 두 색 쌍(연계 점수), 모든 점에 하나 또는 점마다 하나. 이름표의 연계 점수도 같은 색을 씁니다."
L["One custom color, your class color, or your class's two colors as a gradient (from the Gradients page)."] = "사용자 지정 색 하나, 직업 색상, 또는 직업의 두 색 그라데이션 (그라데이션 페이지)."
L["One gradient (Gradients page)"] = "그라데이션 하나 (그라데이션 페이지)"
L["One more thing at the end of the same line, after the second part."] = "같은 줄 끝, 두 번째 부분 뒤에 하나 더."
L["One row per group member and your pet on your target's threat list, highest first, with you always in it. The percent is of the pull: at 100% it turns on you."] = "대상의 위협 목록에 있는 파티원과 소환수마다 한 줄씩, 높은 순으로, 나는 항상 포함됩니다. 퍼센트는 어그로 기준이며, 100%가 되면 나에게 달려듭니다."
L["One switch per part of the game's windows."] = "게임 창의 부분마다 스위치 하나."
L["One tile with the count"] = "개수가 적힌 칸 하나"
L["One tile: each section of the bank shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "칸 하나: 은행의 각 구역에 빈 칸 하나와 남은 칸 수가 표시됩니다. 아이템을 그 위에 놓으면 그곳에 넣습니다."
L["One tile: each section shows a single empty slot with the free count on it."] = "칸 하나: 각 구역에 빈 칸 하나와 남은 칸 수가 표시됩니다."
L["One tile: each section shows a single empty slot with the free count on it. Drop an item on it to put it there."] = "칸 하나: 각 구역에 빈 칸 하나와 남은 칸 수가 표시됩니다. 아이템을 그 위에 놓으면 그곳에 넣습니다."
L["Ones that matter in a fight"] = "전투에 중요한 것"
L["Online"] = "접속 중"
L["Only at full health"] = "생명력이 가득할 때만"
L["Only clears this list. Moved buffs stay in their new categories."] = "이 목록만 지웁니다. 옮긴 강화 효과는 새 범주에 그대로 남습니다."
L["Only debuffs I can dispel"] = "내가 해제할 수 있는 약화 효과만"
L["Only in a group"] = "파티 중일 때만"
L["Only in combat"] = "전투 중일 때만"
L["Only mine"] = "내 것만"
L["Only ones I can dispel"] = "내가 해제할 수 있는 것만"
L["Only spells you cast can be bound."] = "내가 시전하는 주문만 지정할 수 있습니다."
L["Only the chat's messages stay over the world, each fading after a while, like Floating chat (Chat > Floating). It stays even with Fade everything at the campfire on."] = "대화 메시지만 세상 위에 남아 시간이 지나면 하나씩 사라집니다. 떠 있는 대화(대화 > 떠 있는 대화)와 같습니다. 모닥불에서 모두 흐리게를 켜도 남습니다."
L["Only the debuffs you put on it, or yours first and then everyone else's."] = "내가 건 약화 효과만, 또는 내 것을 먼저 보여 주고 그다음 다른 사람 것."
L["Only under a minute"] = "1분 미만일 때만"
L["Only when detached."] = "분리했을 때만."
L["Only when detached. Main hand at the bottom, the others above it."] = "분리했을 때만. 주장비가 맨 아래, 나머지는 그 위."
L["Only when detached. When attached, the bars match the cast bar's width."] = "분리했을 때만. 붙어 있으면 바가 시전바 너비에 맞춰집니다."
L["Only when something changes"] = "무언가 바뀔 때만"
L["When not usable"] = "사용할 수 없을 때"
L["Only while the power bar is on its own."] = "자원 바가 따로 있을 때만."
L["Only while the power bar is on its own. When off, both ends are straight."] = "자원 바가 따로 있을 때만. 끄면 양 끝이 곧습니다."
L["Only with a target"] = "대상이 있을 때만"
L["Only your group's leader can change the listing."] = "파티장만 등록 내용을 바꿀 수 있습니다."
L["Only your group's leader can list the group."] = "파티장만 파티를 등록할 수 있습니다."
L["Opacity"] = "투명도"
L["Opacity & fade"] = "투명도 및 흐려짐"
L["Opacity on cooldown"] = "재사용 대기 중 투명도"
L["Open DaylightUI options"] = "DaylightUI 설정 열기"
L["Open a chat box first to link it."] = "링크하려면 먼저 대화 입력창을 여세요."
L["Open spot"] = "빈 자리"
L["Open stat groups"] = "능력치 그룹 펼치기"
L["Open this page at these settings."] = "이 설정으로 이 페이지를 엽니다."
L["Open world only"] = "야외에서만"
L["Opening a mailbox shows DaylightUI's window: your letters, sending, and a ledger of your gold. Turn it off to use the game's window. The ledger keeps counting either way."] = "우체통을 열면 DaylightUI 창이 나옵니다: 편지, 보내기, 골드 장부. 끄면 게임 창을 씁니다. 장부는 어느 쪽이든 계속 기록합니다."
L["Opening a profession shows DaylightUI's window: your recipes on the left, the one you picked on the right. In a fight the game's own window opens. Turn it off to use the game's window."] = "전문 기술을 열면 DaylightUI 창이 나옵니다: 왼쪽에 제조법, 오른쪽에 고른 제조법. 전투 중에는 게임 창이 열립니다. 끄면 게임 창을 씁니다."
L["Opening a vendor sells everything in the Junk group: gray items, and anything you've moved to Junk yourself. Chat shows how much you got."] = "상인을 열면 잡동사니 그룹에 있는 모든 것을 팝니다: 회색 아이템과 직접 잡동사니로 옮긴 것. 받은 금액은 대화창에 표시됩니다."
L["Opening a vendor that repairs fixes all your gear, and chat shows the cost. Not in combat."] = "수리가 가능한 상인을 열면 모든 장비를 수리하고, 대화창에 비용이 표시됩니다. 전투 중에는 안 됩니다."
L["Opening and closing windows: bags, character, spellbook, quest log, the game menu and DaylightUI's own windows."] = "창 열고 닫기: 가방, 캐릭터, 마법책, 퀘스트 목록, 게임 메뉴, DaylightUI 자체 창."
L["Opening the group finder shows DaylightUI's window: groups to join, listing yourself, and who's about. In a fight the game's own window opens. Turn it off to use the game's window."] = "파티 찾기를 열면 DaylightUI 창이 나옵니다: 참여할 파티, 내 등록, 주변 사람. 전투 중에는 게임 창이 열립니다. 끄면 게임 창을 씁니다."
L["Opening your bag fills up part stacks of the same item (15 and 5 Linen Cloth become 20), so no slot is wasted. Not in combat, or while you trade or have the mailbox or auction house open."] = "가방을 열면 같은 아이템의 덜 찬 묶음을 채워 (리넨 옷감 15개와 5개가 20개로) 칸을 낭비하지 않습니다. 전투 중, 거래 중, 우체통이나 경매장이 열려 있을 때는 안 합니다."
L["Opens the Gradients page, where the Combo points pairs are."] = "연계 점수 쌍이 있는 그라데이션 페이지를 엽니다."
L["Opens the layout editor right on your screen: pull spells up from the tray, drag them where you want them, hook them together, click one to change it. Type /cdm to open it any time. Out of combat only."] = "화면 위에서 바로 구성 편집기를 엽니다: 트레이에서 주문을 끌어 올려 원하는 곳에 놓고, 서로 연결하고, 클릭해서 바꾸세요. 언제든 /cdm으로 열 수 있습니다. 비전투 중에만."
L["Opens your spellbook with Click-cast switched on: click a spell with the mouse button you want. Close the spellbook when you're done and this page comes back."] = "클릭 시전을 켠 채로 마법책을 엽니다: 원하는 마우스 버튼으로 주문을 클릭하세요. 다 되면 마법책을 닫으세요. 이 페이지로 돌아옵니다."
L["Option toggles"] = "설정 스위치"
L["Options"] = "설정"
L["Options (%s): %s"] = "설정 (%s): %s"
L["Options windows of addons built on Ace3, in the game's settings and their own windows: Questie, RestedXP and many more."] = "Ace3 기반 애드온의 설정 창, 게임 설정 안과 자체 창 모두: Questie, RestedXP 등."
L["Or drag the badge in Design mode."] = "또는 디자인 모드에서 배지를 끌어 옮기세요."
L["Orange timer when running out"] = "시간이 얼마 안 남으면 주황색 타이머"
