L["Daylight UI's journal, marker and arrow stay either way. You can change it later on the Quests options page."] = "Daylight UI의 퀘스트 일지, 표시기, 화살표는 어느 쪽이든 남습니다. 나중에 퀘스트 설정 페이지에서 바꿀 수 있습니다."
L["Our nameplates back."] = "이름표가 돌아왔습니다."
