L["Over or under the frame, the buffs sit nearest it when both share a spot. Outside spots may need room around the frame."] = "개체창 위나 아래에서 같은 위치를 함께 쓰면 강화 효과가 개체창에 가장 가깝게 놓입니다. 바깥 위치에는 개체창 주변에 공간이 필요할 수 있습니다."
L["Over, under or beside the health bar. In Design mode on the preview, drag it there."] = "생명력 바 위, 아래 또는 옆. 미리 보기의 디자인 모드에서 끌어다 놓으세요."
L["Over, under or beside the health bar. Rows sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "생명력 바 위, 아래 또는 옆. 같은 위치를 쓰는 줄은 바에서 바깥쪽으로 나란히 놓입니다. 미리 보기의 디자인 모드에서 끌어다 놓으세요."
L["Over, under, beside or on a friendly plate's health bar. Without the health bar the name stays centered."] = "아군 이름표 생명력 바의 위, 아래, 옆 또는 바 안. 생명력 바가 없으면 이름은 가운데에 남습니다."
L["Over, under, beside or on the health bar. Pieces sharing a spot line up outward from the bar. In Design mode on the preview, drag it there."] = "생명력 바의 위, 아래, 옆 또는 바 안. 같은 위치를 쓰는 요소는 바에서 바깥쪽으로 나란히 놓입니다. 미리 보기의 디자인 모드에서 끌어다 놓으세요."
L["Overall"] = "종합"
L["Overlap (bunch up)"] = "겹치기 (모으기)"
