L["Parts of the world map you haven't explored yet show too, dimmed so you can still tell where you haven't been."] = "아직 탐험하지 않은 세계 지도 지역도 표시합니다. 어둡게 그려져 가 보지 않은 곳을 알 수 있습니다."
