L["Past this the list scrolls with the mouse wheel."] = "이보다 길면 마우스 휠로 목록을 스크롤합니다."
L["Paste a DaylightUI profile (Ctrl+V) and name it. It becomes a new profile, chosen for this character (these talents, with dual spec); yours stay as they are."] = "DaylightUI 프로필을 붙여넣고 (Ctrl+V) 이름을 정하세요. 새 프로필이 되어 이 캐릭터(현재 특성, 이중 특성 포함)에 선택됩니다. 기존 프로필은 그대로입니다."
L["Paste a talent string"] = "특성 문자열 붙여넣기"
L["Paste someone's profile. It becomes a new profile; yours stay as they are."] = "다른 사람의 프로필을 붙여넣으세요. 새 프로필이 되며, 기존 프로필은 그대로입니다."
