L["Pick a page on the left to shape your interface. Changes apply as you make them. Hover a setting to see what it does; the arrow beside a changed setting puts it back."] = "왼쪽에서 페이지를 골라 인터페이스를 꾸미세요. 바꾸는 즉시 적용됩니다. 설정에 마우스를 올리면 설명이 나오며, 바뀐 설정 옆의 화살표를 누르면 되돌립니다."
