L["Players' last names after their first. When off, first names only, which fit the narrow rows better."] = "플레이어의 이름 뒤에 성을 붙입니다. 끄면 이름만 표시되어 좁은 줄에 더 잘 맞습니다."
L["Players' names in their class color, in every kind of chat (the game's own setting)."] = "모든 대화에서 플레이어 이름을 직업 색상으로 표시합니다 (게임 자체 설정)."
