L["Press 1 to 9 to pick a line or a reward, Space for the next step (accept, continue, complete), Escape to back out. Space never jumps while you talk. Other keys still go to the game, and in combat every key is the game's."] = "1~9를 눌러 대화 줄이나 보상을 고르고, Space로 다음 단계(수락, 계속, 완료), Escape로 물러납니다. 대화 중에는 Space로 건너뛰지 않습니다. 다른 키는 그대로 게임에 전달되며, 전투 중에는 모든 키가 게임의 것입니다."
L["Press Bind in spellbook (or open %s and switch on Click-cast at its top), then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more). That click on any of your unit frames then casts it on that unit. Close the spellbook when you're done: this page comes back. Left-click still targets and right-click opens the menu unless you bind them."] = "마법책에서 지정을 누르고 (또는 %s을(를) 열고 위쪽의 클릭 시전을 켠 뒤), 원하는 마우스 버튼으로 주문을 클릭하세요 (Shift, Ctrl, Alt를 누르면 더 많이). 그러면 어느 개체창에서든 그 클릭으로 해당 대상에게 시전합니다. 다 되면 마법책을 닫으세요: 이 페이지로 돌아옵니다. 따로 지정하지 않으면 왼쪽 클릭은 대상 지정, 오른쪽 클릭은 메뉴 열기 그대로입니다."
