L["Pressing O shows DaylightUI's window: who's online, people you played with, friend requests and your raid's groups. Turn it off to use the game's window."] = "O를 누르면 DaylightUI 창이 나옵니다: 접속 중인 사람, 함께 플레이한 사람, 친구 신청, 공격대 그룹. 끄면 게임 창을 씁니다."
