L["Shows a grid while frames are unlocked, and snaps them to it."] = "개체창 잠금이 풀린 동안 격자를 표시하고 격자에 맞춥니다."
L["Shows a handle on every frame. Drag to move it; right-click a handle to reset that frame."] = "모든 개체창에 손잡이를 표시합니다. 끌어서 옮기고, 손잡이를 오른쪽 클릭하면 그 개체창을 초기화합니다."
L["Shows a macro's name on its button. When off, macros show their icon only."] = "버튼에 매크로 이름을 표시합니다. 끄면 매크로는 아이콘만 표시합니다."
L["Shows a sample of just this frame while you edit it, and every change as you make it. Stays on across pages until you switch it off; combat ends it."] = "편집하는 동안 이 개체창만 예시로 보여 주며 바꾸는 즉시 반영합니다. 끌 때까지 페이지를 넘어가도 켜져 있으며, 전투가 시작되면 꺼집니다."
L["Shows a sample of the line where it sits."] = "놓일 자리에 줄의 예시를 보여 줍니다."
L["Shows buffs icons on each member."] = "각 파티원에 강화 효과 아이콘을 표시합니다."
L["Shows crowd control icons on each member."] = "각 파티원에 군중 제어 아이콘을 표시합니다."
L["Shows debuffs icons on each member."] = "각 파티원에 약화 효과 아이콘을 표시합니다."
L["Shows each button's key on the button. When off, the keys still work, you just don't see them."] = "각 버튼에 단축키를 표시합니다. 꺼도 단축키는 그대로 작동하며, 보이지만 않습니다."
L["Shows each pet's health as text."] = "각 소환수의 생명력을 텍스트로 표시합니다."
L["Shows each pet's name."] = "각 소환수의 이름을 표시합니다."
L["Shows only while the buff is up, like Power Word: Shield."] = "신의 권능: 보호막처럼 강화 효과가 있는 동안에만 표시합니다."
L["Shows or hides the row of bag buttons. Your bag keys still open your bags when it's hidden."] = "가방 버튼 줄을 보이거나 숨깁니다. 숨겨도 가방 단축키로 가방을 열 수 있습니다."
L["Shows or hides the row of small buttons that open your character, spellbook, talents and other windows. Their keys still work when it's hidden."] = "캐릭터, 마법책, 특성 등 창을 여는 작은 버튼 줄을 보이거나 숨깁니다. 숨겨도 단축키는 작동합니다."
L["Shows server time instead of your local time."] = "지역 시간 대신 서버 시간을 표시합니다."
L["Shows target, focus, pet, target of target and the party with sample units, and both cast bars mid-cast, so you can style and move them without a real target. Ends when combat starts."] = "대상, 주시 대상, 소환수, 대상의 대상, 파티를 예시 유닛으로 보여 주고 두 시전바를 시전 중으로 표시해, 실제 대상 없이 꾸미고 옮길 수 있습니다. 전투가 시작되면 끝납니다."
L["Shows the AFK screen now. Click or press any key to close it. Also /dui afk."] = "지금 자리 비움 화면을 표시합니다. 클릭하거나 아무 키나 누르면 닫힙니다. /dui afk로도 됩니다."
L["Shows the calendar and tracking buttons on the map's right edge while the mouse is over the map."] = "마우스가 지도 위에 있는 동안 지도 오른쪽 가장자리에 달력과 추적 버튼을 표시합니다."
L["Shows the game's countdown on buttons that are on cooldown."] = "재사용 대기 중인 버튼에 게임의 카운트다운을 표시합니다."
L["Shows the game's small gold coin on gray items in the bank, like the default bags."] = "기본 가방처럼 은행의 회색 아이템에 게임의 작은 금화를 표시합니다."
L["Shows the game's small gold coin on gray items, like the default bags."] = "기본 가방처럼 회색 아이템에 게임의 작은 금화를 표시합니다."
L["Shows the healer's name next to a heal on you."] = "나에게 들어온 치유 옆에 치유한 사람의 이름을 표시합니다."
L["Shows the health text large and white in the frame's inner corner (in Ribbon, at the inner end of the row above the bar)."] = "생명력 텍스트를 개체창 안쪽 모서리에 크고 하얗게 표시합니다 (리본에서는 바 위 줄의 안쪽 끝)."
L["Shows the unit's name on this frame."] = "이 개체창에 유닛 이름을 표시합니다."
L["Shows these raid frames in a party too, in place of the party frames."] = "파티에서도 파티 개체창 대신 이 공격대 개체창을 표시합니다."
L["Shows this square on each member while its spell is on them."] = "주문이 걸려 있는 동안 각 파티원에 이 사각형을 표시합니다."
L["Shows where the range is before the enemy gets there, faintly."] = "적이 도착하기 전에 사정거리를 흐릿하게 표시합니다."
L["Shrink icon when pressed"] = "누를 때 아이콘 축소"
L["Side"] = "옆"
L["Silk"] = "비단"
L["Silver"] = "은색"
L["Simple Wood"] = "단순한 나무"
L["Since %s"] = "%s 이후"
L["Since you logged in"] = "접속 이후"
L["Sitting by a campfire warms the screen with firelight and embers, a soft crackle plays, and your action bars and unit frames fade away. Move, target or cast and everything comes back; a fight brings it back at once. The sounds follow Soft UI sounds (General > Sound)."] = "모닥불 옆에 앉으면 화면이 불빛과 불씨로 따뜻해지고, 부드러운 장작 소리가 나며, 행동 단축바와 개체창이 사라집니다. 움직이거나 대상을 잡거나 시전하면 모두 돌아오며, 전투가 시작되면 즉시 돌아옵니다. 소리는 부드러운 UI 소리(일반 > 소리)를 따릅니다."
L["Size"] = "크기"
L["Size as a percent of the button's normal size."] = "버튼 기본 크기에 대한 퍼센트 크기."
L["Size of every plate, friendly and enemy. Plates keep this size at any distance."] = "아군과 적 모든 이름표의 크기. 거리와 상관없이 이 크기를 유지합니다."
L["Size of the names and numbers on this meter's bars."] = "이 측정기 바의 이름과 숫자 크기."
L["Size of the names and percents on the threat meter."] = "위협 측정기의 이름과 퍼센트 크기."
L["Size of the numbers on the experience bar."] = "경험치 바 숫자 크기."
L["Size target separately"] = "대상 크기 따로"
L["Sizing"] = "크기 조절"
L["Skill"] = "기술"
L["Skill %d / %d"] = "기술 %d / %d"
L["Skill-up color"] = "기술 향상 색상"
L["Skill-ups"] = "기술 향상"
L["Skills"] = "기술"
