L["Skull when your DoTs will kill it"] = "지속 피해로 죽일 수 있으면 해골 표시"
L["Skull, cross and the rest, on the tile of a marked member."] = "해골, 가위표 등을 징표가 붙은 파티원 칸에 표시합니다."
L["Skull, cross and the rest, shown in the name tab before the name."] = "해골, 가위표 등을 이름 탭의 이름 앞에 표시합니다."
L["Slant"] = "기울기"
L["Slant angle"] = "기울기 각도"
