L["Slot size"] = "칸 크기"
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for Bank and alts alone: their rows show below."] = "칸 크기, 간격, 크기 비율, 아이템 배치, 빈 칸, 아이템 아이콘 표시는 가방 페이지를 따릅니다. 끄면 은행과 다른 캐릭터에만 따로 설정할 수 있으며, 해당 줄이 아래에 표시됩니다."
L["Slot size, spacing, scale, how items are arranged, empty slots and item icon marks follow your Bags page. Turn it off to set them for the bank alone: their rows show below."] = "칸 크기, 간격, 크기 비율, 아이템 배치, 빈 칸, 아이템 아이콘 표시는 가방 페이지를 따릅니다. 끄면 은행에만 따로 설정할 수 있으며, 해당 줄이 아래에 표시됩니다."
L["Slots"] = "칸"
L["Slots per row in the Bank and alts window."] = "은행과 다른 캐릭터 창의 줄당 칸 수."
L["Slots per row in the bank. It holds more than your bags, so it's wider by default."] = "은행의 줄당 칸 수. 가방보다 많이 담기므로 기본으로 더 넓습니다."
L["Slots with nothing on them show as empty frames. When off, they disappear and show again while you drag a spell or item."] = "아무것도 없는 칸을 빈 틀로 표시합니다. 끄면 사라지며, 주문이나 아이템을 끄는 동안 다시 나타납니다."
L["Small Brown Pouch"] = "작은 갈색 주머니"
L["Small colored squares on each member for your heals over time and shields, like Renew or Power Word: Shield. Each square shows while your spell is on them."] = "지속 치유와 보호막을 각 파티원에 작은 색 사각형으로 표시합니다 (소생, 신의 권능: 보호막 등). 주문이 걸려 있는 동안 각 사각형이 표시됩니다."
L["Small helpers and the game's windows in DaylightUI style."] = "작은 편의 기능과 게임 창을 DaylightUI 스타일로."
L["Small helpers for looting, quests, trainers and more."] = "전리품, 퀘스트, 전문가 등을 위한 작은 편의 기능."
L["Small helpers that save time every day. Each one says what it does."] = "매일 시간을 아껴 주는 작은 편의 기능. 기능마다 설명이 있습니다."
L["Small helpers: faster looting, quest automation, trainers and more."] = "작은 편의 기능: 더 빠른 전리품 획득, 퀘스트 자동화, 전문가 등."
L["Small icons in their own row, under the frame by default."] = "따로 한 줄에 놓인 작은 아이콘. 기본은 개체창 아래."
L["Small icons over your frame, nearest it. Off by default: your buff bars show them too."] = "개체창 위, 가장 가까이 놓인 작은 아이콘. 기본은 꺼짐: 강화 효과 바에도 표시되기 때문입니다."
L["Small tiles for a raid of up to 10: one column per group, left to right. Show, fade, textures and fonts here count for every raid size; your party has its own page."] = "10명까지의 공격대용 작은 칸: 그룹마다 한 열, 왼쪽부터 오른쪽으로. 여기의 표시, 흐려짐, 텍스처, 글꼴은 모든 공격대 규모에 적용됩니다. 파티는 자체 페이지가 있습니다."
L["Smooth bars"] = "부드러운 바"
