L["Switch on, then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more): that click on a unit frame casts it. /dui > Unit Frames > Click-casting lists them."] = "켠 다음, 원하는 마우스 버튼으로 주문을 클릭하세요 (Shift, Ctrl, Alt를 누르면 더 지정 가능): 개체창에서 그 클릭으로 주문을 시전합니다. /dui > 개체창 > 클릭 시전에서 목록을 볼 수 있습니다."
L["Switch on, then click a spell with the mouse button you want (hold Shift, Ctrl or Alt for more): that click on a unit frame casts it. Closing the spellbook switches it off. /dui > Unit Frames > Click-casting lists them."] = "켠 다음, 원하는 마우스 버튼으로 주문을 클릭하세요 (Shift, Ctrl, Alt를 누르면 더 지정 가능): 개체창에서 그 클릭으로 주문을 시전합니다. 마법책을 닫으면 꺼집니다. /dui > 개체창 > 클릭 시전에서 목록을 볼 수 있습니다."
