L["Takes the meter out of the panel into its own window in the bottom-right corner; move it in unlock mode."] = "측정기를 패널에서 꺼내 오른쪽 아래 구석의 별도 창으로 옮깁니다. 잠금 해제 모드에서 옮길 수 있습니다."
L["Takes the spell out of the layout; it goes back to the tray. Delete does too."] = "주문을 배치에서 빼서 보관함으로 되돌립니다. 삭제해도 같습니다."
L["Takes this extra aura group off the frame. Add another in Design mode."] = "이 추가 효과 묶음을 개체창에서 뺍니다. 디자인 모드에서 다시 추가할 수 있습니다."
