L["Text size inside the frame"] = "개체창 안 텍스트 크기"
L["Text size of the count on a button, like charges or how many of an item you carry."] = "버튼 위 숫자의 텍스트 크기 (충전 횟수나 가진 아이템 개수 등)."
L["Text size of the countdown on a button that's on cooldown."] = "재사용 대기 중인 버튼의 남은 시간 텍스트 크기."
L["Text size of the key shown on each button."] = "각 버튼에 표시되는 단축키의 텍스트 크기."
L["Text size of the macro names on buttons."] = "버튼 위 매크로 이름의 텍스트 크기."
L["Text size of the names on enemy plates."] = "적 이름표의 이름 텍스트 크기."
L["Text size of the names on friendly plates."] = "아군 이름표의 이름 텍스트 크기."
L["Text up / down"] = "텍스트 위 / 아래"
L["Text: %s"] = "텍스트: %s"
L["Thank you for making DaylightUI possible."] = "DaylightUI를 가능하게 해 주셔서 감사합니다."
L["Thank you to everyone who supports DaylightUI and keeps it growing."] = "DaylightUI를 후원하고 키워 주시는 모든 분께 감사드립니다."
L["That border in the unit's class (or reaction) gradient from the Gradients page, running left to right."] = "그라데이션 페이지의 대상 직업(또는 관계) 그라데이션으로 칠한 테두리가 왼쪽에서 오른쪽으로 이어집니다."
L["That's as many builds as a set keeps: delete one first."] = "한 세트에 저장할 수 있는 구성 수가 가득 찼습니다: 먼저 하나를 삭제하세요."
L["The '?', the title and the hand-in line."] = "'?', 제목, 완료 줄."
L["The AFK screen can't show in combat, a boss fight, a keystone or a PvP match."] = "전투, 우두머리 전투, 쐐기돌, PvP 경기 중에는 자리 비움 화면을 표시할 수 없습니다."
L["The DaylightUI border, the item's quality color, your accent color (General > Appearance), or a color you pick."] = "DaylightUI 테두리, 아이템 품질 색상, 강조 색상 (일반 > 모양), 또는 직접 고른 색상."
L["The Fabled styles are art by JiberishUI and its artists, from the Jiberish Fabled Icons addon, read from its own folder. Without it installed, every style shows Daylight UI's own icons."] = "Fabled 스타일은 JiberishUI와 소속 아티스트의 작품으로, Jiberish Fabled Icons 애드온의 폴더에서 읽어 옵니다. 설치되어 있지 않으면 모든 스타일에서 Daylight UI 아이콘을 표시합니다."
L["The Legacy button shows DaylightUI's window: how far the next reward is, the challenges and the Legacy trees. Turn it off to use the game's window."] = "유산 버튼은 DaylightUI 창을 엽니다: 다음 보상까지 남은 정도, 도전 과제, 유산 계통도. 끄면 게임 기본 창을 사용합니다."
L["The Mindless Ones completed."] = "정신 나간 자들 완료."
L["The NPC window is switched off (/dui > Talk)."] = "NPC 창이 꺼져 있습니다 (/dui > 대화)."
L["The Quests header stays when nothing is tracked, so you can see where the tracker is."] = "추적 중인 퀘스트가 없어도 퀘스트 머리글이 남아 있어 추적기 위치를 알 수 있습니다."
L["The accent"] = "강조 색상"
L["The aggro color when Aggro color is Custom color."] = "위협 색상이 사용자 색상일 때의 위협 색상."
L["The arrow's color while Arrow color is set to Custom."] = "화살표 색상이 사용자 설정일 때의 화살표 색상."
L["The bank in the same look as your bags. Groups and moved items are shared with your bags."] = "가방과 같은 모양의 은행. 묶음과 옮긴 아이템은 가방과 공유됩니다."
L["The bar shades from dark to bright instead of one flat color. Reputation gets one per standing, editable on the Gradients page."] = "막대가 한 가지 색 대신 어두운 색에서 밝은 색으로 바뀝니다. 평판은 관계마다 하나씩이며, 그라데이션 페이지에서 바꿀 수 있습니다."
L["The bar's color for dead and offline players and tapped NPCs, and for NPCs by how they feel about you."] = "죽었거나 접속을 종료한 플레이어, 선점된 NPC, 그리고 나에 대한 태도에 따른 NPC의 막대 색상."
L["The bar's color while the cast can't be interrupted, whatever the fill style."] = "차단할 수 없는 시전 중의 막대 색상 (채움 방식과 관계없이)."
L["The bar's color while the cast can't be interrupted."] = "차단할 수 없는 시전 중의 막대 색상."
L["The bars over enemies' heads: how big they are, and what they show."] = "적 머리 위의 막대: 크기와 표시 내용."
L["The bars shade from dark to bright instead of one flat color. The color pairs are on General > Gradients."] = "막대가 한 가지 색 대신 어두운 색에서 밝은 색으로 바뀝니다. 색상 쌍은 일반 > 그라데이션에 있습니다."
L["The bars that hang off the end of the health for incoming heals and absorb shields. An overshield (a shield bigger than the health missing) follows the shield."] = "생명력 끝에 붙어 들어올 치유와 흡수 보호막을 보여 주는 막대. 초과 보호막 (잃은 생명력보다 큰 보호막)은 보호막을 따라갑니다."
L["The bars' and names' colors on every unit frame."] = "모든 개체창의 막대와 이름 색상."
L["The bars' color when Bar color is One color."] = "막대 색상이 단색일 때의 막대 색상."
L["The border color of every loot feed line while Loot feed border color is set to Custom."] = "전리품 알림 테두리 색상이 사용자 설정일 때 모든 전리품 알림 줄의 테두리 색상."
L["The border color when Border color is set to Your own color."] = "테두리 색상이 직접 고른 색상일 때의 테두리 색상."
L["The border in the same color as the name."] = "이름과 같은 색의 테두리."
L["The border of a debuff you can dispel, and the raid tile's dispel icon. Debuffs already on screen change after /reload."] = "해제할 수 있는 약화 효과의 테두리와 공격대 타일의 해제 아이콘. 이미 화면에 있는 약화 효과는 /reload 후에 바뀝니다."
L["The boxes behind the experience bar, minimap and damage meter, and the meters' and threat meter's own windows. At 0 opacity the boxes disappear; the minimap and bars still show."] = "경험치 막대, 미니맵, 피해량 측정기 뒤의 상자와 측정기 및 위협 측정기의 별도 창. 투명도 0이면 상자가 사라지고, 미니맵과 막대는 그대로 보입니다."
L["The buffs wrap onto up to this many rows."] = "강화 효과가 최대 이 줄 수만큼 줄바꿈됩니다."
L["The button's border lights up while the mouse is over it."] = "마우스를 올리면 버튼 테두리가 빛납니다."
L["The button's border lights up while you press it."] = "누르는 동안 버튼 테두리가 빛납니다."
L["The cast bar's color when Fill style is One color."] = "채움 방식이 단색일 때의 시전바 색상."
L["The character window and its tabs (reputation, skills, PvP, currency, statistics), inspecting others."] = "캐릭터 창과 그 탭 (평판, 기술, PvP, 화폐, 통계), 다른 플레이어 살펴보기."
L["The chat menu, channel, voice and social buttons next to chat. When off, they're gone; their slash commands still work."] = "대화창 옆의 대화 메뉴, 채널, 음성, 소셜 버튼. 끄면 사라지지만 슬래시 명령어는 그대로 작동합니다."
L["The chat window's text and the chat bubbles. General uses the font on General > Appearance."] = "대화창의 텍스트와 말풍선. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The clock reads 18:30 instead of 6:30 PM."] = "시계를 오후 6:30 대신 18:30으로 표시합니다."
L["The color of a Curse debuff's border and dispel icon."] = "저주 약화 효과의 테두리와 해제 아이콘 색상."
L["The color of a Disease debuff's border and dispel icon."] = "질병 약화 효과의 테두리와 해제 아이콘 색상."
L["The color of a Magic debuff's border and dispel icon."] = "마법 약화 효과의 테두리와 해제 아이콘 색상."
L["The color of a Poison debuff's border and dispel icon."] = "독 약화 효과의 테두리와 해제 아이콘 색상."
L["The color of the glow around your target's bar."] = "대상 막대 주위 광채의 색상."
L["The color of the last pip, or the whole row at max points, and the end of Color to full color."] = "마지막 칸, 또는 최대 점수일 때 줄 전체의 색상이자 최대 색상으로 변화의 끝 색상."
L["The color of the names on the threat meter."] = "위협 측정기의 이름 색상."
L["The color of the names on this meter's bars."] = "이 측정기 막대의 이름 색상."
L["The color of the outline around your target's bar."] = "대상 막대 주위 외곽선의 색상."
L["The color of the pull line across the threat bars."] = "위협 막대를 가로지르는 어그로 선의 색상."
L["The color of the shaded spell cost on your power bar."] = "자원 막대에 음영으로 표시되는 주문 소모량의 색상."
L["The color of the stretch for damage shields."] = "피해 보호막 구간의 색상."
L["The color of the stretch past the health for heals on their way."] = "생명력 너머 들어올 치유 구간의 색상."
L["The color the border lights up in while the mouse is over a button."] = "버튼에 마우스를 올렸을 때 테두리가 빛나는 색상."
L["The color the border lights up in while you press a button."] = "버튼을 누를 때 테두리가 빛나는 색상."
L["The color the execute range lights up in."] = "마무리 구간이 빛나는 색상."
L["The color used while the menu above is set to Custom."] = "위 메뉴가 사용자 설정일 때 쓰는 색상."
L["The colored sweep over the icon while its buff is up. When off, only the timer shows."] = "강화 효과가 유지되는 동안 아이콘 위를 쓸고 지나가는 색. 끄면 타이머만 표시합니다."
L["The colors below"] = "아래 색상"
L["The colors, font and textures used everywhere. The screen changes as you pick."] = "모든 곳에 쓰이는 색상, 글꼴, 텍스처. 고르는 대로 화면이 바뀝니다."
L["The cooldown edge's color when Cooldown edge is set to Your own color."] = "재사용 대기시간 가장자리가 직접 고른 색상일 때의 가장자리 색상."
L["The cooldown layout can't be edited during combat."] = "전투 중에는 재사용 대기시간 배치를 편집할 수 없습니다."
L["The cooldown manager's layout."] = "재사용 대기시간 관리자의 배치."
L["The countdown icons for your totems, above the player frame. Move them in unlock mode."] = "플레이어 개체창 위에 표시되는 토템 남은 시간 아이콘. 잠금 해제 모드에서 옮길 수 있습니다."
L["The currencies you're tracking (as the game's own backpack list shows them), with their icon and count, beside your money."] = "추적 중인 화폐 (게임의 소지품 목록과 같은 순서)를 아이콘과 수량과 함께 소지금 옆에 표시합니다."
L["The dark part shrinks away instead of filling in."] = "채워지는 대신 어두운 부분이 줄어듭니다."
L["The dark ribbon behind each line. When off, only the icon and text show."] = "각 줄 뒤의 어두운 띠. 끄면 아이콘과 텍스트만 표시합니다."
L["The data texts, and the clock and framerate on the minimap. General uses the font on General > Appearance."] = "정보 텍스트와 미니맵의 시계 및 프레임률. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The debuffs wrap onto up to this many rows."] = "약화 효과가 최대 이 줄 수만큼 줄바꿈됩니다."
L["The dim line under each item's name. Repair warnings still show when it's off."] = "각 아이템 이름 아래의 흐린 줄. 꺼도 수리 경고는 표시됩니다."
L["The dungeon journal, its favorites and settings windows; each dungeon's picture kept."] = "던전 도감과 즐겨찾기 및 설정 창. 각 던전의 그림은 그대로 둡니다."
L["The edge round each button. A proc still lights it up."] = "각 버튼의 테두리. 발동 효과는 그래도 빛납니다."
L["The elite dragon wraps your own portrait too."] = "정예 용 장식이 내 초상화도 감쌉니다."
L["The empty bar pulses while the buff is down."] = "강화 효과가 없는 동안 빈 막대가 깜빡입니다."
L["The empty part behind every bar's fill, tinted in the bar's color, except where a frame's own page picks another."] = "모든 막대의 채움 뒤 빈 부분으로, 막대 색상으로 물듭니다. 개체창 자체 페이지에서 따로 고른 곳은 제외합니다."
L["The empty part behind the bars in DaylightUI's windows. General uses the bar background above."] = "DaylightUI 창에 있는 막대의 빈 부분. 일반은 위의 막대 배경을 사용합니다."
L["The empty part of every bar in the group. A spell's own background, above, wins."] = "묶음에 있는 모든 막대의 빈 부분. 위에서 고른 주문 자체의 배경이 우선합니다."
L["The empty part of every health bar: a dimmed copy of the bar's own color, or one you pick."] = "모든 생명력 막대의 빈 부분: 막대 색을 어둡게 한 것, 또는 직접 고른 색."
L["The empty part of the Cooldown Manager's bars, behind the fill. General uses the bar background on General > Appearance."] = "재사용 대기시간 관리자 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the cast bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "모든 이름표 시전바의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the combo points on your target's nameplate, behind the fill. General uses the bar background on General > Appearance."] = "대상 이름표 연계 점수의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the combo points, behind the fill. General uses the bar background on General > Appearance."] = "연계 점수의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the damage, healing and threat meters' bars, behind the fill. General uses the bar background on General > Appearance."] = "피해, 치유, 위협 측정기 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the experience and reputation bar, behind the fill. General uses the bar background on General > Appearance."] = "경험치 및 평판 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the health bar on every nameplate, behind the fill. General uses the bar background on General > Appearance."] = "모든 이름표 생명력 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the health bar under a unit's tooltip, behind the fill. General uses the bar background on General > Appearance."] = "대상 툴팁 아래 생명력 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the pets' health bars, behind the fill. General uses the bar background on General > Appearance."] = "소환수 생명력 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the pets' power bars, behind the fill. General uses the bar background on General > Appearance."] = "소환수 자원 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the progress bars in the tracker and the pop-up, behind the fill. General uses the bar background on General > Appearance."] = "추적기와 팝업 진행 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the raid tiles' health bars, behind the fill. General uses the bar background on General > Appearance."] = "공격대 타일 생명력 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the raid tiles' power bars, behind the fill. General uses the bar background on General > Appearance."] = "공격대 타일 자원 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of the swing timer, behind the fill. General uses the bar background on General > Appearance."] = "자동 공격 타이머의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of this frame's health bar, behind the fill. General uses the bar background on General > Appearance."] = "이 개체창 생명력 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of this frame's power bar, behind the fill. General uses the bar background on General > Appearance."] = "이 개체창 자원 막대의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of your cast bar, behind the fill. General uses the bar background on General > Appearance."] = "내 시전바의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of your focus's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "주시 대상 시전바의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part of your target's cast bar, behind the fill. General uses the bar background on General > Appearance."] = "대상 시전바의 채움 뒤 빈 부분. 일반은 일반 > 모양의 막대 배경을 사용합니다."
L["The empty part's color when Missing health color is Custom color."] = "잃은 생명력 색상이 사용자 색상일 때 빈 부분의 색상."
L["The experience bar on top of the panel, or reputation at the level cap."] = "패널 위쪽의 경험치 막대, 최고 레벨에서는 평판."
L["The experience bar's text and its +XP. General uses the font on General > Appearance."] = "경험치 막대의 텍스트와 +경험치. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The experience bar, damage meter and minimap fade together (and the separate meter window, if used)."] = "경험치 막대, 피해량 측정기, 미니맵이 함께 흐려집니다 (별도 측정기 창을 쓰면 그것도)."
L["The fifth chat channel you joined, often a custom one."] = "다섯 번째로 가입한 대화 채널, 보통 사용자 채널."
L["The fifth pip fills in Full color (red to start with), so a full row stands out at a glance."] = "다섯 번째 칸이 최대 색상(처음엔 빨강)으로 채워져 줄이 가득 찬 것이 한눈에 보입니다."
L["The fill of every bar: health, power, cast bars, swing timers, experience, the damage meter, nameplates and more, except where a frame's own page picks another. Textures other addons share (SharedMedia) are listed after ours."] = "모든 막대의 채움: 생명력, 자원, 시전바, 자동 공격 타이머, 경험치, 피해량 측정기, 이름표 등. 개체창 자체 페이지에서 따로 고른 곳은 제외합니다. 다른 애드온이 공유하는 텍스처 (SharedMedia)는 DaylightUI 텍스처 다음에 나열됩니다."
L["The fill of the Cooldown Manager's bars. General uses the bar texture on General > Appearance."] = "재사용 대기시간 관리자 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the bars in DaylightUI's windows: reputation, skills, professions, pet experience, quest objectives. They keep their round shape. General uses the bar texture above."] = "DaylightUI 창에 있는 막대의 채움: 평판, 기술, 전문 기술, 소환수 경험치, 퀘스트 목표. 둥근 모양은 유지됩니다. 일반은 위의 막대 텍스처를 사용합니다."
L["The fill of the cast bar on every nameplate. General uses the bar texture on General > Appearance."] = "모든 이름표 시전바의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the combo points on your target's nameplate. General uses the bar texture on General > Appearance."] = "대상 이름표 연계 점수의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the combo points. General uses the bar texture on General > Appearance."] = "연계 점수의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the damage, healing and threat meters' bars. General uses the bar texture on General > Appearance."] = "피해, 치유, 위협 측정기 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the experience and reputation bar. General uses the bar texture on General > Appearance."] = "경험치 및 평판 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the health bar on every nameplate. General uses the bar texture on General > Appearance."] = "모든 이름표 생명력 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the health bar under a unit's tooltip. General uses the bar texture on General > Appearance."] = "대상 툴팁 아래 생명력 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the pets' health bars. General uses the bar texture on General > Appearance."] = "소환수 생명력 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the pets' power bars. General uses the bar texture on General > Appearance."] = "소환수 자원 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the progress bars in the tracker and the pop-up. General uses the bar texture on General > Appearance."] = "추적기와 팝업 진행 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the raid tiles' health bars. General uses the bar texture on General > Appearance."] = "공격대 타일 생명력 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the raid tiles' power bars. General uses the bar texture on General > Appearance."] = "공격대 타일 자원 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of the swing timer. General uses the bar texture on General > Appearance."] = "자동 공격 타이머의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of this frame's health bar. General uses the bar texture on General > Appearance."] = "이 개체창 생명력 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of this frame's power bar. General uses the bar texture on General > Appearance."] = "이 개체창 자원 막대의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of your cast bar. General uses the bar texture on General > Appearance."] = "내 시전바의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of your focus's cast bar. General uses the bar texture on General > Appearance."] = "주시 대상 시전바의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The fill of your target's cast bar. General uses the bar texture on General > Appearance."] = "대상 시전바의 채움. 일반은 일반 > 모양의 막대 텍스처를 사용합니다."
L["The font above shows everywhere at once, except where a frame's own page or the window font below picks another. This puts every one of those back on the font above."] = "위의 글꼴이 모든 곳에 한 번에 적용됩니다. 개체창 자체 페이지나 아래 창 글꼴에서 따로 고른 곳은 제외합니다. 이 버튼은 그런 곳을 모두 위의 글꼴로 되돌립니다."
L["The friendly health bar's color when Bar color is One color."] = "막대 색상이 단색일 때 아군 생명력 막대의 색상."
L["A marker over the quest you picked and breadcrumbs on the ground leading to it. With the QuestieDB addon, an arrow to the nearest objective too."] = "선택한 퀘스트 위의 표시와 그곳까지 땅 위에 이어지는 길 안내. QuestieDB 애드온이 있으면 가장 가까운 목표를 가리키는 화살표도."
L["The game menu, addon list, macros, clock, loot, socketing, upgrading, the scrapper, the auction house, the world map's frame, the breath bar."] = "게임 메뉴, 애드온 목록, 매크로, 시계, 전리품, 보석 장착, 강화, 분해기, 경매장, 세계 지도 테두리, 호흡 막대."
L["The game only reports range for your group; anyone else stays at full opacity."] = "게임은 파티원의 거리만 알려 줍니다. 그 외에는 항상 완전 불투명으로 표시됩니다."
L["The game shows it as a bar."] = "게임에서 막대로 표시합니다."
L["The game shows it as an icon."] = "게임에서 아이콘으로 표시합니다."
L["The game's chat in the DaylightUI look, in the bottom-left corner. Chat itself works as normal."] = "DaylightUI 모양의 게임 대화창을 왼쪽 아래 구석에 둡니다. 대화 기능은 평소대로 작동합니다."
L["The game's new-player tips (the game setting 'Tutorials'). When off, they're turned off."] = "게임의 초보자 도움말 (게임 설정 '튜토리얼'). 끄면 꺼집니다."
L["The game's numbers that pop off what you hit, and the scrolling combat text over you."] = "공격한 대상에서 튀어나오는 게임 숫자와 내 위로 흐르는 전투 문자."
L["The game's own"] = "게임 기본"
L["The game's own buff frames show beside DaylightUI's bars. When off, our bars replace them (they still show while Edit Mode is open)."] = "DaylightUI 막대 옆에 게임 기본 강화 효과 창을 표시합니다. 끄면 DaylightUI 막대가 대신합니다 (편집 모드가 열려 있는 동안은 계속 표시)."
L["The game's own messages: logins, /played, errors and the like."] = "게임 자체 메시지: 접속, /played, 오류 등."
L["The game's own setting: a quest you accept goes straight into the tracker."] = "게임 자체 설정: 수락한 퀘스트가 바로 추적기에 들어갑니다."
L["The game's own setting: the map turns with you, so the way you face is always up. When off, north is always up."] = "게임 자체 설정: 지도가 나와 함께 돌아 바라보는 방향이 항상 위쪽입니다. 끄면 항상 북쪽이 위입니다."
L["The game's own settings for how the numbers leave the target."] = "숫자가 대상에서 떠오르는 방식에 대한 게임 자체 설정."
L["The game's own switches."] = "게임 자체 설정."
L["The game's own windows in DaylightUI style: the info panel's background, DaylightUI borders, font, controls and scroll bars."] = "DaylightUI 스타일의 게임 창: 정보 패널 배경, DaylightUI 테두리, 글꼴, 조작 요소, 스크롤 막대."
L["The game's own windows in the DaylightUI look."] = "DaylightUI 모양의 게임 창."
L["The game's quest tracker, placed under the panel."] = "게임 퀘스트 추적기를 패널 아래에 둡니다."
L["The game's scrolling text over your own character: hits you take, heals, procs and more."] = "내 캐릭터 위로 흐르는 게임 전투 문자: 받는 공격, 치유, 발동 효과 등."
L["The game's tooltips in the DaylightUI look."] = "DaylightUI 모양의 게임 툴팁."
L["The game's tooltips."] = "게임 툴팁."
L["The gap between buff icons."] = "강화 효과 아이콘 사이 간격."
L["The gap between combo point pips."] = "연계 점수 칸 사이 간격."
L["The gap between combo points."] = "연계 점수 사이 간격."
L["The gap between debuff icons."] = "약화 효과 아이콘 사이 간격."
L["The gap between icons."] = "아이콘 사이 간격."
L["The gap between lines, when there's more than one."] = "줄이 여러 개일 때 줄 사이 간격."
L["The gap between one party frame and the next."] = "파티 개체창 사이 간격."
L["The gap between this bar's buttons."] = "이 단축바 버튼 사이 간격."
L["The gap between this bar's icons."] = "이 막대 아이콘 사이 간격."
L["The glow behind your character in this color."] = "이 색상으로 캐릭터 뒤에 광채를 둡니다."
L["The glowing border on a button when its spell procs."] = "주문이 발동되면 버튼에 빛나는 테두리를 표시합니다."
L["The gold at the bottom of the bag counts up or down to its new amount. Needs Motion effects (General > Appearance)."] = "가방 아래쪽 골드가 새 금액까지 올라가거나 내려갑니다. 움직임 효과가 필요합니다 (일반 > 모양)."
L["The green numbers over who you heal."] = "내가 치유한 대상 위의 초록색 숫자."
L["The guide that set this character up: a quick setup, a tour of everything DaylightUI does, or another profile."] = "이 캐릭터를 설정한 안내: 빠른 설정, DaylightUI 기능 둘러보기, 또는 다른 프로필."
L["The guide window (old and new), its steps and its item and target boxes."] = "안내 창 (이전 및 새 버전), 단계, 아이템 및 대상 상자."
L["The hand and time on each bar. Attached under the cast bar, it's kept small enough for the bar."] = "각 막대의 손과 시간. 시전바 아래에 붙으면 막대에 맞게 작게 유지됩니다."
L["The health and level numbers on the nameplates. General uses the font on General > Appearance."] = "이름표의 생명력과 레벨 숫자. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The health bar fills bottom to top instead of across."] = "생명력 막대가 가로가 아니라 아래에서 위로 채워집니다."
L["The health bar fills from the opposite side."] = "생명력 막대가 반대쪽에서 채워집니다."
L["The health bar's color for a dead unit."] = "죽은 대상의 생명력 막대 색상."
L["The health bar's color for a friendly NPC."] = "우호적인 NPC의 생명력 막대 색상."
L["The health bar's color for a player who went offline."] = "접속을 종료한 플레이어의 생명력 막대 색상."
L["The health bar's color for an NPC someone else tagged first."] = "다른 플레이어가 먼저 선점한 NPC의 생명력 막대 색상."
L["The health bar's color for an NPC that attacks you."] = "나를 공격하는 NPC의 생명력 막대 색상."
L["The health bar's color for an NPC that leaves you alone until you hit it."] = "공격하기 전까지 나를 내버려 두는 NPC의 생명력 막대 색상."
L["The health bar's color when Health bar color is One color."] = "생명력 막대 색상이 단색일 때의 생명력 막대 색상."
L["The health text shows at full health too. When off, it disappears while the unit is at full."] = "생명력이 가득 차도 생명력 텍스트를 표시합니다. 끄면 생명력이 가득한 동안 사라집니다."
L["The health text's color when Health text color is Custom."] = "생명력 텍스트 색상이 사용자 설정일 때의 생명력 텍스트 색상."
L["The highest rank"] = "최고 등급"
L["The highlight color: Daylight's own quiet tone, the Daylight gradient, your class's color or its gradient (from the Gradients page), or one of your own."] = "강조 색상: Daylight 고유의 차분한 색, Daylight 그라데이션, 직업 색상 또는 직업 그라데이션 (그라데이션 페이지), 또는 직접 고른 색."
L["The highlight's color when Active spell is set to Your own color."] = "활성 주문이 직접 고른 색상일 때의 강조 색상."
L["The icon of the quest the minimap arrow points to (click a quest's icon to pick it), and the light behind an icon under the mouse."] = "미니맵 화살표가 가리키는 퀘스트의 아이콘 (퀘스트 아이콘을 클릭해 선택)과 마우스를 올린 아이콘 뒤의 빛."
L["The info panel, meter, map and tracker."] = "정보 패널, 측정기, 지도, 추적기."
L["The item level at the bottom in your gear's quality color, durability green to yellow to red. When off, both are plain gray."] = "아래쪽 아이템 레벨은 장비 품질 색상, 내구도는 초록에서 노랑, 빨강으로. 끄면 둘 다 기본 회색입니다."
L["The item level of weapons and armor in the bank, in the bottom left corner."] = "은행에 있는 무기와 방어구의 아이템 레벨을 왼쪽 아래 구석에 표시합니다."
L["The item level of weapons and armor in the bottom left corner."] = "무기와 방어구의 아이템 레벨을 왼쪽 아래 구석에 표시합니다."
L["The kobolds in the mine carry candles on their heads to see in the dark. Bring me eight of them and I'll make it worth your while."] = "광산의 코볼트들은 어둠 속에서 보려고 머리에 양초를 달고 다니지. 여덟 개를 가져오면 섭섭지 않게 해 주겠네."
L["The leader tools are off: Unit Frames > Raid > Leader tools."] = "공격대장 도구가 꺼져 있습니다: 개체창 > 공격대 > 공격대장 도구."
L["The leader tools open after the fight."] = "공격대장 도구는 전투가 끝나면 열립니다."
L["The leader tools sit beside Daylight UI's party or raid frames, which are off."] = "공격대장 도구는 Daylight UI의 파티 또는 공격대 개체창 옆에 있는데, 개체창이 꺼져 있습니다."
L["The leader's crown stays in a fight. When off, it hides while you're fighting."] = "전투 중에도 공격대장 왕관을 표시합니다. 끄면 전투 중에는 숨깁니다."
L["The line under the open tab at the top (Character, Reputation, Skills...)."] = "위쪽에 열린 탭 아래의 줄 (캐릭터, 평판, 기술...)."
L["The line under the open tab in this color."] = "열린 탭 아래 줄을 이 색상으로."
L["The line where the range starts. 0 hides it."] = "구간이 시작되는 선. 0이면 숨깁니다."
L["The lines in the middle of the screen (interrupted, bags full, a new area found) in your font, errors in a soft red, easing in and out. Move them with /dui unlock. Turn it off to see the game's own red and yellow text."] = "화면 가운데의 문구 (차단됨, 가방 가득 참, 새 지역 발견)를 내 글꼴로, 오류는 부드러운 빨강으로 부드럽게 나타났다 사라지게 합니다. /dui unlock으로 옮길 수 있습니다. 끄면 게임 기본 빨강, 노랑 문구가 보입니다."
L["The lines under the headers in this color."] = "머리글 아래 줄을 이 색상으로."
L["The list grows up from its handle instead of down. For a tracker placed low on the screen."] = "목록이 손잡이에서 아래가 아니라 위로 늘어납니다. 화면 아래쪽에 둔 추적기용."
L["The look shared by everything DaylightUI draws."] = "DaylightUI가 그리는 모든 것이 공유하는 모양."
L["The loot browser's window, its lists, buttons and dialogs; its icons and maps kept."] = "전리품 탐색기 창, 목록, 버튼, 대화 상자. 아이콘과 지도는 그대로 둡니다."
L["The loot window's spot is kept by the game's Edit Mode, and you're on an Edit Mode layout of your own: move it there (Esc > Edit Mode)."] = "전리품 창 위치는 게임의 편집 모드가 관리하며, 지금은 직접 만든 편집 모드 배치를 쓰고 있습니다: 거기서 옮기세요 (Esc > 편집 모드)."
L["The lower ranks of each spell sit under the highest, so you can cast an older rank for less mana. When off, the spellbook lists only the highest rank. The spellbook page has the same switch (Hide ranks)."] = "각 주문의 하위 등급이 최고 등급 아래에 있어 마나를 덜 쓰는 이전 등급을 시전할 수 있습니다. 끄면 마법책에 최고 등급만 나옵니다. 마법책 페이지에도 같은 스위치(하위 등급 숨기기)가 있습니다."
L["The main hand bar's color."] = "주장비 막대 색상."
L["The mark shows what the quest wants from it, the way the map does: a sword to kill, a bag to loot, a cog to use, an eye to explore, in the quest's color. Needs the Quests module; without it, the !."] = "지도처럼 퀘스트가 원하는 것을 표시합니다: 처치는 검, 획득은 가방, 사용은 톱니바퀴, 탐험은 눈, 퀘스트 색상으로. 퀘스트 모듈이 필요하며, 없으면 !를 표시합니다."
L["The marker and the arrow fade back while you're in combat, so they're never in the way."] = "전투 중에는 표시와 화살표가 흐려져 방해되지 않습니다."
L["The marker in the world that leads you to your quest."] = "퀘스트로 안내하는 세계 속 표시."
L["The marker over the spot of the quest you picked (click its icon in the tracker) in DaylightUI style, with the distance. It fades away once you're in the quest's area on the map. Turn it off to see the game's own marker."] = "고른 퀘스트 (추적기에서 아이콘 클릭) 위치 위에 DaylightUI 스타일의 표시를 거리와 함께 띄웁니다. 지도에서 퀘스트 지역에 들어서면 사라집니다. 끄면 게임 기본 표시를 사용합니다."
L["The melee bars' color while Heroic Strike, Cleave or Maul waits for your next swing."] = "영웅의 일격, 회전베기, 후려치기가 다음 공격을 기다리는 동안 근접 막대 색상."
L["The meter hides while you play solo."] = "혼자 플레이할 때는 측정기를 숨깁니다."
L["The most buff icons at once."] = "한 번에 표시할 최대 강화 효과 아이콘 수."
L["The most buffs you can purge or steal one plate shows."] = "이름표 하나에 표시할, 정화하거나 훔칠 수 있는 강화 효과의 최대 수."
L["The most debuff icons at once."] = "한 번에 표시할 최대 약화 효과 아이콘 수."
L["The most debuffs from other players, shown after yours. Only with Mine first, then others."] = "다른 플레이어의 약화 효과를 내 것 다음에 표시할 최대 수. 내 것 먼저, 그다음 다른 사람일 때만."
L["The most group members the threat meter lists at once, under the damage meter."] = "피해량 측정기 아래 위협 측정기에 한 번에 표시할 최대 파티원 수."
L["The most group members the threat meter lists at once."] = "위협 측정기에 한 번에 표시할 최대 파티원 수."
L["The most icons this group shows at once."] = "이 묶음이 한 번에 표시할 최대 아이콘 수."
L["The most of your buffs one friendly plate shows."] = "아군 이름표 하나에 표시할 내 강화 효과의 최대 수."
L["The most of your debuffs one plate shows."] = "이름표 하나에 표시할 내 약화 효과의 최대 수."
L["The most of your own debuffs shown at once."] = "한 번에 표시할 내 약화 효과의 최대 수."
L["The mouseover border's color when Mouseover border color is set to Your own color."] = "마우스오버 테두리 색상이 직접 고른 색상일 때의 마우스오버 테두리 색상."
L["The name floats above the bar, at its outer end. Long names are cut short."] = "이름이 막대 위, 바깥쪽 끝에 떠 있습니다. 긴 이름은 잘립니다."
L["The name of a buff or debuff as it lands on you."] = "내게 걸리는 강화 또는 약화 효과의 이름."
L["The name sits in a small tab above the frame. Long names are cut short."] = "이름이 개체창 위 작은 탭에 들어갑니다. 긴 이름은 잘립니다."
L["The name's color when Name color is Custom."] = "이름 색상이 사용자 설정일 때의 이름 색상."
L["The names on every unit frame, unless a frame picks its own. Class and reaction: players by class color, others by friendly, neutral or hostile."] = "개체창이 따로 고르지 않는 한 모든 개체창의 이름. 직업 및 관계: 플레이어는 직업 색상, 그 외는 우호, 중립, 적대로."
L["The names' color when Name color is Custom."] = "이름 색상이 사용자 설정일 때의 이름 색상."
L["The newest first. Click one to move it again."] = "최근 것이 먼저. 하나를 클릭하면 다시 옮깁니다."
L["The note box shows after the fight."] = "쪽지 상자는 전투가 끝나면 표시됩니다."
L["The number on an icon showing how many stacks it has."] = "아이콘의 중첩 수를 보여 주는 숫자."
L["The numbers change color for the last seconds of the cooldown."] = "재사용 대기시간의 마지막 몇 초 동안 숫자 색이 바뀝니다."
L["The numbers in objectives, like 3/8."] = "목표의 숫자 (예: 3/8)."
L["The numbers on the bar, e.g. 1,200 / 5,000 (+800), where +800 is your rested XP."] = "막대의 숫자 (예: 1,200 / 5,000 (+800), +800은 휴식 경험치)."
L["The numbers over what you hit."] = "공격한 대상 위의 숫자."
L["The off hand bar's color."] = "보조장비 막대 색상."
L["The outline every button is cut to. The icon, border and cooldown shade all follow it."] = "모든 버튼이 잘리는 윤곽. 아이콘, 테두리, 재사용 대기시간 음영이 모두 따라갑니다."
L["The outline or glow in your accent color (Appearance), following it when it changes. When off, uses the colors below."] = "강조 색상(모양)의 외곽선이나 광채로, 강조 색상이 바뀌면 따라 바뀝니다. 끄면 아래 색상을 사용합니다."
L["The outline's color when Target outline color is Custom color."] = "대상 외곽선 색상이 사용자 색상일 때의 외곽선 색상."
L["The panel behind the chat, with its border. When off, only the chat text shows."] = "대화창 뒤의 테두리 있는 패널. 끄면 대화 텍스트만 표시합니다."
L["The panel's framed box behind the list, as tall as what's shown."] = "목록 뒤에 표시된 내용만큼의 높이로 테두리 상자를 둡니다."
L["The pet's health bar takes the mood color instead: red unhappy, yellow content, green happy. Turn the square off to have only this."] = "소환수 생명력 막대가 대신 만족도 색을 띱니다: 불만은 빨강, 보통은 노랑, 만족은 초록. 이것만 쓰려면 네모를 끄세요."
L["The pets' health text. General uses the font on General > Appearance."] = "소환수 생명력 텍스트. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The pets' names. General uses the font on General > Appearance."] = "소환수 이름. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The piece of the bar you just earned flashes and \"+XP\" rises; a sweep on a level up. Needs Motion effects (General > Appearance)."] = "방금 얻은 막대 부분이 반짝이고 \"+경험치\"가 떠오르며, 레벨이 오르면 빛이 쓸고 지나갑니다. 움직임 효과가 필요합니다 (일반 > 모양)."
L["The pips widen to span the whole frame, so the row reads like a bar."] = "칸이 개체창 전체 너비로 넓어져 줄이 막대처럼 보입니다."
L["The pips' color with One color, or the color they start from with Color to full color."] = "단색일 때의 칸 색상, 또는 최대 색상으로 변화일 때 시작 색상."
L["The players who keep DaylightUI going. Thank you."] = "DaylightUI를 이어 가게 해 주는 플레이어분들. 감사합니다."
L["The power bar's color when Power bar color is One color."] = "자원 막대 색상이 단색일 때의 자원 막대 색상."
L["The power text shows while mana, rage or energy is full too. When off, it disappears at full."] = "마나, 분노, 기력이 가득 차도 자원 텍스트를 표시합니다. 끄면 가득 찼을 때 사라집니다."
L["The pressed border's color when Pressed border color is set to Your own color."] = "누름 테두리 색상이 직접 고른 색상일 때의 누름 테두리 색상."
L["The priority quest's color while Priority quest color is set to Custom."] = "우선 퀘스트 색상이 사용자 설정일 때의 우선 퀘스트 색상."
L["The proc border's color when Proc border is set to Your own color."] = "발동 테두리가 직접 고른 색상일 때의 발동 테두리 색상."
L["The profile %s is ready. Choose it for this character (or a talent set) to use it."] = "%s 프로필이 준비되었습니다. 사용하려면 이 캐릭터 (또는 특성 세트)에 선택하세요."
L["The profile %s: its settings, frame positions and Edit Mode layout. Ctrl+C to copy, then share it."] = "%s 프로필: 설정, 개체창 위치, 편집 모드 배치. Ctrl+C로 복사해 공유하세요."
L["The profile for your first talent set. Changing it asks to reload."] = "첫 번째 특성 세트의 프로필. 바꾸면 UI를 다시 불러올지 묻습니다."
L["The profile for your second talent set; swapping talents asks to switch."] = "두 번째 특성 세트의 프로필. 특성을 바꾸면 전환할지 묻습니다."
L["The profile in use as text to copy and share."] = "사용 중인 프로필을 복사해 공유할 수 있는 텍스트로."
L["The profile is ready. Reload to use it."] = "프로필이 준비되었습니다. 사용하려면 UI를 다시 불러오세요."
L["The profile is used as it is; nothing in it changes."] = "프로필을 그대로 사용합니다. 아무것도 바뀌지 않습니다."
L["The profile this character uses. Changing it asks to reload."] = "이 캐릭터가 쓰는 프로필. 바꾸면 UI를 다시 불러올지 묻습니다."
L["The profile's Edit Mode layout will be set after the reload (%s)."] = "프로필의 편집 모드 배치는 UI를 다시 불러온 뒤 적용됩니다 (%s)."
L["The progress bars' color while Progress bar color is set to Custom."] = "진행 막대 색상이 사용자 설정일 때의 진행 막대 색상."
L["The quest log on the world map."] = "세계 지도의 퀘스트 목록."
L["The quest under the mouse stays bright, the others ease dimmer."] = "마우스를 올린 퀘스트는 밝게 남고, 나머지는 부드럽게 흐려집니다."
L["The raid frames for 11 to 20 players. Show, fade, textures and fonts are on the Raid 10 page."] = "11~20명용 공격대 개체창. 표시, 흐려짐, 텍스처, 글꼴은 공격대 10 페이지에 있습니다."
L["The raid frames for 21 to 40 players. Show, fade, textures and fonts are on the Raid 10 page."] = "21~40명용 공격대 개체창. 표시, 흐려짐, 텍스처, 글꼴은 공격대 10 페이지에 있습니다."
L["The raid tiles' health text. General uses the font on General > Appearance."] = "공격대 타일의 생명력 텍스트. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The raid tiles' names. General uses the font on General > Appearance."] = "공격대 타일의 이름. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The raid tiles' own name color. Same as the Colors page follows the name color every frame shares."] = "공격대 타일 고유의 이름 색상. 색상 페이지와 동일을 고르면 모든 개체창이 공유하는 이름 색상을 따릅니다."
L["The ranged bar shows how far your target is instead of its name: Melee, Dead zone, 10 to 35 yd, Max range or Out of range."] = "원거리 막대가 대상 이름 대신 거리를 표시합니다: 근접, 사각지대, 10~35미터, 최대 사거리, 사거리 밖."
L["The ranged bar's color."] = "원거리 막대 색상."
L["The red of a ring, name tab or raid tile while something is attacking the unit, or a color you pick."] = "무언가가 대상을 공격하는 동안의 고리, 이름 탭, 공격대 타일의 빨강, 또는 직접 고른 색."
L["The ring (or name tab, or raid tile) that turns red while something is attacking the unit; an elite's dragon keeps its color, its eyes catch fire."] = "무언가가 대상을 공격하는 동안 빨갛게 바뀌는 고리 (또는 이름 탭, 공격대 타일). 정예의 용은 색을 유지하고 눈에 불이 붙습니다."
L["The role icon stays in a fight. When off, it hides while you're fighting."] = "전투 중에도 역할 아이콘을 표시합니다. 끄면 전투 중에는 숨깁니다."
L["The row above the bar that holds the name and the health number."] = "막대 위에 이름과 생명력 숫자가 들어가는 줄."
L["The same click again removes it."] = "같은 클릭을 다시 하면 제거됩니다."
L["The same colors as in the game's chat settings: a change shows in every chat tab."] = "게임 대화 설정과 같은 색상: 바꾸면 모든 대화 탭에 반영됩니다."
L["The same size as the top-right panel with its damage meter out."] = "피해량 측정기를 뺀 오른쪽 위 패널과 같은 크기."
L["The search failed. Try Refresh."] = "검색에 실패했습니다. 새로고침을 해 보세요."
L["The shade over the health your damage over time spells will still take, on the target and on enemy nameplates."] = "대상과 적 이름표에서 지속 피해 주문이 앞으로 깎을 생명력 위의 음영."
L["The shade that sweeps over a button while it's on cooldown."] = "재사용 대기 중인 버튼 위를 쓸고 지나가는 음영."
L["The size of the entrance, flight master, boat and zeppelin symbols on the world map. They keep this size as you zoom."] = "세계 지도의 입구, 비행 조련사, 배, 비행선 아이콘 크기. 확대해도 이 크기를 유지합니다."
L["The skull, star and other raid markers just left of the bar."] = "막대 바로 왼쪽의 해골, 별 등 공격대 징표."
L["The slim health bar. The name, the health number and the power line sit outside it."] = "얇은 생명력 막대. 이름, 생명력 숫자, 자원 줄은 바깥에 있습니다."
L["The small tab on the meter's left edge (it shows while the mouse is near) slides it out or back by hand."] = "측정기 왼쪽 가장자리의 작은 탭 (마우스가 가까이 오면 표시)으로 측정기를 직접 꺼내거나 넣습니다."
L["The small tab that holds the name above the frame: its own border, corners, shadow, place and width."] = "개체창 위 이름이 들어가는 작은 탭: 고유의 테두리, 모서리, 그림자, 위치, 너비."
L["The small zone names over each group of quests."] = "각 퀘스트 묶음 위의 작은 지역 이름."
L["The soft light behind the model on the Character page."] = "캐릭터 페이지 모델 뒤의 은은한 빛."
L["The soft light behind the model on the Character page. When off, only the window's background shows."] = "캐릭터 페이지 모델 뒤의 은은한 빛. 끄면 창 배경만 보입니다."
L["The sound when someone whispers you. The first five are gentle chimes made for DaylightUI; picking one plays it once."] = "누군가 귓속말을 보낼 때의 소리. 처음 다섯 개는 DaylightUI를 위해 만든 부드러운 차임입니다. 하나를 고르면 한 번 재생합니다."
L["The space between the health bar and the power line under it."] = "생명력 막대와 그 아래 자원 줄 사이 간격."
L["The spell an enemy is casting, under its health bar."] = "적이 시전 중인 주문을 생명력 막대 아래에 표시합니다."
L["The spell being cast, as a small icon left of the cast bar."] = "시전 중인 주문을 시전바 왼쪽에 작은 아이콘으로."
L["The spell name and time on the cast bars. General uses the font on General > Appearance."] = "시전바의 주문 이름과 시간. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The spell name and time on your cast bar."] = "내 시전바의 주문 이름과 시간."
L["The spell name and time on your cast bar. General uses the font on General > Appearance."] = "내 시전바의 주문 이름과 시간. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The spell name and time on your focus's cast bar. General uses the font on General > Appearance."] = "주시 대상 시전바의 주문 이름과 시간. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The spell name and time on your focus's cast bar. Inside the frame it's kept small enough for the power bar."] = "주시 대상 시전바의 주문 이름과 시간. 개체창 안에서는 자원 막대에 맞게 작게 유지됩니다."
L["The spell name and time on your target's cast bar. General uses the font on General > Appearance."] = "대상 시전바의 주문 이름과 시간. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The spell name and time on your target's cast bar. Inside the frame it's kept small enough for the power bar, unless Text size inside the frame is set."] = "대상 시전바의 주문 이름과 시간. 개체창 안 텍스트 크기를 정하지 않으면, 개체창 안에서는 자원 막대에 맞게 작게 유지됩니다."
L["The spell name and timer on the target's cast bar."] = "대상 시전바의 주문 이름과 타이머."
L["The spell name and timer while the bar sits inside the target frame, even past the power bar's height. 0 uses Target cast bar text size, kept small enough for the power bar."] = "막대가 대상 개체창 안에 있을 때 자원 막대 높이를 넘더라도 쓰는 주문 이름과 타이머 크기. 0이면 대상 시전바 텍스트 크기를 자원 막대에 맞게 작게 씁니다."
L["The spell's icon at the end of your focus's cast bar. Not while it sits inside the frame."] = "주시 대상 시전바 끝의 주문 아이콘. 개체창 안에 있을 때는 제외."
L["The spell's icon at the end of your target's cast bar. Not while it sits inside the frame."] = "대상 시전바 끝의 주문 아이콘. 개체창 안에 있을 때는 제외."
L["The spell's name on every cast bar."] = "모든 시전바의 주문 이름."
L["The spell's own"] = "주문 고유"
L["The spell's own color (Renew green, a shield blue), or one you pick."] = "주문 고유의 색 (소생은 초록, 보호막은 파랑), 또는 직접 고른 색."
L["The spellbook and talent keys open DaylightUI's window. In a fight the game's own book opens, so you can still drag spells to your bars. Turn it off to always use the game's window."] = "마법책과 특성 단축키로 DaylightUI 창이 열립니다. 전투 중에는 게임 기본 마법책이 열려 여전히 주문을 단축바로 끌어 놓을 수 있습니다. 끄면 항상 게임 기본 창을 사용합니다."
L["The spellbook and talents, the profession windows, the professions book, the stable."] = "마법책과 특성, 전문 기술 창, 전문 기술 책, 야수 관리인."
L["The square minimap in the panel."] = "패널 안의 네모난 미니맵."
L["The square's color when Heal indicator color is Custom color."] = "치유 표시기 색상이 사용자 색상일 때 네모의 색상."
L["The stat group headers and the headers on the other pages. Each its own: a color per stat group, used in turn on the other pages."] = "능력치 묶음 머리글과 다른 페이지의 머리글. 각각 따로: 능력치 묶음마다 한 색씩, 다른 페이지에서는 차례로 사용합니다."
L["The sweep can't start in combat."] = "전투 중에는 빛 효과를 시작할 수 없습니다."
L["The swing timer's hand and time. General uses the font on General > Appearance."] = "자동 공격 타이머의 손과 시간. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["The tag after a PvP quest's title."] = "PvP 퀘스트 제목 뒤의 태그."
L["The tag after a dungeon quest's title."] = "던전 퀘스트 제목 뒤의 태그."
L["The tag after a raid quest's title."] = "공격대 퀘스트 제목 뒤의 태그."
L["The tag after an elite quest's title."] = "정예 퀘스트 제목 뒤의 태그."
L["The talents you're using now."] = "지금 사용 중인 특성."
L["The target and focus cast bars' color for a moment after their cast is interrupted."] = "대상과 주시 대상의 시전이 차단된 직후 잠시 쓰는 시전바 색상."
L["The target and focus cast bars' color while they cast."] = "대상과 주시 대상이 시전하는 동안의 시전바 색상."
L["The target and focus cast bars' color while they channel."] = "대상과 주시 대상이 정신 집중하는 동안의 시전바 색상."
L["The target's and target of target's class and power gradients run the other way, so they mirror yours. Only for a horizontal gradient."] = "대상과 대상의 대상의 직업 및 자원 그라데이션이 반대 방향으로 흘러 내 것과 거울처럼 보입니다. 가로 그라데이션에서만."
L["The text in DaylightUI's windows (character, spellbook, professions, bags, quest journal) and the game's windows it restyles. General uses the font above."] = "DaylightUI 창 (캐릭터, 마법책, 전문 기술, 가방, 퀘스트 일지)과 DaylightUI가 꾸미는 게임 창의 텍스트. 일반은 위의 글꼴을 사용합니다."
L["The textures above show on every bar at once, except where a frame's own page or the window bars below pick another. This puts every one of those back on the textures above."] = "위의 텍스처가 모든 막대에 한 번에 적용됩니다. 개체창 자체 페이지나 아래 창 막대에서 따로 고른 곳은 제외합니다. 이 버튼은 그런 곳을 모두 위의 텍스처로 되돌립니다."
L["The thin line under each header. Like the tab underline: whatever Tab underline below is set to. Class gradient uses your class's colors from the Gradients page."] = "각 머리글 아래의 얇은 줄. 탭 밑줄처럼, 아래 탭 밑줄 설정을 따릅니다. 직업 그라데이션은 그라데이션 페이지의 직업 색상을 사용합니다."
L["The thin power bar under the health bar."] = "생명력 막대 아래의 얇은 자원 막대."
L["The thin strip under the minimap with gold, gear, bag space and more."] = "미니맵 아래 골드, 장비, 가방 공간 등을 보여 주는 얇은 띠."
L["The threat bars' color when Bar color is One color."] = "막대 색상이 단색일 때의 위협 막대 색상."
L["The threat colors slowly brighten and dim, quicker when a mob is about to switch. Needs the health bar, border or glow above."] = "위협 색상이 천천히 밝아졌다 어두워지며, 몹이 대상을 바꾸려 할 때 더 빨라집니다. 위의 생명력 막대, 테두리 또는 광채가 필요합니다."
L["The tick next to a finished objective."] = "완료한 목표 옆의 체크 표시."
L["The time at the bottom of the minimap."] = "미니맵 아래쪽의 시간."
L["The time before each message (the game's own setting)."] = "각 메시지 앞의 시간 (게임 자체 설정)."
L["The time left as a number on each icon."] = "각 아이콘에 남은 시간을 숫자로."
L["The time left on a timed quest once it's under a minute."] = "시간제한 퀘스트의 남은 시간이 1분 미만일 때."
L["The time left on a timed quest."] = "시간제한 퀘스트의 남은 시간."
L["The time on every cast bar: what's left, what's left out of the whole cast, or nothing."] = "모든 시전바의 시간: 남은 시간, 전체 시전 중 남은 시간, 또는 표시 안 함."
L["The tint on a button while your target is out of range, when Out of range is set to Tint the icon."] = "대상이 사거리 밖일 때 버튼에 입히는 색 (사거리 밖이 아이콘에 색 입히기일 때)."
L["The tooltip text; titles are a little larger."] = "툴팁 텍스트. 제목은 조금 더 큽니다."
L["The top-right panel: experience bar on top, damage meter and minimap below. Move it in unlock mode."] = "오른쪽 위 패널: 위에는 경험치 막대, 아래에는 피해량 측정기와 미니맵. 잠금 해제 모드에서 옮길 수 있습니다."
L["The two ends of the bar's gradient. With Gradient off, the bar takes the bright end."] = "막대 그라데이션의 양 끝. 그라데이션을 끄면 밝은 쪽 색을 사용합니다."
L["The two-color fills bars use when set to a gradient (Class gradient on unit frames and nameplates, power bars)."] = "그라데이션으로 설정한 막대가 쓰는 두 색 채움 (개체창과 이름표의 직업 그라데이션, 자원 막대)."
L["The unit you set as focus."] = "주시 대상으로 지정한 대상."
L["The unit's health as text at the right end of the bar. Pick the format under Health text."] = "대상의 생명력을 막대 오른쪽 끝에 텍스트로. 형식은 생명력 텍스트에서 고르세요."
L["The unit's health written on this frame."] = "이 개체창에 적힌 대상의 생명력."
L["The unit's level at the left end of the bar, in the game's difficulty color; ?? for one far above you, + for an elite."] = "막대 왼쪽 끝의 대상 레벨을 게임 난이도 색상으로. 훨씬 높은 대상은 ??, 정예는 +."
L["The whole Bank and alts window, slots, text and buttons together."] = "은행 및 다른 캐릭터 창 전체: 칸, 텍스트, 버튼 모두."
L["The whole bag window, slots, text and buttons together."] = "가방 창 전체: 칸, 텍스트, 버튼 모두."
L["The whole bank window, slots, text and buttons together."] = "은행 창 전체: 칸, 텍스트, 버튼 모두."
L["The whole bar, icons, text and background together."] = "막대 전체: 아이콘, 텍스트, 배경 모두."
L["The whole feed. Also the mouse wheel over its handle in /dui unlock."] = "알림 전체. /dui unlock에서 손잡이 위로 마우스 휠을 굴려도 됩니다."
L["The whole group shows only during a fight."] = "전투 중에만 묶음 전체를 표시합니다."
L["The whole group shows only in a party or raid."] = "파티나 공격대에 있을 때만 묶음 전체를 표시합니다."
L["The whole pop-up, text and bar together."] = "팝업 전체: 텍스트와 막대 모두."
L["The window's title shows the player's last name after their first name."] = "창 제목에 플레이어의 이름 뒤에 성을 표시합니다."
L["The world map's quest list and quest pages in DaylightUI style, with Track, Share and Abandon on each quest. Turn it off to use the game's own."] = "세계 지도의 퀘스트 목록과 퀘스트 페이지를 DaylightUI 스타일로, 각 퀘스트에 추적, 공유, 포기 버튼과 함께. 끄면 게임 기본을 사용합니다."
L["The zone or area you're in, at the top of the map (above the coordinates)."] = "지도 위쪽 (좌표 위)에 현재 지역 또는 장소."
L["The zone or area you're in, at the top of the minimap."] = "미니맵 위쪽에 현재 지역 또는 장소."
L["Their health as text at the right end of the bar."] = "막대 오른쪽 끝에 생명력을 텍스트로."
L["Their keybinds work even when hidden. Move them in unlock mode."] = "숨겨져 있어도 단축키는 작동합니다. 잠금 해제 모드에서 옮길 수 있습니다."
L["Their level at the left end of the bar."] = "막대 왼쪽 끝에 레벨."
L["These are for talent set %s; each talent set keeps its own."] = "특성 세트 %s용입니다. 특성 세트마다 따로 저장됩니다."
L["These talents use the profile %s. Switch to it?"] = "이 특성은 %s 프로필을 사용합니다. 전환할까요?"
L["Thick"] = "두꺼움"
L["Thin"] = "얇음"
L["Thin lines split the bar into 20 parts, like the classic bar: each one is 5% of a level."] = "얇은 선이 막대를 클래식 막대처럼 20칸으로 나눕니다: 한 칸이 레벨의 5%입니다."
L["This Legacy tree isn't available yet."] = "이 유산 계통도는 아직 사용할 수 없습니다."
L["This bar's own name size. Text size, under Whole group, sizes every bar's."] = "이 막대 고유의 이름 크기. 묶음 전체의 텍스트 크기는 모든 막대의 크기를 정합니다."
L["This character"] = "이 캐릭터"
L["This character hasn't finished the setup guide, so moved frames go back when you log out. Type /dui install to finish it."] = "이 캐릭터는 설정 안내를 마치지 않아 옮긴 개체창이 접속 종료 시 되돌아갑니다. /dui install을 입력해 마치세요."
L["This character hasn't finished the setup guide, so what you change or move is lost when you log out. Finish the guide first, then make your changes."] = "이 캐릭터는 설정 안내를 마치지 않아 바꾸거나 옮긴 것이 접속 종료 시 사라집니다. 먼저 안내를 마친 뒤 변경하세요."
L["This character's, for the talent set in use. Covers your player, target, target of target, pet, focus, party and raid frames."] = "이 캐릭터의 사용 중인 특성 세트용. 플레이어, 대상, 대상의 대상, 소환수, 주시 대상, 파티, 공격대 개체창에 적용됩니다."
L["This client has no aura container; target auras are off."] = "이 클라이언트에는 효과 컨테이너가 없어 대상 효과를 끕니다."
L["This fight"] = "이번 전투"
L["This frame's health text and large number. General uses the font on General > Appearance."] = "이 개체창의 생명력 텍스트와 큰 숫자. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["This frame's names, and its level badge. General uses the font on General > Appearance."] = "이 개체창의 이름과 레벨 배지. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["This frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares."] = "이 개체창 고유의 생명력 색상으로 다른 개체창과 다르게 보이게 합니다. 색상 페이지와 동일을 고르면 모든 개체창이 공유하는 색상을 따릅니다."
L["This frame's own name color. Same as the Colors page follows the name color every frame shares."] = "이 개체창 고유의 이름 색상. 색상 페이지와 동일을 고르면 모든 개체창이 공유하는 이름 색상을 따릅니다."
L["This frame's own outline, corners and shadow, so it can stand apart from the rest of your UI."] = "이 개체창 고유의 외곽선, 모서리, 그림자로 UI의 나머지와 구별되게 합니다."
L["This frame's own power color. Same as the Colors page follows the color every frame shares."] = "이 개체창 고유의 자원 색상. 색상 페이지와 동일을 고르면 모든 개체창이 공유하는 색상을 따릅니다."
L["This frame's power text. General uses the font on General > Appearance."] = "이 개체창의 자원 텍스트. 일반은 일반 > 모양의 글꼴을 사용합니다."
L["This group's header. The other pages use the six colors in turn."] = "이 묶음의 머리글. 다른 페이지는 여섯 색을 차례로 사용합니다."
L["This icon's own size. Whole group, below, sizes every icon in the group."] = "이 아이콘 고유의 크기. 아래 묶음 전체는 묶음의 모든 아이콘 크기를 정합니다."
L["This level"] = "이번 레벨"
L["This session"] = "이번 접속"
L["This set hasn't been used yet. Activate it to spend its points."] = "이 세트는 아직 사용한 적이 없습니다. 활성화한 뒤 포인트를 사용하세요."
L["This setting"] = "이 설정"
L["This zone"] = "이 지역"
L["This zone only"] = "이 지역에서만"
L["Those quiet errors play one soft, low tick in place of the voice line, never in a burst. Follows Soft UI sounds (General > Sound)."] = "이런 조용한 오류는 음성 대신 부드럽고 낮은 틱 소리를 한 번만 냅니다. 연달아 울리지 않습니다. 부드러운 UI 소리 (일반 > 소리)를 따릅니다."
L["Threat"] = "위협"
L["Threat % tag"] = "위협 % 태그"
L["Threat Meter"] = "위협 측정기"
L["Threat bar gradient"] = "위협 막대 그라데이션"
L["Threat colors"] = "위협 색상"
L["Threat meter"] = "위협 측정기"
L["Threat meter rows"] = "위협 측정기 줄 수"
L["Threat: about to switch"] = "위협: 곧 바뀜"
L["Threat: as a glow"] = "위협: 광채로"
L["Threat: breathing pulse"] = "위협: 숨 쉬듯 깜빡임"
L["Threat: on the border"] = "위협: 테두리에"
L["Threat: on the health bar"] = "위협: 생명력 막대에"
L["Threat: switched"] = "위협: 바뀜"
L["Tiles per line"] = "한 줄당 타일 수"
L["Time"] = "시간"
