L["Under the bar (the cast bar moves down) or over it (the name moves up)."] = "막대 아래 (시전바가 아래로 이동) 또는 위 (이름이 위로 이동)."
L["Under the cast bar"] = "시전바 아래"
L["Under the frame (slides out)"] = "개체창 아래 (밀려 나옴)"
L["Under the frame it continues the frame's angle and slides out as you cast. Above the frame or on its own it has its own size."] = "개체창 아래에서는 개체창의 사선을 이어 가며 시전할 때 밀려 나옵니다. 개체창 위나 따로 있을 때는 고유 크기를 가집니다."
L["Under the frame, it continues the frame's angle. When off, its end is straight."] = "개체창 아래에서는 개체창의 사선을 이어 갑니다. 끄면 끝이 직선입니다."
L["Under the frame, or over it, clear of the name. The target's buffs or debuffs on that side move out of the way."] = "개체창 아래 또는 위, 이름과 겹치지 않게. 그쪽에 있는 대상의 강화 또는 약화 효과가 비켜납니다."
L["Under the meter"] = "측정기 아래"
L["Under the meter it rises out of the damage meter's bottom inside the panel, as wide as the meter, and the meter's rows make room. Docked (left or under), it shows only while the damage meter is open. Its own window goes anywhere: move it in unlock mode (/dui unlock) and drag its corner to size it."] = "측정기 아래에서는 패널 안 피해량 측정기 아래쪽에서 측정기 너비만큼 올라오고, 측정기 줄이 자리를 비켜 줍니다. 붙어 있을 때 (왼쪽 또는 아래)는 피해량 측정기가 열려 있을 때만 보입니다. 별도 창은 어디든 둘 수 있습니다: 잠금 해제 모드 (/dui unlock)에서 옮기고 모서리를 끌어 크기를 정하세요."
L["Under the meter it's part of the panel, with no window of its own."] = "측정기 아래에서는 별도 창 없이 패널의 일부가 됩니다."
L["Under the panel"] = "패널 아래"
L["Underline color"] = "밑줄 색상"
