L["Unlist"] = "등록 취소"
L["Unlock"] = "잠금 해제"
L["Unlock frames"] = "개체창 잠금 해제"
L["Unlocked. Drag to move, scroll to resize, right-click to put back, /dui lock when done."] = "잠금 해제됨. 끌어서 옮기고, 스크롤로 크기를 바꾸고, 오른쪽 클릭으로 되돌리세요. 다 되면 /dui lock."
L["Unpin"] = "고정 해제"
L["Untrack"] = "추적 해제"
