L["Up"] = "위로"
L["Up and Down scroll the text in a straight line. Arc bursts it out to the side and curves it up."] = "위로와 아래로는 텍스트를 직선으로 흘립니다. 부채꼴은 옆으로 터지듯 나와 위로 휘어집니다."
L["Up early. Even the murlocs are still asleep."] = "일찍 일어났군. 멀록들도 아직 자고 있는데."
L["Up to three, at the debuffs' size, with a countdown. They only appear when a boss uses them. With the game's buff frames shown, the game shows them there instead."] = "최대 세 개, 약화 효과 크기로 남은 시간과 함께. 우두머리가 사용할 때만 나타납니다. 게임 기본 강화 효과 창을 표시 중이면 게임이 대신 거기에 표시합니다."
L["Up to two big icons in the middle, with a sweep for the time left. They only appear when a boss uses them."] = "가운데에 큰 아이콘 최대 두 개, 남은 시간을 쓸고 지나가는 효과와 함께. 우두머리가 사용할 때만 나타납니다."
L["Up: newest at the bottom"] = "위로: 최신 줄이 아래"
L["Update"] = "갱신"
L["Usable glow color"] = "사용 가능 광채 색상"
L["Usable"] = "사용 가능"
L["Usage: /dui buffs toggle <category name>"] = "사용법: /dui buffs toggle <category name>"
L["Use"] = "사용"
L["Use DaylightUI's"] = "DaylightUI 것 사용"
