L["Use this"] = "이것 사용"
L["Use this font for the game's text"] = "게임 텍스트에 이 글꼴 사용"
L["Use this heal indicator"] = "이 치유 표시기 사용"
L["Used by all DaylightUI text, except where a frame's own page picks another font. Game font is the client's own, including a font you've replaced it with. Fonts other addons share (SharedMedia) are listed after ours."] = "개체창 자체 페이지에서 다른 글꼴을 고른 곳을 제외한 모든 DaylightUI 텍스트에 쓰입니다. 게임 글꼴은 클라이언트 자체 글꼴이며, 바꿔 넣은 글꼴도 포함합니다. 다른 애드온이 공유하는 글꼴 (SharedMedia)은 DaylightUI 글꼴 다음에 나열됩니다."
L["Used when Unit Frames > Extras > Combo points > Colors is a gradient: All points fills every pip with one pair, Point 1 to 5 give each pip its own."] = "개체창 > 추가 기능 > 연계 점수 > 색상이 그라데이션일 때 사용: 모든 점수는 모든 칸을 한 쌍으로 채우고, 점수 1~5는 칸마다 따로 색을 줍니다."
L["Uses the Raid 10 frames, and the rows below are grayed out. Turn it off to give this raid size its own, starting from a copy of Raid 10."] = "공격대 10 개체창을 사용하며 아래 줄은 회색으로 비활성화됩니다. 끄면 이 공격대 규모에 공격대 10을 복사한 것부터 시작하는 고유 설정을 줍니다."
L["Uses the game's own font in place of DaylightUI's fonts, which only have Latin letters. The options window changes after /reload."] = "라틴 문자만 있는 DaylightUI 글꼴 대신 게임 자체 글꼴을 사용합니다. 설정 창은 /reload 후 바뀝니다."
L["Usually General."] = "보통 공개."
