L["Vendors"] = "상인"
L["Vendors open in the NPC window too, with their goods on a shelf. Turn it off to use the game's vendor window."] = "상인도 NPC 창에서 열리며 물품이 진열대에 놓입니다. 끄면 게임 기본 상인 창을 사용합니다."
L["Version %s."] = "버전 %s."
