L["Wait for the talents being applied."] = "특성이 적용될 때까지 기다리세요."
L["Walking Boots"] = "보행용 장화"
L["Warmed by the fire"] = "모닥불에 몸을 녹였습니다"
L["Warlock"] = "흑마법사"
L["Warm bell"] = "따뜻한 종소리"
L["Warns you when a mob is about to change target, or has."] = "몹이 대상을 바꾸려 하거나 바꿨을 때 알려 줍니다."
