L["Web addresses in messages become links; click one to copy it."] = "메시지의 웹 주소가 링크가 됩니다. 클릭하면 복사합니다."
L["Website: %s"] = "웹사이트: %s"
L["Welcome"] = "환영합니다"
L["Went out"] = "나감"
L["What Alt-click on a quest in the tracker does."] = "추적기에서 퀘스트를 Alt-클릭했을 때의 동작."
L["What a button does while your target is out of range. Not enough mana, rage or energy does the same (blue when tinted)."] = "대상이 사거리 밖일 때 버튼의 동작. 마나, 분노, 기력이 부족할 때도 같습니다 (색을 입히면 파랑)."
L["What a click on a quest in the tracker does. Clicking its icon always makes it your priority, and right-click opens its menu."] = "추적기에서 퀘스트를 클릭했을 때의 동작. 아이콘을 클릭하면 항상 우선 퀘스트가 되고, 오른쪽 클릭은 메뉴를 엽니다."
L["What a friendly NPC does (Innkeeper, Flight Master...) under its name, smaller."] = "우호적인 NPC의 역할 (여관주인, 비행 조련사...)을 이름 아래에 작게."
L["What an NPC does (Skinner, Flight Master...) under its name, smaller. Not inside instances."] = "NPC의 역할 (무두장이, 비행 조련사...)을 이름 아래에 작게. 인스턴스 안에서는 표시하지 않습니다."
L["What an interrupted cast bar does: Blade slices it in two, Shatter breaks it into shards, Snap cracks it in the middle, Burn out burns the fill away, Rewind whips it back to empty, Shockwave bursts light from it, Fizzle lets its light leak out. Your own interrupts light up in your accent color. Point at a choice to see it on the preview."] = "차단된 시전바의 효과: 칼날은 둘로 베고, 산산조각은 파편으로 부수고, 꺾기는 가운데를 쪼개고, 연소는 채움을 태워 없애고, 되감기는 빈 상태로 되돌리고, 충격파는 빛을 터뜨리고, 피식은 빛이 새어 나가게 합니다. 내 차단은 강조 색상으로 빛납니다. 선택지에 마우스를 올리면 미리 보기에서 볼 수 있습니다."
L["What changed in each version."] = "버전별 변경 사항."
L["What changed in each version. Click a version to open or close it."] = "버전별 변경 사항. 버전을 클릭하면 열거나 닫습니다."
L["What each enemy plate shows on and around its bar, and its colors."] = "각 적 이름표가 막대 위와 주변에 표시하는 것과 그 색상."
L["What each item's icon shows in the Bank and alts window."] = "은행 및 다른 캐릭터 창에서 각 아이템 아이콘에 표시할 것."
L["What each item's icon shows in the bank."] = "은행에서 각 아이템 아이콘에 표시할 것."
L["What each item's icon shows."] = "각 아이템 아이콘에 표시할 것."
L["What each slot shows, left to right. The clock, framerate and coordinates are on the minimap too."] = "각 칸에 표시할 것 (왼쪽부터). 시계, 프레임률, 좌표는 미니맵에도 있습니다."
L["What happens to the fights you have so far when you enter a dungeon, raid or battleground: keep them, ask whether to reset, or reset at once. Running back after you die doesn't count."] = "던전, 공격대, 전장에 들어갈 때 지금까지의 전투 기록을 어떻게 할지: 유지, 초기화할지 묻기, 바로 초기화. 죽은 뒤 다시 달려오는 것은 포함되지 않습니다."
L["What happens to the fights you have so far when you join a group: keep them, ask whether to reset, or reset at once."] = "파티에 들어갈 때 지금까지의 전투 기록을 어떻게 할지: 유지, 초기화할지 묻기, 바로 초기화."
L["What it shows"] = "표시 내용"
L["What sits between the text's parts."] = "텍스트 부분 사이에 들어갈 것."
L["What the meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more. The button on the meter changes it too."] = "측정기가 보여 줄 것: 피해, 치유, 받은 피해, 차단, 무효화, 죽음 등. 측정기의 버튼으로도 바꿀 수 있습니다."
L["What the second meter lists: damage, healing, damage taken, interrupts, dispels, deaths and more."] = "두 번째 측정기가 보여 줄 것: 피해, 치유, 받은 피해, 차단, 무효화, 죽음 등."
L["What the target's or focus's cast bar does when its cast is interrupted. Your own interrupts light up in your accent color."] = "대상 또는 주시 대상의 시전이 차단됐을 때 시전바의 효과. 내 차단은 강조 색상으로 빛납니다."
L["What the tracker does when you enter a dungeon, raid or battleground. It comes back as you leave."] = "던전, 공격대, 전장에 들어갈 때 추적기의 동작. 나오면 돌아옵니다."
L["What this extra text shows first, like the name, the level or the guild."] = "이 추가 텍스트가 먼저 보여 줄 것 (이름, 레벨, 길드 등)."
L["What this group takes. Click to change."] = "이 묶음에 들어갈 것. 클릭해서 바꾸세요."
L["What this slot on the data text strip shows. Slots count from the left."] = "정보 텍스트 띠의 이 칸에 표시할 것. 칸은 왼쪽부터 셉니다."
L["What you loot and your skill-ups, sliding in as ribbons at the bottom right."] = "획득한 전리품과 기술 향상이 오른쪽 아래에 띠처럼 밀려 들어옵니다."
L["What you loot slides in at the bottom right of the screen in its quality color, more of the same adding to its count, and fades a few seconds later. Point at a line for the item's tooltip. Move it with /dui unlock."] = "획득한 전리품이 화면 오른쪽 아래에 품질 색상으로 밀려 들어오고, 같은 것은 개수가 더해지며, 몇 초 뒤 흐려집니다. 줄에 마우스를 올리면 아이템 툴팁이 나옵니다. /dui unlock으로 옮길 수 있습니다."
L["What's Training is still reading your spells."] = "What's Training이 아직 주문을 읽는 중입니다."
L["What's included"] = "포함 내용"
L["When Threat colors are on, they replace this color while showing."] = "위협 색상을 켜면 표시되는 동안 이 색을 대신합니다."
L["When a buff runs out, the spells after it slide over to fill its spot. When off, every spell keeps its place. A spell set to Keep its spot (Behavior tab) keeps it either way."] = "강화 효과가 끝나면 뒤의 주문이 밀려와 빈자리를 채웁니다. 끄면 모든 주문이 제자리를 지킵니다. 자리 유지 (행동 방식 탭)로 설정한 주문은 어느 쪽이든 자리를 지킵니다."
L["When a cast is interrupted, the bar stays full for a moment and says Interrupted."] = "시전이 차단되면 막대가 잠시 가득 찬 채 차단됨이라고 표시합니다."
L["When an NPC has only one thing to offer (a vendor, flight master, banker or trainer) and no quests, its window opens straight away. Hold Shift to see the dialogue."] = "NPC가 제공하는 것이 하나뿐이고 (상인, 비행 조련사, 은행원, 상급자) 퀘스트가 없으면 바로 해당 창이 열립니다. 대화를 보려면 Shift를 누르세요."
L["When auto loot is on, everything is picked up at once instead of one item at a time."] = "자동 획득이 켜져 있으면 한 개씩이 아니라 모두 한 번에 줍습니다."
L["When hovering a button shows its spell or item tooltip."] = "버튼에 마우스를 올렸을 때 주문 또는 아이템 툴팁을 표시하는 경우."
L["When it shows"] = "표시 시점"
L["When off, any debuff with a type (Magic, Curse, Disease, Poison) shows, even one you can't remove."] = "끄면 해제할 수 없는 것이라도 종류 (마법, 저주, 질병, 독)가 있는 약화 효과는 모두 표시합니다."
L["When off, the game's own bag windows are used."] = "끄면 게임 기본 가방 창을 사용합니다."
L["When off, the game's tracker stays where Edit Mode puts it."] = "끄면 게임 추적기가 편집 모드에서 정한 자리에 남습니다."
L["When ready"] = "준비되면"
L["When the accent color is a gradient (Daylight's or your class's), window borders run along it."] = "강조 색상이 그라데이션 (Daylight 또는 직업)일 때 창 테두리가 그 색을 따라 흐릅니다."
L["When the shown bag bar fades and how far."] = "표시된 가방 막대가 언제, 얼마나 흐려질지."
L["When the shown micro menu fades and how far."] = "표시된 메뉴 막대가 언제, 얼마나 흐려질지."
L["When to show"] = "표시 조건"
L["When you destroy a good item, the confirmation box is filled in. You still press the button."] = "좋은 아이템을 파괴할 때 확인 상자가 채워집니다. 버튼은 직접 누르세요."
L["When you dodge, parry or an attack misses you."] = "공격을 피하거나 막거나 공격이 빗나갔을 때."
L["When you go away, the world dims, the UI fades and your character stands beside a card with your name, zone, rested XP and a fun fact. Move, click or press any key to come back. Never in combat, boss fights, keystones or PvP matches."] = "자리를 비우면 세상이 어두워지고 UI가 흐려지며, 내 캐릭터가 이름, 지역, 휴식 경험치, 재미있는 정보가 적힌 카드 옆에 섭니다. 움직이거나 클릭하거나 아무 키나 누르면 돌아옵니다. 전투, 우두머리 전투, 쐐기돌, PvP 경기 중에는 작동하지 않습니다."
L["When you have forms"] = "변신 형태가 있을 때"
L["When you have totems"] = "토템이 있을 때"
L["When your next auto-attack lands: a bar for each hand you swing with."] = "다음 자동 공격이 들어갈 때: 공격하는 손마다 막대 하나."
L["Where \"Kicked by\" and the name show: beside the cast bar or under it."] = "\"차단한 사람\"과 이름이 표시될 곳: 시전바 옆 또는 아래."
L["Where along the frame the row starts: the angled end facing the middle of your screen, the middle, or the far end."] = "개체창을 따라 줄이 시작할 곳: 화면 가운데를 향한 사선 끝, 가운데, 또는 반대쪽 끝."
L["Where along the frame's top the tab sits. A full-width tab always starts at the outer end. Or drag the tab in Design mode."] = "개체창 위쪽에서 탭이 놓일 곳. 전체 너비 탭은 항상 바깥쪽 끝에서 시작합니다. 디자인 모드에서 탭을 끌어도 됩니다."
L["Where along the power bar the power text sits."] = "자원 막대에서 자원 텍스트가 놓일 곳."
L["Where new lines come in."] = "새 줄이 들어오는 곳."
L["Where on the button its key shows."] = "버튼에서 단축키가 표시될 곳."
L["Where on the frame this square sits."] = "개체창에서 이 네모가 놓일 곳."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text."] = "입력 상자가 나타날 곳. 패널 아래로 하면 대화창 아래에 띠를 남겨 두어 텍스트를 가리지 않습니다."
L["Where the dispel icon sits on each frame, or just outside it."] = "각 개체창에서 해제 아이콘이 놓일 곳 (안쪽 또는 바로 바깥)."
L["Where the interrupter's name shows: right of the cast bar or under it."] = "차단한 사람 이름이 표시될 곳: 시전바 오른쪽 또는 아래."
L["Where the leader crown sits on each frame, or just outside it."] = "각 개체창에서 공격대장 왕관이 놓일 곳 (안쪽 또는 바로 바깥)."
L["Where the name sits across the bar, while it's on the bar: left, center or right."] = "이름이 막대 위에 있을 때 막대를 가로질러 놓일 곳: 왼쪽, 가운데, 오른쪽."
L["Where the name sits across the bar: left, center or right."] = "이름이 막대를 가로질러 놓일 곳: 왼쪽, 가운데, 오른쪽."
L["Where the name sits inside its tab: left, center or right."] = "이름이 탭 안에서 놓일 곳: 왼쪽, 가운데, 오른쪽."
L["Where the numbers open when you hover the bar. Automatic opens them toward the middle of the screen."] = "막대에 마우스를 올렸을 때 숫자가 열리는 방향. 자동은 화면 가운데 쪽으로 엽니다."
L["Where the raid marker sits on each frame, or just outside it."] = "각 개체창에서 공격대 징표가 놓일 곳 (안쪽 또는 바로 바깥)."
L["Where the ready check answer sits on each frame, or just outside it."] = "각 개체창에서 전투 준비 응답이 놓일 곳 (안쪽 또는 바로 바깥)."
L["Where the role icon sits on each frame, or just outside it."] = "각 개체창에서 역할 아이콘이 놓일 곳 (안쪽 또는 바로 바깥)."
L["Where the role, marker, crown and dispel icons sit on a tile."] = "타일에서 역할, 징표, 왕관, 해제 아이콘이 놓일 곳."
L["Where things sit on your screen."] = "화면에서 각 요소가 놓일 곳."
L["Where this category sits on the bar."] = "막대에서 이 범주가 놓일 곳."
L["Where this extra text sits on the frame, or just outside it."] = "개체창에서 이 추가 텍스트가 놓일 곳 (안쪽 또는 바로 바깥)."
L["Where this group sits in the bag."] = "가방에서 이 묶음이 놓일 곳."
L["Where you put it"] = "내가 둔 곳"
L["Where your frames sit. Healers get the group as big tiles in the middle of the screen."] = "개체창이 놓일 곳. 치유 전담은 파티를 화면 가운데에 큰 타일로 봅니다."
L["Whether each raid group is a column, side by side, or a row, stacked down."] = "각 공격대 파티를 나란히 놓인 열로 할지, 아래로 쌓인 행으로 할지."
L["Whether the meter counts the fight you're in or every fight since the last reset."] = "측정기가 지금 전투를 셀지, 마지막 초기화 이후 모든 전투를 셀지."
L["Whether the name tab's end is cut at an angle. Same as the frame follows the frame's own end."] = "이름 탭 끝을 사선으로 자를지. 개체창과 동일은 개체창 끝을 따릅니다."
L["Whether the party frames stack down or line up across."] = "파티 개체창을 아래로 쌓을지, 가로로 늘어놓을지."
L["Whether the second meter counts the fight you're in or every fight since the last reset."] = "두 번째 측정기가 지금 전투를 셀지, 마지막 초기화 이후 모든 전투를 셀지."
L["Whether this extra group shows debuffs or buffs."] = "이 추가 묶음이 약화 효과를 보여 줄지, 강화 효과를 보여 줄지."
L["Whether your bars and your frame step aside when you're not fighting. Every part has its own Visible setting later."] = "전투 중이 아닐 때 단축바와 개체창이 비켜날지. 각 부분마다 나중에 가시성 설정이 따로 있습니다."
L["Which bar the rows below set."] = "아래 줄이 설정할 막대."
L["Which buffs show."] = "표시할 강화 효과."
L["Which buffs this group shows."] = "이 묶음이 표시할 강화 효과."
L["Which buttons the look rows on this page change. A bar keeps what you change for it; the rest follows All bars."] = "이 페이지의 모양 설정이 바꿀 버튼. 막대마다 바꾼 것은 유지되고, 나머지는 모든 막대를 따릅니다."
L["Which corner of the button its count shows in."] = "버튼에서 개수가 표시될 모서리."
L["Which debuffs show."] = "표시할 약화 효과."
L["Which debuffs this group shows."] = "이 묶음이 표시할 약화 효과."
L["Which end of the group stays put when a spell in it hides."] = "묶음의 주문이 숨겨질 때 고정될 끝."
L["Which frame the pips sit on."] = "칸이 놓일 개체창."
L["Which key accepts, continues and completes. Enter is also the key that opens chat."] = "수락, 계속, 완료에 쓸 키. Enter는 대화창을 여는 키이기도 합니다."
L["Which numbers"] = "표시할 숫자"
L["Which of the six squares the rows below set."] = "아래 줄이 설정할 네모 (여섯 개 중)."
L["Which part's fade the rows below set."] = "아래 줄이 흐려짐을 설정할 부분."
L["Which quest tracker?"] = "어느 퀘스트 추적기를 쓸까요?"
L["Which side of its owner's frame each pet bar sits on."] = "각 소환수 막대가 주인 개체창의 어느 쪽에 놓일지."
L["Which side of the list the quest item buttons sit on."] = "퀘스트 아이템 버튼이 목록의 어느 쪽에 놓일지."
L["Which stat groups start open. By class and spec: Attributes and the one that matters for you. Groups you open or fold yourself are remembered for each character."] = "처음에 펼쳐 둘 능력치 묶음. 직업과 전문화별: 능력치와 나에게 중요한 묶음. 직접 펼치거나 접은 묶음은 캐릭터마다 기억합니다."
L["Which way the color runs along a bar."] = "막대를 따라 색이 흐르는 방향."
L["Which way the row adds its icons, starting from its position."] = "줄이 시작 위치에서 아이콘을 추가하는 방향."
L["Which way the row of icons fills from its first icon."] = "아이콘 줄이 첫 아이콘부터 채워지는 방향."
L["While Heroic Strike, Cleave or Maul waits for your next swing, the melee bars change color and show its name."] = "영웅의 일격, 회전베기, 후려치기가 다음 공격을 기다리는 동안 근접 막대 색이 바뀌고 그 이름을 표시합니다."
L["While moving frames, edges and centers line up with other frames. Hold Shift to drop anywhere."] = "개체창을 옮길 때 가장자리와 중심이 다른 개체창에 맞춰집니다. 아무 곳에나 놓으려면 Shift를 누르세요."
L["While possessing"] = "빙의 중"
L["While swinging"] = "공격 중"
L["While swinging: each bar only while its swing runs, gone between swings. In combat: all your bars while you're fighting."] = "공격 중: 각 막대는 공격이 진행되는 동안만 보이고 공격 사이에는 사라집니다. 전투 중: 싸우는 동안 모든 막대를 표시합니다."
L["While the buff or debuff isn't up, it keeps its spot as a grayed icon or an empty bar, so you see what's missing."] = "강화 또는 약화 효과가 없는 동안 회색 아이콘이나 빈 막대로 자리를 지켜 무엇이 빠졌는지 보여 줍니다."
L["While the panel is away, how long each message stays before it fades. A new message doesn't bring old ones back. Move the mouse over the chat to see them all again."] = "패널이 숨겨진 동안 각 메시지가 흐려지기 전까지 남아 있는 시간. 새 메시지가 와도 이전 메시지는 돌아오지 않습니다. 대화창에 마우스를 올리면 모두 다시 보입니다."
L["While you cast, the power the spell will use is shaded on your power bar."] = "시전하는 동안 주문이 쓸 자원을 자원 막대에 음영으로 표시합니다."
L["While you have a bow, gun, crossbow, thrown weapon or wand."] = "활, 총, 석궁, 투척 무기, 마법봉을 들고 있을 때."
L["While you have a target, every other plate fades so your target stands out. A plate that starts casting comes back to full."] = "대상이 있는 동안 다른 이름표가 모두 흐려져 대상이 눈에 띕니다. 시전을 시작한 이름표는 다시 완전히 보입니다."
L["While you have a target, your target's plate and all other plates use the sizes below (relative to Width, Health bar height and Scale)."] = "대상이 있는 동안 대상 이름표와 다른 모든 이름표가 아래 크기를 사용합니다 (너비, 생명력 막대 높이, 크기에 대한 비율)."
L["While you have a weapon in your off hand."] = "보조장비에 무기를 들고 있을 때."
L["Whisper"] = "귓속말"
L["Whisper %s"] = "%s에게 귓속말"
L["Whisper color"] = "귓속말 색상"
L["Whisper sound"] = "귓속말 소리"
L["Whispered"] = "귓속말함"
L["Battle.net whispers"] = "Battle.net 귓속말"
L["Whispers"] = "귓속말"
L["Whispers from your Battle.net friends, and yours to them."] = "Battle.net 친구에게 받은 귓속말과 내가 보낸 귓속말."
L["Whispers in their own tab"] = "귓속말을 별도 탭에"
L["Whispers you get and send."] = "주고받는 귓속말."
L["White"] = "흰색"
L["White, the unit's class color, or one you pick."] = "흰색, 대상의 직업 색상, 또는 직접 고른 색."
L["Who"] = "누구"
L["Who a player or creature is targeting, in their color (\">> You <<\" when it's you)."] = "플레이어나 생물이 대상으로 잡고 있는 것을 그 색으로 (나일 때는 \">> 당신 <<\")."
L["Who interrupted position"] = "차단한 사람 위치"
L["Who to whisper?"] = "누구에게 귓속말할까요?"
L["Who your target is looking at."] = "대상이 바라보는 상대."
L["Who's closest to pulling your target, in a small window that slides out of the damage meter's left edge, along its bottom, or anywhere on its own."] = "대상의 어그로를 끌 가능성이 가장 높은 사람을, 피해량 측정기 왼쪽 가장자리나 아래쪽에서 밀려 나오는 작은 창, 또는 따로 어디에나 표시합니다."
L["Whole bar"] = "막대 전체"
L["Whole group"] = "묶음 전체"
L["Whole row in full color at max points"] = "최대 점수일 때 줄 전체를 최대 색상으로"
L["Width"] = "너비"
L["William Pestle"] = "윌리엄 페슬"
L["Window"] = "창"
L["Window background opacity"] = "창 배경 투명도"
L["Window bar background"] = "창 막대 배경"
L["Window bar texture"] = "창 막대 텍스처"
L["Window border"] = "창 테두리"
L["Window font"] = "창 글꼴"
L["Window height"] = "창 높이"
L["Window scale"] = "창 크기"
L["Windows"] = "창"
L["Windows glide in and out, tooltips fade in, a spell's icon pops when it's ready, gold and XP count up. When off, everything snaps into place."] = "창이 부드럽게 열리고 닫히며, 툴팁이 서서히 나타나고, 준비된 주문 아이콘이 튀어 오르고, 골드와 경험치가 올라갑니다. 끄면 모든 것이 바로 제자리에 놓입니다."
L["Windows open & close"] = "창 열기 및 닫기"
L["Wisdom"] = "지혜"
L["With Keep its spot (Buff missing), it shows only when you need to cast it, like Battle Shout."] = "자리 유지 (강화 효과 없음)와 함께 쓰면 전투의 외침처럼 시전해야 할 때만 표시합니다."
L["With a pet"] = "소환수가 있을 때"
L["With both on, it shows only when you're in a group and in combat. The second meter follows these too."] = "둘 다 켜면 파티 중이면서 전투 중일 때만 표시합니다. 두 번째 측정기도 이 설정을 따릅니다."
L["With chat open, Shift-click links the quest first."] = "대화창이 열려 있으면 Shift-클릭은 퀘스트 링크를 먼저 넣습니다."
L["With items in categories, stacks of the same item show as one, with the total. They show apart while you trade or have the mailbox or auction house open, so you can Shift-click one to split it."] = "아이템을 범주로 나누면 같은 아이템 묶음이 합계와 함께 하나로 보입니다. 거래 중이거나 우체통이나 경매장이 열려 있으면 따로 보여 Shift-클릭으로 나눌 수 있습니다."
L["With items in categories, your Soul Shards show as one, with how many you have, though each still takes its own slot."] = "아이템을 범주로 나누면 영혼의 조각이 개수와 함께 하나로 보입니다. 각각은 여전히 칸을 하나씩 차지합니다."
L["With no portrait and no name tab, the role, marker, crown and dispel icons sit in the frame's corners."] = "초상화와 이름 탭이 없으면 역할, 징표, 왕관, 해제 아이콘이 개체창 모서리에 놓입니다."
L["Withdraw"] = "찾기"
L["Withdraw gold"] = "골드 찾기"
L["Within each zone. Most recent progress moves a quest up when a kill, item or objective counts. Nearest first looks again every few seconds as you move, never in a fight or a dungeon. Nothing moves in a fight."] = "각 지역 안에서. 최근 진행은 처치, 아이템, 목표가 집계될 때 퀘스트를 위로 올립니다. 가까운 순은 움직이는 동안 몇 초마다 다시 확인하며, 전투나 던전에서는 하지 않습니다. 전투 중에는 아무것도 움직이지 않습니다."
L["Wood pop"] = "나무 소리"
L["World"] = "세계"
L["World map"] = "세계 지도"
L["World markers"] = "위치 표시기"
L["World of Warcraft"] = "월드 오브 워크래프트"
L["Wowhead link"] = "Wowhead 링크"
L["Wowhead link (Ctrl+C copies it):"] = "Wowhead 링크 (Ctrl+C로 복사):"
L["Wrists"] = "손목"
L["Write a letter..."] = "편지 쓰기..."
L["Write a note to list for %s."] = "%s 등록에 쓸 쪽지를 적으세요."
L["Write a subject."] = "제목을 적으세요."
L["Write the full name: first and last."] = "이름을 모두 적으세요: 이름과 성."
L["XP"] = "경험치"
L["XP bar"] = "경험치바"
L["XP bar position"] = "경험치바 위치"
L["XP bar, damage meter and a square minimap in one corner panel."] = "경험치바, 피해량 측정기, 네모난 미니맵을 한 구석 패널에."
L["XP gain effects"] = "경험치 획득 효과"
L["Yards under the arrow"] = "화살표 아래 거리 (미터)"
L["Yell color"] = "외침 색상"
L["Yes"] = "예"
L["You"] = "당신"
L["You block about 1 in %d attacks with your shield."] = "방패로 약 %d번 중 1번 공격을 막습니다."
L["You can also drag the chat's bottom-right corner to size it."] = "대화창 오른쪽 아래 모서리를 끌어 크기를 바꿀 수도 있습니다."
L["You can also switch with the button next to the search box."] = "검색 상자 옆 버튼으로도 전환할 수 있습니다."
L["You can make %d"] = "%d개 제작 가능"
L["You can reach rank %d this week"] = "이번 주에 %d등급까지 오를 수 있습니다"
L["You can track up to %d quests."] = "퀘스트를 최대 %d개까지 추적할 수 있습니다."
L["You can't parry yet."] = "아직 무기 막기를 할 수 없습니다."
L["You carry %s."] = "%s 소지 중."
L["You choose one of these:"] = "다음 중 하나를 선택합니다:"
L["You dodge about 1 in %d attacks."] = "약 %d번 중 1번 공격을 피합니다."
L["You don't block yet."] = "아직 방패 막기를 할 수 없습니다."
L["You don't dodge attacks yet."] = "아직 공격을 피할 수 없습니다."
L["You don't have that much gold."] = "골드가 부족합니다."
L["You get back %.0f mana every 5 seconds while not casting."] = "시전하지 않는 동안 5초마다 마나를 %.0f 회복합니다."
L["You keep"] = "유지"
L["You parry about 1 in %d attacks from the front."] = "정면 공격을 약 %d번 중 1번 무기 막기합니다."
L["You shoot every %.2f seconds. Lower is faster."] = "%.2f초마다 사격합니다. 낮을수록 빠릅니다."
L["You'll also get:"] = "추가로 받는 보상:"
L["You'll choose one of these:"] = "다음 중 하나를 선택하게 됩니다:"
L["You're in a group: the leader tools work for real. Leave the group to practice with sample members."] = "파티 중입니다: 공격대장 도구가 실제로 작동합니다. 예시 파티원으로 연습하려면 파티를 떠나세요."
L["You're in combat; this finishes as soon as it ends."] = "전투 중입니다. 전투가 끝나는 즉시 마무리됩니다."
L["You're not in a guild."] = "길드에 속해 있지 않습니다."
L["You're not in a raid."] = "공격대에 속해 있지 않습니다."
L["You've already learned talents this build doesn't have. A trainer can reset them."] = "이 구성에 없는 특성을 이미 배웠습니다. 상급자가 초기화해 줄 수 있습니다."
L["Your Legacy Points, their rewards, the challenges that earn them and the Legacy trees, in one window, in DaylightUI style."] = "유산 포인트, 그 보상, 포인트를 얻는 도전 과제, 유산 계통도를 한 창에서 DaylightUI 스타일로."
L["Your accent, when the accent color is set to Custom color."] = "강조 색상이 사용자 색상일 때의 강조 색상."
L["Your action bars and their buttons."] = "행동 단축바와 버튼."
L["Your attacks don't land critical hits yet."] = "아직 공격이 치명타로 적중하지 않습니다."
L["Your attacks and spells miss %.1f%% less often."] = "공격과 주문이 %.1f%% 덜 빗나갑니다."
L["Your bags are full."] = "가방이 가득 찼습니다."
L["Your bank from anywhere, and your other characters' bags and banks."] = "어디서든 은행과 다른 캐릭터의 가방 및 은행을."
L["Your bindings"] = "내 단축키"
L["Your buffs"] = "내 강화 효과"
L["Your buffs and debuffs."] = "내 강화 및 약화 효과."
L["Your buffs grow direction"] = "내 강화 효과 확장 방향"
L["Your buffs left / right"] = "내 강화 효과 좌 / 우"
L["Your buffs position"] = "내 강화 효과 위치"
L["Your buffs sorted into color-coded groups; debuffs edged by type."] = "내 강화 효과를 색으로 구분한 묶음으로 정리하고, 약화 효과는 종류별 테두리로."
L["Your buffs up / down"] = "내 강화 효과 위 / 아래"
L["Your buffs, minimap and info panel, quest tracker and chat fade away too, so only the fire and the world are left. Point at any of them to see it."] = "강화 효과, 미니맵과 정보 패널, 퀘스트 추적기, 대화창도 흐려져 모닥불과 세상만 남습니다. 아무거나 마우스를 올리면 보입니다."
L["Your buffs, sorted into colored categories. Right-click a buff to cancel it; shift-click to move it to another category. The bar sits beside the info panel; to move it, turn off Attach to the info panel."] = "내 강화 효과를 색으로 구분한 범주로 정리합니다. 오른쪽 클릭으로 강화 효과를 취소하고, Shift-클릭으로 다른 범주로 옮깁니다. 막대는 정보 패널 옆에 있으며, 옮기려면 정보 패널에 붙이기를 끄세요."
L["Your cast bar's color for a moment after your cast is interrupted."] = "내 시전이 차단된 직후 잠시 쓰는 시전바 색상."
L["Your cast bar's color while you cast."] = "내가 시전하는 동안의 시전바 색상."
L["Your cast bar's color while you channel."] = "내가 정신 집중하는 동안의 시전바 색상."
L["Your cast bar's colors"] = "내 시전바 색상"
L["Your casts and channels in your class color, or your class's gradient with a two-color fill. Not with the Daylight gradient."] = "내 시전과 정신 집중을 직업 색상으로, 두 색 채움이면 직업 그라데이션으로. Daylight 그라데이션과는 함께 쓸 수 없습니다."
L["Your character window: gear, model, stats and the other pages. It opens with C, as always."] = "캐릭터 창: 장비, 모델, 능력치, 다른 페이지. 언제나처럼 C로 엽니다."
L["Your chat also comes back the next time you log in on this character, under a gray line with when you left."] = "이 캐릭터로 다음에 접속할 때도 떠난 시각이 적힌 회색 줄 아래로 대화 내용이 돌아옵니다."
L["Your class"] = "내 직업"
L["Your class can heal; pick Healer if you do."] = "치유가 가능한 직업입니다. 치유를 한다면 치유 전담을 고르세요."
L["Your class's pick"] = "직업 추천"
L["Your class's pick follows your class on every character. Pick one to watch it instead."] = "직업 추천은 모든 캐릭터에서 직업을 따라갑니다. 대신 하나를 골라 지켜보세요."
L["Your damage over time spells: the end of the health they will still take is shaded darker."] = "지속 피해 주문: 앞으로 깎을 생명력의 끝부분을 더 어둡게 칠합니다."
L["Your damage over time spells: the end of the health they will still take is shaded darker. The color is on Unit Frames > Colors."] = "지속 피해 주문: 앞으로 깎을 생명력의 끝부분을 더 어둡게 칠합니다. 색상은 개체창 > 색상에 있습니다."
L["Your debuffs"] = "내 약화 효과"
L["Your debuffs, crowd control and buffs you can remove, on enemy plates."] = "적 이름표에 내 약화 효과, 군중 제어, 제거할 수 있는 강화 효과."
L["Your focus's cast bar fills from the right. Not while it sits inside the frame."] = "주시 대상 시전바가 오른쪽에서 채워집니다. 개체창 안에 있을 때는 제외."
L["Your focus's casts, while they last. It uses the target cast bar's colors."] = "주시 대상의 시전을 시전 중에만. 대상 시전바 색상을 사용합니다."
L["Your frame's own health color, so it can look unlike the others. Same as the Colors page follows the color every frame shares; Daylight gradient is the logo's blue to orange."] = "내 개체창 고유의 생명력 색상으로 다른 개체창과 다르게 보이게 합니다. 색상 페이지와 동일을 고르면 모든 개체창이 공유하는 색상을 따릅니다. Daylight 그라데이션은 로고의 파랑에서 주황입니다."
L["Your frames per second beside the clock."] = "시계 옆에 초당 프레임 수."
L["Your frames per second beside the clock. Hover it for latency, addon CPU and memory."] = "시계 옆에 초당 프레임 수. 마우스를 올리면 지연 시간, 애드온 CPU, 메모리를 봅니다."
L["Your friends, recent allies, friend requests and the raid, in one window, in DaylightUI style."] = "친구, 최근 동료, 친구 요청, 공격대를 한 창에서 DaylightUI 스타일로."
L["Your group is too big for a %d-player activity."] = "%d인 활동에는 파티 인원이 너무 많습니다."
L["Your guild's officer chat."] = "길드 관리자 대화."
L["Your heals over time and shields, everything you cast, or all of them. A class without heals sees everything it casts."] = "내 지속 치유와 보호막, 내가 시전한 모든 것, 또는 전부. 치유가 없는 직업은 시전한 모든 것을 봅니다."
L["Your health and mana come back faster while you're not fighting or casting."] = "전투나 시전을 하지 않는 동안 생명력과 마나가 더 빨리 회복됩니다."
L["Your health and power just under your character, the way Legion's personal display sat at your feet."] = "군단의 개인 자원 표시처럼 캐릭터 발밑에 생명력과 자원을."
L["Your health bar, your power under it and, for rogues and druids, your combo points, just under your character. It follows the camera as you zoom."] = "생명력 막대, 그 아래 자원, 도적과 드루이드는 연계 점수까지 캐릭터 바로 아래에. 카메라를 확대하거나 축소해도 따라갑니다."
L["Your health. Each point adds about 10; you have %.0f."] = "생명력. 1포인트마다 약 10씩 늘어납니다. 현재 %.0f."
L["Your last name after your first, at the top of the window."] = "창 위쪽에 이름 뒤에 성을 표시합니다."
L["Your letters, sending, and what you made through the mail and the auction house, in one window, in DaylightUI style."] = "편지, 보내기, 우편과 경매장으로 번 수익을 한 창에서 DaylightUI 스타일로."
L["Your listing"] = "내 등록"
L["Your main hand swings every %.2f seconds. Lower is faster."] = "주장비가 %.2f초마다 공격합니다. 낮을수록 빠릅니다."
L["Your mana, rage or energy under the health bar."] = "생명력 막대 아래에 마나, 분노, 기력."
L["Your melee attacks hit harder: Strength adds attack power."] = "근접 공격이 더 강해집니다: 힘이 전투력을 올립니다."
L["Your own buffs and heals over time, in a row above the name."] = "내 강화 효과와 지속 치유를 이름 위에 한 줄로."
L["Your own color"] = "직접 고른 색상"
L["Your own cooldown layout: every spell the Cooldown Manager tracks as an icon or a bar, placed where you like and snapped together. One layout per talent set, for this character."] = "나만의 재사용 대기시간 배치: 재사용 대기시간 관리자가 추적하는 모든 주문을 아이콘이나 막대로 원하는 곳에 두고 서로 맞붙입니다. 이 캐릭터의 특성 세트마다 배치 하나."
L["Your own frame sits with the party's. When off, only the rest of the party shows."] = "내 개체창을 파티와 함께 둡니다. 끄면 나머지 파티원만 표시합니다."
L["Your own frame."] = "내 개체창."
L["Your own groups"] = "내 묶음"
L["Your own layout on this character. When off, this character's spells show where the game puts them, still in DaylightUI's look. Saved for this character."] = "이 캐릭터의 내 배치. 끄면 이 캐릭터의 주문이 게임이 정한 곳에 DaylightUI 모양으로 표시됩니다. 이 캐릭터에 저장됩니다."
L["Your own tile sits with the raid's. When off, only the rest of the raid shows."] = "내 타일을 공격대와 함께 둡니다. 끄면 나머지 공격대원만 표시합니다."
L["Your party and raid as square tiles under you, dispels easy to spot."] = "내 아래에 파티와 공격대를 네모난 타일로, 해제할 것이 잘 보이게."
L["Your party: bars like your own frame, or square tiles. Set how they line up, what shows, and move them as one in unlock mode."] = "파티: 내 개체창 같은 막대 또는 네모난 타일. 정렬 방식과 표시 내용을 정하고, 잠금 해제 모드에서 한꺼번에 옮기세요."
L["Your pet"] = "내 소환수"
L["Your pet or minion."] = "내 소환수 또는 하수인."
L["Your pet's damage"] = "소환수 피해"
L["Your pet's or totem's hits too."] = "소환수나 토템의 공격도."
L["Your picks are saved into %s."] = "선택한 내용이 %s에 저장됩니다."
L["Your portrait ring, or your name tab without a portrait, turns red while you're in combat."] = "전투 중에는 초상화 고리 (초상화가 없으면 이름 탭)가 빨갛게 바뀝니다."
L["Your priority quest is the one the marker and arrow lead to."] = "우선 퀘스트는 표시와 화살표가 안내하는 퀘스트입니다."
L["Your profession's recipes in one window, in DaylightUI style."] = "전문 기술 제조법을 한 창에서 DaylightUI 스타일로."
L["Your quest tracker."] = "내 퀘스트 추적기."
