L["Tile size"] = "타일 크기"
L["Trade"] = "거래"
L["Unlock the chat's size"] = "대화창 크기 잠금 해제"
L["What the away message says."] = "자리 비움 메시지의 내용."
L["When someone writes your name where people talk, it lights up in your accent color and the tab it lands in glows."] = "누군가 대화하는 곳에서 내 이름을 쓰면 강조 색상으로 빛나고, 그 메시지가 들어간 탭도 빛납니다."
L["When the away message answers."] = "자리 비움 메시지가 답장하는 때."
L["Where the box you type in appears. Under the panel keeps a strip below the chat for it, so it never covers any text. At the bottom, the Daylight chat box lifts its messages over the box while you type."] = "입력창이 나타나는 곳. 패널 아래는 대화창 아래에 입력창 자리를 두어 글을 가리지 않습니다. 아래쪽이면 Daylight 대화창이 입력하는 동안 메시지를 입력창 위로 올립니다."
L["Whisper tiles"] = "귓속말 타일"
L["Whisper tiles show"] = "귓속말 타일 표시"
L["Whispers are part of the Daylight chat box: /dui chat daylight to use it."] = "귓속말은 Daylight 대화창의 기능입니다. 사용하려면 /dui chat daylight."
L["Whispers open on the"] = "귓속말이 열리는 쪽"
L["Whispers show in"] = "귓속말 표시 위치"
L["With the chat input at the bottom: while you type, the messages slide up and the box you type in sits under them, so it never covers a line."] = "입력창이 아래쪽일 때: 입력하는 동안 메시지가 위로 올라가고 입력창이 그 아래에 놓여 어떤 줄도 가리지 않습니다."
L["Words to light up"] = "강조할 단어"
L["Words to light up, separated by commas"] = "강조할 단어, 쉼표로 구분"
L["XP, reputation and skills"] = "경험치, 평판, 기술"
L["not a table"] = "테이블이 아님"
L["show"] = "보기"
L["A bar of its own for the faction you're watching. While it's on, the experience bar no longer turns to reputation when you gain some."] = "주시 중인 진영을 위한 별도의 막대입니다. 켜져 있으면 평판을 얻을 때 경험치 막대가 더 이상 평판으로 바뀌지 않습니다."
L["Game window skins"] = "게임 창 스킨"
L["How far through the standing you are, e.g. 60%."] = "현재 관계에서 얼마나 진행했는지입니다. 예: 60%."
L["How tall the reputation bar is."] = "평판 막대의 높이입니다."
L["How wide the reputation bar is. Dragging its corner in unlock mode sets this too."] = "평판 막대의 너비입니다. 잠금 해제 모드에서 모서리를 끌어도 설정됩니다."
L["More windows"] = "다른 창"
L["Reputation Bar"] = "평판 막대"
L["Reputation bar"] = "평판 막대"
L["Reputation bar gradient"] = "평판 막대 그라데이션"
L["Reputation bar height"] = "평판 막대 높이"
L["Reputation bar width"] = "평판 막대 너비"
L["Reputation details position"] = "평판 상세 정보 위치"
L["Reputation text size"] = "평판 텍스트 크기"
L["Show a separate reputation bar"] = "별도 평판 막대 표시"
L["Show reputation as text"] = "평판을 텍스트로 표시"
L["Show reputation percent"] = "평판 퍼센트 표시"
L["Show the faction's name"] = "진영 이름 표시"
L["Size of the text on the reputation bar. Its font is the experience bar's."] = "평판 막대 텍스트의 크기입니다. 글꼴은 경험치 막대와 같습니다."
L["Spellbook, inspect, professions, group finder, mailbox, social and Legacy: each window's switch, its size and its own extras."] = "마법책, 살펴보기, 전문 기술, 파티 찾기, 우체통, 소셜, 유산: 창마다 스위치, 크기, 추가 기능."
L["The bar shades from dark to bright in its standing's colors, editable on the Gradients page."] = "막대가 관계의 색으로 어두운 색에서 밝은 색으로 바뀝니다. 그라데이션 페이지에서 편집할 수 있습니다."
L["The faction's name on the bar."] = "막대 위의 진영 이름입니다."
L["The numbers on the bar, e.g. 1,800 / 3,000."] = "막대 위의 숫자입니다. 예: 1,800 / 3,000."
L["The reputation you're watching, always, on its own bar. Pick the faction on the Reputation page of the character window. Move it in unlock mode; drag its corner to resize."] = "주시 중인 평판을 항상 별도의 막대에 표시합니다. 진영은 캐릭터 창의 평판 페이지에서 고릅니다. 잠금 해제 모드에서 옮기고, 모서리를 끌어 크기를 바꿉니다."
L["Welcome back, %s"] = "다시 오신 것을 환영합니다, %s"
